    #[test]
    fn test_select_v128_i32_mul_scalarizes_with_sse2_flag() {
        let (mut isel, entry) = make_empty_isel();
        isel.set_scalarize_v4i32_imul_with_sse2(true);
        define_vreg(&mut isel, Value(0), Type::V128);
        define_vreg(&mut isel, Value(1), Type::V128);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Imul,
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();

        assert_eq!(isel.value_type(&Value(2)), Type::V128);
        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        let count = |opcode| insts.iter().filter(|inst| inst.opcode == opcode).count();

        assert_eq!(count(X86Opcode::Pmulld), 0);
        assert_eq!(count(X86Opcode::Pmuludq), 2);
        assert_eq!(count(X86Opcode::Pshufd), 4);
        assert_eq!(count(X86Opcode::Punpckldq), 1);
        assert_eq!(count(X86Opcode::ImulRR), 0);
        assert_eq!(count(X86Opcode::MovdFromXmm), 0);
        assert_eq!(count(X86Opcode::MovdToXmm), 0);
        assert_eq!(count(X86Opcode::Punpcklqdq), 0);
        let shuffle_imms = insts
            .iter()
            .filter(|inst| inst.opcode == X86Opcode::Pshufd)
            .filter_map(|inst| inst.operands.get(2))
            .collect::<Vec<_>>();
        assert_eq!(
            shuffle_imms,
            vec![
                &X86ISelOperand::Imm(0xF5),
                &X86ISelOperand::Imm(0xF5),
                &X86ISelOperand::Imm(0x88),
                &X86ISelOperand::Imm(0x88),
            ]
        );
        assert!(matches!(
            insts.last().and_then(|inst| inst.operands.first()),
            Some(X86ISelOperand::VReg(vreg)) if vreg.class == RegClass::Fpr128
        ));
    }

