    #[test]
    fn test_select_arithmetic_rejects_mismatched_v128_operands() {
        let (mut isel, entry) = make_empty_isel();
        define_vreg(&mut isel, Value(0), Type::V128);
        define_vreg(&mut isel, Value(1), Type::I64);

        let err = isel
            .select_instruction(
                &Instruction {
                    opcode: Opcode::Iadd,
                    args: vec![Value(0), Value(1)],
                    results: vec![Value(2)],
                },
                entry,
            )
            .unwrap_err();

        assert!(
            matches!(err, X86ISelError::UnsupportedOpcode(ref message)
                if message.contains("Arithmetic lhs=V128 rhs=I64")),
            "unexpected vector arithmetic error: {err:?}"
        );
        assert!(isel.func.blocks[&entry].insts.is_empty());
    }

    fn v4i32_mask_const_stack_sequence(lane_imms: [i64; 4]) -> Vec<Instruction> {
        v4i32_mask_const_stack_sequence_with_ids(0, 10, 20, 1, lane_imms)
    }

    fn v4i32_mask_const_stack_sequence_with_ids(
        slot: u32,
        base: u32,
        lane_value_start: u32,
        result: u32,
        lane_imms: [i64; 4],
    ) -> Vec<Instruction> {
        let mut instructions = vec![Instruction {
            opcode: Opcode::StackAddr { slot },
            args: vec![],
            results: vec![Value(base)],
        }];

        for (lane, lane_imm) in lane_imms.into_iter().enumerate() {
            let lane_value_base = lane_value_start + lane as u32 * 3;
            instructions.push(Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I64,
                    imm: lane as i64,
                },
                args: vec![],
                results: vec![Value(lane_value_base)],
            });
            instructions.push(Instruction {
                opcode: Opcode::ArrayGep { elem_ty: Type::I32 },
                args: vec![Value(base), Value(lane_value_base)],
                results: vec![Value(lane_value_base + 1)],
            });
            instructions.push(Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I32,
                    imm: lane_imm,
                },
                args: vec![],
                results: vec![Value(lane_value_base + 2)],
            });
            instructions.push(Instruction {
                opcode: Opcode::Store {
                    ty: Type::I32,
                    align: None,
                },
                args: vec![Value(lane_value_base + 2), Value(lane_value_base + 1)],
                results: vec![],
            });
        }

        instructions.push(Instruction {
            opcode: Opcode::Load {
                ty: Type::V128,
                align: None,
            },
            args: vec![Value(base)],
            results: vec![Value(result)],
        });
        instructions
    }

    fn narrow_bool_mask_const_stack_sequence_with_ids(
        slot: u32,
        base: u32,
        lane_value_start: u32,
        result: u32,
        elem_ty: Type,
        lane_imms: &[i64],
    ) -> Vec<Instruction> {
        let mut instructions = vec![Instruction {
            opcode: Opcode::StackAddr { slot },
            args: vec![],
            results: vec![Value(base)],
        }];

        for (lane, imm) in lane_imms.iter().copied().enumerate() {
            let lane_value_base = lane_value_start + lane as u32 * 3;
            instructions.push(Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I64,
                    imm: lane as i64,
                },
                args: vec![],
                results: vec![Value(lane_value_base)],
            });
            instructions.push(Instruction {
                opcode: Opcode::ArrayGep {
                    elem_ty: elem_ty.clone(),
                },
                args: vec![Value(base), Value(lane_value_base)],
                results: vec![Value(lane_value_base + 1)],
            });
            instructions.push(Instruction {
                opcode: Opcode::Iconst {
                    ty: elem_ty.clone(),
                    imm,
                },
                args: vec![],
                results: vec![Value(lane_value_base + 2)],
            });
            instructions.push(Instruction {
                opcode: Opcode::Store {
                    ty: elem_ty.clone(),
                    align: None,
                },
                args: vec![Value(lane_value_base + 2), Value(lane_value_base + 1)],
                results: vec![],
            });
        }

        instructions.push(Instruction {
            opcode: Opcode::Load {
                ty: Type::V128,
                align: None,
            },
            args: vec![Value(base)],
            results: vec![Value(result)],
        });
        instructions
    }

    fn v4i32_insert_stack_sequence(
        slot: u32,
        base: u32,
        vector: u32,
        elem: u32,
        lane: i64,
        result: u32,
    ) -> Vec<Instruction> {
        vec![
            Instruction {
                opcode: Opcode::StackAddr { slot },
                args: vec![],
                results: vec![Value(base)],
            },
            Instruction {
                opcode: Opcode::Store {
                    ty: Type::V128,
                    align: None,
                },
                args: vec![Value(vector), Value(base)],
                results: vec![],
            },
            Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I64,
                    imm: lane,
                },
                args: vec![],
                results: vec![Value(base + 1)],
            },
            Instruction {
                opcode: Opcode::ArrayGep { elem_ty: Type::I32 },
                args: vec![Value(base), Value(base + 1)],
                results: vec![Value(base + 2)],
            },
            Instruction {
                opcode: Opcode::Store {
                    ty: Type::I32,
                    align: None,
                },
                args: vec![Value(elem), Value(base + 2)],
                results: vec![],
            },
            Instruction {
                opcode: Opcode::Load {
                    ty: Type::V128,
                    align: None,
                },
                args: vec![Value(base)],
                results: vec![Value(result)],
            },
        ]
    }

    fn v4i32_mask_lanes_from_bits(bits: u8) -> [i64; 4] {
        std::array::from_fn(|lane| {
            if bits & (1_u8 << lane) != 0 {
                if bits & 1 == 0 {
                    i64::from(u32::MAX)
                } else {
                    -1
                }
            } else {
                0
            }
        })
    }

    fn expected_v4i32_mask_shuffle_imm(bits: u8) -> i64 {
        (0..4).fold(0_i64, |imm, lane| {
            let selector = if bits & (1_u8 << lane) != 0 { 0 } else { 1 };
            imm | (selector << (lane * 2))
        })
    }

    #[test]
    fn test_select_block_v4i32_all_zero_and_all_ones_constants_use_self_ops() {
        for (lane_imm, expected_opcode) in [
            (0, X86Opcode::Pxor),
            (-1, X86Opcode::Pcmpeqd),
            (i64::from(u32::MAX), X86Opcode::Pcmpeqd),
        ] {
            let (mut isel, entry) = make_empty_isel();
            isel.set_stack_slots(vec![StackSlotInfo::new(16, 16)]);

            isel.select_block(entry, &v4i32_mask_const_stack_sequence([lane_imm; 4]))
                .unwrap();

            let insts = &isel.func.blocks[&entry].insts;
            assert_eq!(insts.len(), 1, "{lane_imm}");
            assert_eq!(insts[0].opcode, expected_opcode, "{lane_imm}");
            assert_eq!(insts[0].operands.len(), 2);
            assert_eq!(insts[0].operands[0], insts[0].operands[1]);
            assert!(matches!(
                insts[0].operands[0],
                X86ISelOperand::VReg(VReg {
                    class: RegClass::Fpr128,
                    ..
                })
            ));
            assert_eq!(isel.value_types[&Value(1)], Type::V128);
            assert!(
                insts.iter().all(|inst| !matches!(
                    inst.opcode,
                    X86Opcode::Lea
                        | X86Opcode::LeaSib
                        | X86Opcode::MovdquMR
                        | X86Opcode::MovdquRM
                        | X86Opcode::MovMR32
                        | X86Opcode::MovRM32
                        | X86Opcode::MovRI
                )),
                "direct constant materialization must avoid stack/lane scaffolding: {insts:?}"
            );
        }
    }

    #[test]
    fn test_select_block_v4i32_mixed_mask_constants_use_movd_pshufd() {
        for bits in 1_u8..15 {
            let (mut isel, entry) = make_empty_isel();
            isel.set_stack_slots(vec![StackSlotInfo::new(16, 16)]);

            isel.select_block(
                entry,
                &v4i32_mask_const_stack_sequence(v4i32_mask_lanes_from_bits(bits)),
            )
            .unwrap();

            let insts = &isel.func.blocks[&entry].insts;
            assert_eq!(insts.len(), 3, "{bits:04b}");
            assert_eq!(insts[0].opcode, X86Opcode::MovRI, "{bits:04b}");
            assert_eq!(insts[1].opcode, X86Opcode::MovdToXmm, "{bits:04b}");
            assert_eq!(insts[2].opcode, X86Opcode::Pshufd, "{bits:04b}");
            assert_eq!(insts[0].operands[1], X86ISelOperand::Imm(-1), "{bits:04b}");
            assert_eq!(insts[1].operands[1], insts[0].operands[0], "{bits:04b}");
            assert_eq!(insts[2].operands[1], insts[1].operands[0], "{bits:04b}");
            assert_eq!(
                insts[2].operands[2],
                X86ISelOperand::Imm(expected_v4i32_mask_shuffle_imm(bits)),
                "{bits:04b}"
            );
            assert!(matches!(
                insts[0].operands[0],
                X86ISelOperand::VReg(VReg {
                    class: RegClass::Gpr32,
                    ..
                })
            ));
            assert!(matches!(
                insts[1].operands[0],
                X86ISelOperand::VReg(VReg {
                    class: RegClass::Fpr128,
                    ..
                })
            ));
            assert!(matches!(
                insts[2].operands[0],
                X86ISelOperand::VReg(VReg {
                    class: RegClass::Fpr128,
                    ..
                })
            ));
            assert_eq!(isel.value_types[&Value(1)], Type::V128);
            assert!(
                insts.iter().all(|inst| !matches!(
                    inst.opcode,
                    X86Opcode::Lea
                        | X86Opcode::LeaSib
                        | X86Opcode::MovdquMR
                        | X86Opcode::MovdquRM
                        | X86Opcode::MovMR32
                        | X86Opcode::MovRM32
                )),
                "mixed mask materialization must avoid stack/lane scaffolding: {insts:?}"
            );
        }
    }

    #[test]
    fn test_select_block_v4i32_non_mask_constant_uses_generic_stack_path() {
        let (mut isel, entry) = make_empty_isel();
        isel.set_stack_slots(vec![StackSlotInfo::new(16, 16)]);

        isel.select_block(entry, &v4i32_mask_const_stack_sequence([-1, 1, 0, 0]))
            .unwrap();

        let insts = &isel.func.blocks[&entry].insts;
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == X86Opcode::MovMR32)
                .count(),
            4
        );
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == X86Opcode::MovdquRM)
                .count(),
            1
        );
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == X86Opcode::Pshufd)
                .count(),
            0
        );
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == X86Opcode::MovdToXmm)
                .count(),
            0
        );
    }

    fn v2i64_const_stack_sequence(lane_imms: [i64; 2]) -> Vec<Instruction> {
        let mut instructions = vec![Instruction {
            opcode: Opcode::StackAddr { slot: 0 },
            args: vec![],
            results: vec![Value(10)],
        }];

        for (lane, lane_imm) in lane_imms.into_iter().enumerate() {
            let lane_value_base = 20 + lane as u32 * 3;
            instructions.push(Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I64,
                    imm: lane as i64,
                },
                args: vec![],
                results: vec![Value(lane_value_base)],
            });
            instructions.push(Instruction {
                opcode: Opcode::ArrayGep { elem_ty: Type::I64 },
                args: vec![Value(10), Value(lane_value_base)],
                results: vec![Value(lane_value_base + 1)],
            });
            instructions.push(Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I64,
                    imm: lane_imm,
                },
                args: vec![],
                results: vec![Value(lane_value_base + 2)],
            });
            instructions.push(Instruction {
                opcode: Opcode::Store {
                    ty: Type::I64,
                    align: None,
                },
                args: vec![Value(lane_value_base + 2), Value(lane_value_base + 1)],
                results: vec![],
            });
        }

        instructions.push(Instruction {
            opcode: Opcode::Load {
                ty: Type::V128,
                align: None,
            },
            args: vec![Value(10)],
            results: vec![Value(1)],
        });
        instructions
    }

