    #[test]
    fn test_select_block_v2i64_all_ones_constant_uses_pcmpeqd() {
        let (mut isel, entry) = make_empty_isel();
        isel.set_stack_slots(vec![StackSlotInfo::new(16, 16)]);

        isel.select_block(entry, &v2i64_const_stack_sequence([-1, -1]))
            .unwrap();

        let insts = &isel.func.blocks[&entry].insts;
        assert_eq!(insts.len(), 1);
        assert_eq!(insts[0].opcode, X86Opcode::Pcmpeqd);
        assert_eq!(insts[0].operands[0], insts[0].operands[1]);
        assert_eq!(isel.value_types[&Value(1)], Type::V128);
        assert!(
            insts.iter().all(|inst| !matches!(
                inst.opcode,
                X86Opcode::Lea
                    | X86Opcode::LeaSib
                    | X86Opcode::MovdquMR
                    | X86Opcode::MovdquRM
                    | X86Opcode::MovMR
                    | X86Opcode::MovRM
                    | X86Opcode::MovRI
                    | X86Opcode::MovqToXmm
                    | X86Opcode::Pinsrq
            )),
            "all-ones qword vector should use one self compare: {insts:?}"
        );
    }

    /// Regression: the store-drop class caught on real x86 hardware
    /// (2026-07-31, `v2i64_ne_boundary_masks`). A `V2I64Icmp { NotEqual }`
    /// materializes the block's cached all-ones `PCMPEQD` first; the
    /// subsequent all-ones const-stack sequence (with its two effectful I64
    /// lane stores) is then intercepted and REUSES the cached mask, emitting
    /// no machine instruction at its own anchor. Without a fusion edge from
    /// the anchor to the compare source, the lane stores chain to an
    /// emission-free anchor and TV-3 fails the compile as a dropped store.
    #[test]
    fn test_select_block_v2i64_all_ones_after_ne_compare_links_cached_mask_witness() {
        let (mut isel, entry) = make_empty_isel();
        isel.set_stack_slots(vec![StackSlotInfo::new(16, 16)]);
        define_vreg(&mut isel, Value(200), Type::V128);
        define_vreg(&mut isel, Value(201), Type::V128);

        let mut instructions = vec![Instruction {
            opcode: Opcode::V2I64Icmp {
                cond: IntCC::NotEqual,
            },
            args: vec![Value(200), Value(201)],
            results: vec![Value(2)],
        }];
        let const_anchor = instructions.len() as u32;
        instructions.extend(v2i64_const_stack_sequence([-1, -1]));
        // Lane stores sit at fixed offsets inside the 10-instruction
        // const-stack sequence: [StackAddr, Iconst, ArrayGep, Iconst, Store,
        // Iconst, ArrayGep, Iconst, Store, Load].
        let lane_store_indices = [const_anchor + 4, const_anchor + 8];

        isel.select_block(entry, &instructions).unwrap();

        let insts = &isel.func.blocks[&entry].insts;
        assert_eq!(
            insts.iter().map(|inst| inst.opcode).collect::<Vec<_>>(),
            vec![X86Opcode::Pcmpeqq, X86Opcode::Pcmpeqd, X86Opcode::Pxor],
            "NE compare emits the cached all-ones; the const sequence must reuse it: {insts:?}"
        );
        assert_eq!(isel.value_types[&Value(1)], Type::V128);
        assert_eq!(
            isel.func.source_fusion_target(SourceInstId {
                block: entry.0,
                index: const_anchor,
            }),
            Some(SourceInstId {
                block: entry.0,
                index: 0,
            }),
            "the emission-free all-ones reuse must link its anchor to the \
             compare source that emitted the cached PCMPEQD"
        );
        for store_index in lane_store_indices {
            assert_eq!(
                isel.func.source_fusion_target(SourceInstId {
                    block: entry.0,
                    index: store_index,
                }),
                Some(SourceInstId {
                    block: entry.0,
                    index: const_anchor,
                }),
                "each consumed lane store must chain to the sequence anchor"
            );
        }
    }

    #[test]
    fn test_select_block_v2i64_repeated_constant_uses_movq_pshufd() {
        for lane in [42, i64::MIN, i64::MAX] {
            let (mut isel, entry) = make_empty_isel();
            isel.set_stack_slots(vec![StackSlotInfo::new(16, 16)]);

            isel.select_block(entry, &v2i64_const_stack_sequence([lane, lane]))
                .unwrap();

            let insts = &isel.func.blocks[&entry].insts;
            assert_eq!(insts.len(), 3, "{lane}");
            assert_eq!(insts[0].opcode, X86Opcode::MovRI, "{lane}");
            assert_eq!(insts[1].opcode, X86Opcode::MovqToXmm, "{lane}");
            assert_eq!(insts[2].opcode, X86Opcode::Pshufd, "{lane}");
            assert_eq!(insts[0].operands[1], X86ISelOperand::Imm(lane), "{lane}");
            assert_eq!(insts[1].operands[1], insts[0].operands[0], "{lane}");
            assert_eq!(insts[2].operands[1], insts[1].operands[0], "{lane}");
            assert_eq!(insts[2].operands[2], X86ISelOperand::Imm(0x44), "{lane}");
            assert_eq!(isel.value_types[&Value(1)], Type::V128);
            assert!(
                insts.iter().all(|inst| !matches!(
                    inst.opcode,
                    X86Opcode::Lea
                        | X86Opcode::LeaSib
                        | X86Opcode::MovdquMR
                        | X86Opcode::MovdquRM
                        | X86Opcode::MovMR
                        | X86Opcode::MovRM
                        | X86Opcode::Pinsrq
                )),
                "repeated qword vector should broadcast the low qword: {insts:?}"
            );
        }
    }

