    #[test]
    fn test_select_block_v2i64_zero_lane0_insert_uses_movq_without_seed() {
        let (mut isel, entry) = make_empty_isel();
        isel.set_stack_slots(vec![StackSlotInfo::new(16, 16), StackSlotInfo::new(16, 16)]);
        let mut instructions = v2i64_const_stack_sequence([0, 0]);
        instructions.push(Instruction {
            opcode: Opcode::Iconst {
                ty: Type::I64,
                imm: 42,
            },
            args: vec![],
            results: vec![Value(100)],
        });
        instructions.extend(v2i64_insert_stack_sequence(1, 110, 1, 100, 0, 2));

        isel.select_block(entry, &instructions).unwrap();

        let insts = &isel.func.blocks[&entry].insts;
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == X86Opcode::Pxor)
                .count(),
            0,
            "lane-0 zero insert should not leave a dead PXOR seed: {insts:?}"
        );
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == X86Opcode::Pinsrq)
                .count(),
            0,
            "lane-0 zero insert should avoid PINSRQ: {insts:?}"
        );
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == X86Opcode::MovqToXmm)
                .count(),
            1,
            "lane-0 zero insert should fold through MOVQ: {insts:?}"
        );
        assert_eq!(isel.value_types[&Value(2)], Type::V128);
        assert!(isel.deferred_zero_v2i64_values.is_empty());
    }

