    #[test]
    fn test_select_block_v2i64_extract_element_uses_sse2_shuffle_movq() {
        let (mut isel, entry) = make_empty_isel();
        let vector = define_vreg(&mut isel, Value(0), Type::V128);
        isel.set_stack_slots(vec![StackSlotInfo::new(16, 16)]);

        isel.select_block(
            entry,
            &[
                Instruction {
                    opcode: Opcode::StackAddr { slot: 0 },
                    args: vec![],
                    results: vec![Value(10)],
                },
                Instruction {
                    opcode: Opcode::Store {
                        ty: Type::V128,
                        align: None,
                    },
                    args: vec![Value(0), Value(10)],
                    results: vec![],
                },
                Instruction {
                    opcode: Opcode::Iconst {
                        ty: Type::I64,
                        imm: 1,
                    },
                    args: vec![],
                    results: vec![Value(11)],
                },
                Instruction {
                    opcode: Opcode::ArrayGep { elem_ty: Type::I64 },
                    args: vec![Value(10), Value(11)],
                    results: vec![Value(12)],
                },
                Instruction {
                    opcode: Opcode::Load {
                        ty: Type::I64,
                        align: None,
                    },
                    args: vec![Value(12)],
                    results: vec![Value(1)],
                },
            ],
        )
        .unwrap();

        let insts = &isel.func.blocks[&entry].insts;
        assert_eq!(insts.len(), 2);
        assert_eq!(insts[0].opcode, X86Opcode::Pshufd);
        assert_eq!(insts[0].operands[1], X86ISelOperand::VReg(vector));
        assert_eq!(insts[0].operands[2], X86ISelOperand::Imm(0xEE));
        assert_eq!(insts[1].opcode, X86Opcode::MovqFromXmm);
        assert_eq!(insts[1].operands[1], insts[0].operands[0]);
        assert!(matches!(
            insts[1].operands[0],
            X86ISelOperand::VReg(VReg {
                class: RegClass::Gpr64,
                ..
            })
        ));
        assert_eq!(isel.value_types[&Value(1)], Type::I64);
        assert!(
            insts.iter().all(|inst| !matches!(
                inst.opcode,
                X86Opcode::Lea
                    | X86Opcode::LeaSib
                    | X86Opcode::MovdquMR
                    | X86Opcode::MovdquRM
                    | X86Opcode::MovMR
                    | X86Opcode::MovRM
                    | X86Opcode::Pextrq
            )),
            "direct qword extract must avoid stack materialization: {insts:?}"
        );
    }

