    #[test]
    fn test_select_block_v2i64_nonzero_base_insert_stack_uses_sse2() {
        for (lane, pshufd_count) in [(0, 1), (1, 0)] {
            let (mut isel, entry) = make_empty_isel();
            define_vreg(&mut isel, Value(0), Type::V128);
            define_vreg(&mut isel, Value(1), Type::I64);
            isel.set_stack_slots(vec![StackSlotInfo::new(16, 16)]);

            isel.select_block(entry, &v2i64_insert_stack_sequence(0, 10, 0, 1, lane, 2))
                .unwrap();

            let insts = &isel.func.blocks[&entry].insts;
            assert_eq!(
                insts
                    .iter()
                    .filter(|inst| inst.opcode == X86Opcode::Pinsrq)
                    .count(),
                0,
                "lane {lane} nonzero-base insert should avoid PINSRQ: {insts:?}"
            );
            assert_eq!(
                insts
                    .iter()
                    .filter(|inst| inst.opcode == X86Opcode::MovqToXmm)
                    .count(),
                1,
                "lane {lane} nonzero-base insert should cross the scalar with MOVQ: {insts:?}"
            );
            assert_eq!(
                insts
                    .iter()
                    .filter(|inst| inst.opcode == X86Opcode::Punpcklqdq)
                    .count(),
                1,
                "lane {lane} nonzero-base insert should reassemble with PUNPCKLQDQ: {insts:?}"
            );
            assert_eq!(
                insts
                    .iter()
                    .filter(|inst| inst.opcode == X86Opcode::Pshufd)
                    .count(),
                pshufd_count,
                "lane {lane} should only shuffle when preserving the high qword: {insts:?}"
            );
            assert_eq!(isel.value_types[&Value(2)], Type::V128);
            assert!(
                insts.iter().all(|inst| !matches!(
                    inst.opcode,
                    X86Opcode::Lea
                        | X86Opcode::LeaSib
                        | X86Opcode::MovdquMR
                        | X86Opcode::MovdquRM
                        | X86Opcode::MovMR
                        | X86Opcode::MovRM
                )),
                "direct qword insert must avoid stack materialization: {insts:?}"
            );
        }
    }

