    fn test_select_block_v4i32_extract_lane_zero_uses_movd_from_xmm() {
        let (mut isel, entry) = make_empty_isel();
        let vector = define_vreg(&mut isel, Value(0), Type::V128);
        isel.set_stack_slots(vec![StackSlotInfo::new(16, 16)]);

        isel.select_block(
            entry,
            &[
                Instruction {
                    opcode: Opcode::StackAddr { slot: 0 },
                    args: vec![],
                    results: vec![Value(10)],
                },
                Instruction {
                    opcode: Opcode::Store {
                        ty: Type::V128,
                        align: None,
                    },
                    args: vec![Value(0), Value(10)],
                    results: vec![],
                },
                Instruction {
                    opcode: Opcode::Iconst {
                        ty: Type::I64,
                        imm: 0,
                    },
                    args: vec![],
                    results: vec![Value(11)],
                },
                Instruction {
                    opcode: Opcode::ArrayGep { elem_ty: Type::I32 },
                    args: vec![Value(10), Value(11)],
                    results: vec![Value(12)],
                },
                Instruction {
                    opcode: Opcode::Load {
                        ty: Type::I32,
                        align: None,
                    },
                    args: vec![Value(12)],
                    results: vec![Value(1)],
                },
            ],
        )
        .unwrap();

        let insts = &isel.func.blocks[&entry].insts;
        assert_eq!(insts.len(), 1);
        assert_eq!(insts[0].opcode, X86Opcode::MovdFromXmm);
        assert_eq!(insts[0].operands[1], X86ISelOperand::VReg(vector));
        assert!(matches!(
            insts[0].operands[0],
            X86ISelOperand::VReg(VReg {
                class: RegClass::Gpr32,
                ..
            })
        ));
        assert_eq!(isel.value_types[&Value(1)], Type::I32);
    }

    #[test]
    fn test_select_block_v4i32_nonzero_base_insert_stack_uses_sse2_pack() {
        for lane in 0..=3 {
            let (mut isel, entry) = make_empty_isel();
            define_vreg(&mut isel, Value(0), Type::V128);
            define_vreg(&mut isel, Value(1), Type::I32);
            isel.set_stack_slots(vec![StackSlotInfo::new(16, 16)]);

            isel.select_block(entry, &v4i32_insert_stack_sequence(0, 10, 0, 1, lane, 2))
                .unwrap();

            let insts = &isel.func.blocks[&entry].insts;
            assert_eq!(
                insts
                    .iter()
                    .filter(|inst| inst.opcode == X86Opcode::Pinsrd)
                    .count(),
                0,
                "lane {lane} nonzero-base insert should avoid PINSRD: {insts:?}"
            );
            assert_eq!(
                insts
                    .iter()
                    .filter(|inst| inst.opcode == X86Opcode::MovdFromXmm)
                    .count(),
                3,
                "lane {lane} nonzero-base insert should extract the preserved lanes: {insts:?}"
            );
            assert_eq!(
                insts
                    .iter()
                    .filter(|inst| inst.opcode == X86Opcode::Pshufd)
                    .count(),
                if lane == 0 { 3 } else { 2 },
                "lane {lane} nonzero-base insert should only shuffle nonzero preserved lanes: {insts:?}"
            );
            assert_eq!(
                insts
                    .iter()
                    .filter(|inst| inst.opcode == X86Opcode::MovdToXmm)
                    .count(),
                4,
                "lane {lane} nonzero-base insert should seed four dword lanes with MOVD: {insts:?}"
            );
            assert_eq!(
                insts
                    .iter()
                    .filter(|inst| inst.opcode == X86Opcode::Punpckldq)
                    .count(),
                2,
                "lane {lane} nonzero-base insert should form two dword pairs: {insts:?}"
            );
            assert_eq!(
                insts
                    .iter()
                    .filter(|inst| inst.opcode == X86Opcode::Punpcklqdq)
                    .count(),
                1,
                "lane {lane} nonzero-base insert should join dword pairs: {insts:?}"
            );
            assert_eq!(isel.value_types[&Value(2)], Type::V128);
            assert!(
                insts.iter().all(|inst| !matches!(
                    inst.opcode,
                    X86Opcode::Lea
                        | X86Opcode::LeaSib
                        | X86Opcode::MovdquMR
                        | X86Opcode::MovdquRM
                        | X86Opcode::MovMR32
                        | X86Opcode::MovRM32
                )),
                "direct insert must avoid stack materialization: {insts:?}"
            );
        }
    }

