    #[test]
    fn test_select_block_narrow_direct_extract_lanes_use_sse2_dword_bitfield_ops() {
        for (opcode, result_ty, normalize_opcode) in [
            (
                Opcode::V16I8ExtractLane { lane: 7 },
                Type::I8,
                X86Opcode::Movzx,
            ),
            (
                Opcode::V8I16ExtractLane { lane: 3 },
                Type::I16,
                X86Opcode::MovzxW,
            ),
        ] {
            let (mut isel, entry) = make_empty_isel();
            let vector = define_vreg(&mut isel, Value(0), Type::V128);

            isel.select_block(
                entry,
                &[Instruction {
                    opcode,
                    args: vec![Value(0)],
                    results: vec![Value(1)],
                }],
            )
            .unwrap();

            let insts = &isel.func.blocks[&entry].insts;
            assert_eq!(insts[0].opcode, X86Opcode::Pshufd);
            assert_eq!(insts[0].operands[1], X86ISelOperand::VReg(vector));
            assert_eq!(count_x86_isel_opcode(insts, X86Opcode::MovdFromXmm), 1);
            assert_eq!(count_x86_isel_opcode(insts, X86Opcode::ShrRI), 1);
            assert_eq!(count_x86_isel_opcode(insts, normalize_opcode), 1);
            assert_eq!(isel.value_types[&Value(1)], result_ty);
            assert!(insts.iter().all(|inst| {
                !matches!(
                    inst.opcode,
                    X86Opcode::Pextrd
                        | X86Opcode::Pextrq
                        | X86Opcode::MovdquMR
                        | X86Opcode::MovdquRM
                        | X86Opcode::MovMR32
                        | X86Opcode::MovRM32
                        | X86Opcode::LeaSib
                )
            }));
        }
    }

    #[test]
    fn test_select_block_narrow_direct_insert_lanes_use_sse2_dword_bitfield_ops() {
        for (opcode, elem_ty) in [
            (Opcode::V16I8InsertLane { lane: 7 }, Type::I8),
            (Opcode::V8I16InsertLane { lane: 3 }, Type::I16),
        ] {
            let (mut isel, entry) = make_empty_isel();
            define_vreg(&mut isel, Value(0), Type::V128);
            define_vreg(&mut isel, Value(1), elem_ty);

            isel.select_block(
                entry,
                &[Instruction {
                    opcode,
                    args: vec![Value(0), Value(1)],
                    results: vec![Value(2)],
                }],
            )
            .unwrap();

            let insts = &isel.func.blocks[&entry].insts;
            assert_eq!(count_x86_isel_opcode(insts, X86Opcode::MovdFromXmm), 4);
            assert_eq!(count_x86_isel_opcode(insts, X86Opcode::Pshufd), 3);
            assert_eq!(count_x86_isel_opcode(insts, X86Opcode::AndRR), 2);
            assert_eq!(count_x86_isel_opcode(insts, X86Opcode::ShlRI), 1);
            assert_eq!(count_x86_isel_opcode(insts, X86Opcode::OrRR), 1);
            assert_eq!(count_x86_isel_opcode(insts, X86Opcode::MovdToXmm), 4);
            assert_eq!(count_x86_isel_opcode(insts, X86Opcode::Punpckldq), 2);
            assert_eq!(count_x86_isel_opcode(insts, X86Opcode::Punpcklqdq), 1);
            assert_eq!(isel.value_types[&Value(2)], Type::V128);
            assert!(insts.iter().all(|inst| {
                !matches!(
                    inst.opcode,
                    X86Opcode::Pinsrd
                        | X86Opcode::Pinsrq
                        | X86Opcode::MovdquMR
                        | X86Opcode::MovdquRM
                        | X86Opcode::MovMR32
                        | X86Opcode::MovRM32
                        | X86Opcode::LeaSib
                )
            }));
        }
    }

    #[test]
    fn test_select_block_v4i32_nonzero_base_direct_insert_lane3_uses_sse2_pack() {
        let (mut isel, entry) = make_empty_isel();
        let vector = define_vreg(&mut isel, Value(0), Type::V128);
        let elem = define_vreg(&mut isel, Value(1), Type::I32);

        isel.select_block(
            entry,
            &[Instruction {
                opcode: Opcode::V4I32InsertLane { lane: 3 },
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            }],
        )
        .unwrap();

        let insts = &isel.func.blocks[&entry].insts;
        assert_eq!(insts.len(), 12);
        assert_eq!(insts[0].opcode, X86Opcode::MovdFromXmm);
        assert_eq!(insts[0].operands[1], X86ISelOperand::VReg(vector));
        assert_eq!(insts[1].opcode, X86Opcode::Pshufd);
        assert_eq!(insts[1].operands[1], X86ISelOperand::VReg(vector));
        assert_eq!(insts[1].operands[2], X86ISelOperand::Imm(0x55));
        assert_eq!(insts[2].opcode, X86Opcode::MovdFromXmm);
        assert_eq!(insts[2].operands[1], insts[1].operands[0]);
        assert_eq!(insts[3].opcode, X86Opcode::Pshufd);
        assert_eq!(insts[3].operands[1], X86ISelOperand::VReg(vector));
        assert_eq!(insts[3].operands[2], X86ISelOperand::Imm(0xAA));
        assert_eq!(insts[4].opcode, X86Opcode::MovdFromXmm);
        assert_eq!(insts[4].operands[1], insts[3].operands[0]);
        assert_eq!(insts[5].opcode, X86Opcode::MovdToXmm);
        assert_eq!(insts[5].operands[1], insts[0].operands[0]);
        assert_eq!(insts[6].opcode, X86Opcode::MovdToXmm);
        assert_eq!(insts[6].operands[1], insts[2].operands[0]);
        assert_eq!(insts[7].opcode, X86Opcode::Punpckldq);
        assert_eq!(insts[7].operands[0], insts[5].operands[0]);
        assert_eq!(insts[7].operands[1], insts[5].operands[0]);
        assert_eq!(insts[7].operands[2], insts[6].operands[0]);
        assert_eq!(insts[8].opcode, X86Opcode::MovdToXmm);
        assert_eq!(insts[8].operands[1], insts[4].operands[0]);
        assert_eq!(insts[9].opcode, X86Opcode::MovdToXmm);
        assert_eq!(insts[9].operands[1], X86ISelOperand::VReg(elem));
        assert_eq!(insts[10].opcode, X86Opcode::Punpckldq);
        assert_eq!(insts[10].operands[0], insts[8].operands[0]);
        assert_eq!(insts[10].operands[1], insts[8].operands[0]);
        assert_eq!(insts[10].operands[2], insts[9].operands[0]);
        assert_eq!(insts[11].opcode, X86Opcode::Punpcklqdq);
        assert_eq!(insts[11].operands[0], insts[5].operands[0]);
        assert_eq!(insts[11].operands[1], insts[5].operands[0]);
        assert_eq!(insts[11].operands[2], insts[8].operands[0]);
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == X86Opcode::Pinsrd)
                .count(),
            0,
            "direct nonzero-base insert should avoid PINSRD: {insts:?}"
        );
        assert_eq!(isel.value_types[&Value(2)], Type::V128);
    }

    #[test]
    fn test_select_block_v4i32_direct_insert_multi_use_keeps_fresh_dst() {
        let (mut isel, entry) = make_empty_isel();
        let vector = define_vreg(&mut isel, Value(0), Type::V128);
        define_vreg(&mut isel, Value(1), Type::I32);

        isel.select_block(
            entry,
            &[
                Instruction {
                    opcode: Opcode::V4I32InsertLane { lane: 3 },
                    args: vec![Value(0), Value(1)],
                    results: vec![Value(2)],
                },
                Instruction {
                    opcode: Opcode::V4I32ExtractLane { lane: 2 },
                    args: vec![Value(0)],
                    results: vec![Value(3)],
                },
            ],
        )
        .unwrap();

        let insts = &isel.func.blocks[&entry].insts;
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == X86Opcode::Pinsrd)
                .count(),
            0,
            "multi-use nonzero-base insert should avoid PINSRD: {insts:?}"
        );
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == X86Opcode::MovdToXmm)
                .count(),
            4,
            "multi-use nonzero-base insert should pack with MOVD: {insts:?}"
        );
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == X86Opcode::Punpckldq)
                .count(),
            2,
            "multi-use nonzero-base insert should form two dword pairs: {insts:?}"
        );
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == X86Opcode::Punpcklqdq)
                .count(),
            1,
            "multi-use nonzero-base insert should join dword pairs: {insts:?}"
        );
        assert_ne!(isel.value_map[&Value(2)], X86ISelOperand::VReg(vector));
        assert_eq!(isel.value_types[&Value(2)], Type::V128);
        assert_eq!(isel.value_types[&Value(3)], Type::I32);
    }

    #[test]
    fn test_select_block_v4i32_direct_insert_cross_block_without_counts_keeps_fresh_dst() {
        let (mut isel, entry) = make_empty_isel();
        let later = Block(1);
        isel.ensure_block(later);
        let vector = define_vreg(&mut isel, Value(0), Type::V128);
        let elem = define_vreg(&mut isel, Value(1), Type::I32);
        define_vreg(&mut isel, Value(200), Type::I64);

        isel.select_block(
            entry,
            &[Instruction {
                opcode: Opcode::V4I32InsertLane { lane: 3 },
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            }],
        )
        .unwrap();
        isel.select_block(
            later,
            &[Instruction {
                opcode: Opcode::Store {
                    ty: Type::V128,
                    align: None,
                },
                args: vec![Value(0), Value(200)],
                results: vec![],
            }],
        )
        .unwrap();

        let insts = &isel.func.blocks[&entry].insts;
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == X86Opcode::Pinsrd)
                .count(),
            0,
            "cross-block nonzero-base insert should avoid PINSRD: {insts:?}"
        );
        assert_ne!(isel.value_map[&Value(2)], X86ISelOperand::VReg(vector));
        assert!(insts.iter().any(|inst| {
            inst.opcode == X86Opcode::MovdToXmm && inst.operands[1] == X86ISelOperand::VReg(elem)
        }));
    }

