    #[test]
    fn test_select_block_narrow_pack_lanes_uses_scalar_bitfields_and_sse2_dword_pack() {
        for (opcode, lane_count, lane_ty, shl_count) in [
            (Opcode::V16I8PackLanes, 16, Type::I8, 12),
            (Opcode::V8I16PackLanes, 8, Type::I16, 4),
        ] {
            let (mut isel, entry) = make_empty_isel();
            for lane in 0..lane_count {
                define_vreg(&mut isel, Value(200 + lane as u32), lane_ty.clone());
            }

            isel.select_block(
                entry,
                &[Instruction {
                    opcode,
                    args: (0..lane_count)
                        .map(|lane| Value(200 + lane as u32))
                        .collect(),
                    results: vec![Value(300)],
                }],
            )
            .unwrap();

            let insts = &isel.func.blocks[&entry].insts;
            assert_eq!(count_x86_isel_opcode(insts, X86Opcode::MovdToXmm), 4);
            assert_eq!(count_x86_isel_opcode(insts, X86Opcode::Punpckldq), 2);
            assert_eq!(count_x86_isel_opcode(insts, X86Opcode::Punpcklqdq), 1);
            assert_eq!(count_x86_isel_opcode(insts, X86Opcode::ShlRI), shl_count);
            assert!(count_x86_isel_opcode(insts, X86Opcode::AndRR) >= lane_count);
            assert!(count_x86_isel_opcode(insts, X86Opcode::OrRR) >= lane_count - 4);
            assert_eq!(count_x86_isel_opcode(insts, X86Opcode::Pinsrd), 0);
            assert_eq!(count_x86_isel_opcode(insts, X86Opcode::Pinsrq), 0);
            assert!(insts.iter().all(|inst| {
                !matches!(
                    inst.opcode,
                    X86Opcode::MovdquMR
                        | X86Opcode::MovdquRM
                        | X86Opcode::MovMR32
                        | X86Opcode::MovRM32
                        | X86Opcode::Lea
                        | X86Opcode::LeaSib
                )
            }));
            assert_eq!(isel.value_types[&Value(300)], Type::V128);
        }
    }

