    #[test]
    fn test_select_block_v4i32_pack_extract_multi_use_keeps_simd_pack() {
        let (mut isel, entry) = make_empty_isel();
        for lane in 0..4 {
            define_vreg(&mut isel, Value(200 + lane as u32), Type::I32);
        }

        isel.select_block(
            entry,
            &[
                Instruction {
                    opcode: Opcode::V4I32PackLanes,
                    args: vec![Value(200), Value(201), Value(202), Value(203)],
                    results: vec![Value(300)],
                },
                Instruction {
                    opcode: Opcode::V4I32ExtractLane { lane: 2 },
                    args: vec![Value(300)],
                    results: vec![Value(400)],
                },
                Instruction {
                    opcode: Opcode::Copy,
                    args: vec![Value(300)],
                    results: vec![Value(500)],
                },
            ],
        )
        .unwrap();

        let insts = &isel.func.blocks[&entry].insts;
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == X86Opcode::Pshufd)
                .count(),
            1,
            "multi-use pack/extract should shuffle the requested lane before MOVD: {insts:?}"
        );
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == X86Opcode::MovdFromXmm)
                .count(),
            1,
            "multi-use pack/extract should cross the shuffled lane with MOVD: {insts:?}"
        );
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == X86Opcode::Pextrd)
                .count(),
            0,
            "multi-use pack/extract should avoid SSE4.1 PEXTRD: {insts:?}"
        );
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == X86Opcode::Pinsrd)
                .count(),
            0,
            "multi-use v4i32 pack should avoid SSE4.1 PINSRD: {insts:?}"
        );
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == X86Opcode::Punpckldq)
                .count(),
            2,
            "multi-use v4i32 pack should form two low-dword pairs: {insts:?}"
        );
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == X86Opcode::Punpcklqdq)
                .count(),
            1,
            "multi-use v4i32 pack should join dword pairs in lane order: {insts:?}"
        );
        assert_eq!(isel.value_types[&Value(500)], Type::V128);
    }

