    #[test]
    fn test_select_bitfield_insert_i64_preserves_and_inserts() {
        let (mut isel, entry) = make_empty_isel();
        define_vreg(&mut isel, Value(0), Type::I64);
        define_vreg(&mut isel, Value(1), Type::I64);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::InsertBits { lsb: 16, width: 12 },
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        assert_eq!(
            insts.iter().map(|inst| inst.opcode).collect::<Vec<_>>(),
            vec![
                X86Opcode::MovRI,
                X86Opcode::AndRR,
                X86Opcode::MovRI,
                X86Opcode::AndRR,
                X86Opcode::ShlRI,
                X86Opcode::OrRR,
            ]
        );
        assert_eq!(
            insts[0].operands[1],
            X86ISelOperand::Imm(0xffff_ffff_f000_ffff_u64 as i64)
        );
        assert_eq!(insts[2].operands[1], X86ISelOperand::Imm(0xfff));
        assert_eq!(insts[4].operands[2], X86ISelOperand::Imm(16));
        assert_eq!(insts[5].operands[1], insts[1].operands[0]);
        assert_eq!(insts[5].operands[2], insts[4].operands[0]);
    }

