    #[test]
    fn test_select_bitfield_rejects_invalid_ranges_and_types() {
        for (opcode, expected_lsb, expected_width, expected_bits) in [
            (Opcode::ExtractBits { lsb: 0, width: 0 }, 0, 0, 32),
            (Opcode::SextractBits { lsb: 0, width: 65 }, 0, 65, 64),
            (Opcode::InsertBits { lsb: 63, width: 2 }, 63, 2, 64),
        ] {
            let ty = if expected_bits == 32 {
                Type::I32
            } else {
                Type::I64
            };
            let (mut isel, entry) = make_empty_isel();
            define_vreg(&mut isel, Value(0), ty.clone());
            define_vreg(&mut isel, Value(1), ty);
            let args = if matches!(opcode, Opcode::InsertBits { .. }) {
                vec![Value(0), Value(1)]
            } else {
                vec![Value(0)]
            };

            let err = isel
                .select_instruction(
                    &Instruction {
                        opcode,
                        args,
                        results: vec![Value(2)],
                    },
                    entry,
                )
                .unwrap_err();

            assert!(
                matches!(err, X86ISelError::InvalidBitfieldRange {
                    lsb,
                    width,
                    type_bits,
                    ..
                } if lsb == expected_lsb
                    && width == expected_width
                    && type_bits == expected_bits),
                "unexpected range error: {err:?}"
            );
            assert!(isel.func.blocks[&entry].insts.is_empty());
        }

        for ty in [
            Type::B1,
            Type::I128,
            Type::F32,
            Type::F64,
            Type::V128,
            Type::Struct(vec![Type::I32]),
            Type::Array(Box::new(Type::I8), 2),
        ] {
            let (mut isel, entry) = make_empty_isel();
            define_vreg(&mut isel, Value(0), ty);
            let err = isel
                .select_instruction(
                    &Instruction {
                        opcode: Opcode::ExtractBits { lsb: 0, width: 1 },
                        args: vec![Value(0)],
                        results: vec![Value(1)],
                    },
                    entry,
                )
                .unwrap_err();

            assert!(
                matches!(
                    err,
                    X86ISelError::UnsupportedBitfieldType {
                        op: "ExtractBits",
                        ..
                    }
                ),
                "unexpected type error: {err:?}"
            );
            assert!(isel.func.blocks[&entry].insts.is_empty());
        }
    }

