    #[test]
    fn test_select_v2i64_mask_extract_emits_x86_pseudo_for_i32_and_i64_results() {
        for result_ty in [Type::I32, Type::I64] {
            let (mut isel, entry) = make_empty_isel();
            let mask = define_vreg(&mut isel, Value(0), Type::V128);

            isel.select_instruction(
                &Instruction {
                    opcode: Opcode::V2I64MaskExtract {
                        result_ty: result_ty.clone(),
                    },
                    args: vec![Value(0)],
                    results: vec![Value(1)],
                },
                entry,
            )
            .unwrap();

            let insts = &isel.func.blocks[&entry].insts;
            assert_eq!(insts[0].opcode, X86Opcode::V2I64MaskExtract);
            assert!(matches!(
                insts[0].operands[0],
                X86ISelOperand::VReg(VReg {
                    class: RegClass::Gpr32,
                    ..
                })
            ));
            assert_eq!(insts[0].operands[1], X86ISelOperand::VReg(mask));

            if result_ty == Type::I32 {
                assert_eq!(insts.len(), 1);
            } else {
                assert_eq!(insts.len(), 2);
                assert_eq!(insts[1].opcode, X86Opcode::MovRR32);
                assert!(matches!(
                    insts[1].operands[0],
                    X86ISelOperand::VReg(VReg {
                        class: RegClass::Gpr64,
                        ..
                    })
                ));
                assert_eq!(insts[1].operands[1], insts[0].operands[0]);
            }
            assert_eq!(isel.value_types.get(&Value(1)), Some(&result_ty));
        }
    }

    #[test]
    fn test_select_v2i64_mask_extract_rejects_bad_shapes() {
        let (mut isel, entry) = make_empty_isel();
        define_vreg(&mut isel, Value(0), Type::I64);

        let err = isel
            .select_instruction(
                &Instruction {
                    opcode: Opcode::V2I64MaskExtract {
                        result_ty: Type::I32,
                    },
                    args: vec![Value(0)],
                    results: vec![Value(1)],
                },
                entry,
            )
            .unwrap_err();
        assert!(
            matches!(err, X86ISelError::UnsupportedOpcode(ref message)
                if message.contains("source must be V128")),
            "unexpected V2I64MaskExtract source rejection: {err:?}"
        );

        let (mut isel, entry) = make_empty_isel();
        define_vreg(&mut isel, Value(0), Type::V128);
        let err = isel
            .select_instruction(
                &Instruction {
                    opcode: Opcode::V2I64MaskExtract {
                        result_ty: Type::I16,
                    },
                    args: vec![Value(0)],
                    results: vec![Value(1)],
                },
                entry,
            )
            .unwrap_err();
        assert!(
            matches!(err, X86ISelError::UnsupportedOpcode(ref message)
                if message.contains("result must be I32 or I64")),
            "unexpected V2I64MaskExtract result rejection: {err:?}"
        );
    }

