    #[test]
    fn test_select_cmp_narrow_operands_extend_before_cmp() {
        for (ty, cond, extend_opcode, expected_cc) in [
            (
                Type::I8,
                IntCC::UnsignedLessThan,
                X86Opcode::Movzx,
                X86CondCode::B,
            ),
            (
                Type::I8,
                IntCC::SignedLessThan,
                X86Opcode::MovsxB,
                X86CondCode::L,
            ),
            (
                Type::I16,
                IntCC::UnsignedGreaterThanOrEqual,
                X86Opcode::MovzxW,
                X86CondCode::AE,
            ),
            (
                Type::I16,
                IntCC::SignedGreaterThanOrEqual,
                X86Opcode::MovsxW,
                X86CondCode::GE,
            ),
        ] {
            let (mut isel, entry) = make_empty_isel();
            let lhs = define_vreg(&mut isel, Value(0), ty.clone());
            let rhs = define_vreg(&mut isel, Value(1), ty.clone());

            isel.select_instruction(
                &Instruction {
                    opcode: Opcode::Icmp { cond },
                    args: vec![Value(0), Value(1)],
                    results: vec![Value(2)],
                },
                entry,
            )
            .unwrap();

            let mfunc = isel.finalize();
            let insts = &mfunc.blocks[&entry].insts;
            assert_eq!(
                insts.iter().map(|inst| inst.opcode).collect::<Vec<_>>(),
                vec![
                    extend_opcode,
                    extend_opcode,
                    X86Opcode::CmpRR,
                    X86Opcode::Setcc,
                    X86Opcode::Movzx
                ],
                "unexpected narrow ICmp lowering for {ty:?} {cond:?}: {insts:?}"
            );
            assert_eq!(insts[0].operands[1], X86ISelOperand::VReg(lhs));
            assert_eq!(insts[1].operands[1], X86ISelOperand::VReg(rhs));
            assert_ne!(insts[0].operands[0], X86ISelOperand::VReg(lhs));
            assert_ne!(insts[1].operands[0], X86ISelOperand::VReg(rhs));
            assert_eq!(insts[2].operands[0], insts[0].operands[0]);
            assert_eq!(insts[2].operands[1], insts[1].operands[0]);
            assert_eq!(insts[3].operands[1], X86ISelOperand::CondCode(expected_cc));
            assert_eq!(
                mfunc.blocks[&entry].insts[4].operands[1],
                insts[3].operands[0]
            );
        }
    }

    #[test]
    fn test_select_cmp_masks_b1_operands_before_cmp() {
        let (mut isel, entry) = make_empty_isel();
        let lhs = define_vreg(&mut isel, Value(0), Type::B1);
        let rhs = define_vreg(&mut isel, Value(1), Type::B1);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Icmp { cond: IntCC::Equal },
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();

        let insts = &isel.func.blocks[&entry].insts;
        assert_eq!(
            insts.iter().map(|inst| inst.opcode).collect::<Vec<_>>(),
            vec![
                X86Opcode::Movzx,
                X86Opcode::AndRI,
                X86Opcode::Movzx,
                X86Opcode::AndRI,
                X86Opcode::CmpRR,
                X86Opcode::Setcc,
                X86Opcode::Movzx
            ]
        );
        assert_eq!(insts[0].operands[1], X86ISelOperand::VReg(lhs));
        assert_eq!(insts[2].operands[1], X86ISelOperand::VReg(rhs));
        assert_eq!(insts[1].operands[0], insts[0].operands[0]);
        assert_eq!(insts[1].operands[1], insts[0].operands[0]);
        assert_eq!(insts[1].operands[2], X86ISelOperand::Imm(1));
        assert_eq!(insts[3].operands[0], insts[2].operands[0]);
        assert_eq!(insts[3].operands[1], insts[2].operands[0]);
        assert_eq!(insts[3].operands[2], X86ISelOperand::Imm(1));
        assert_eq!(insts[4].operands[0], insts[1].operands[0]);
        assert_eq!(insts[4].operands[1], insts[3].operands[0]);
    }

    #[test]
    fn test_select_v128_i32_signed_order_comparisons() {
        for (cond, expected_opcodes, gt_uses_swapped_operands) in [
            (IntCC::SignedGreaterThan, vec![X86Opcode::Pcmpgtd], false),
            (IntCC::SignedLessThan, vec![X86Opcode::Pcmpgtd], true),
            (
                IntCC::SignedGreaterThanOrEqual,
                vec![X86Opcode::Pcmpgtd, X86Opcode::Pcmpeqd, X86Opcode::Por],
                false,
            ),
            (
                IntCC::SignedLessThanOrEqual,
                vec![X86Opcode::Pcmpgtd, X86Opcode::Pcmpeqd, X86Opcode::Por],
                true,
            ),
        ] {
            let (mut isel, entry) = make_empty_isel();
            let lhs = define_vreg(&mut isel, Value(0), Type::V128);
            let rhs = define_vreg(&mut isel, Value(1), Type::V128);
            let lhs_op = X86ISelOperand::VReg(lhs);
            let rhs_op = X86ISelOperand::VReg(rhs);

            isel.select_instruction(
                &Instruction {
                    opcode: Opcode::Icmp { cond },
                    args: vec![Value(0), Value(1)],
                    results: vec![Value(2)],
                },
                entry,
            )
            .unwrap();

            let insts = &isel.func.blocks[&entry].insts;
            assert_eq!(
                insts.iter().map(|inst| inst.opcode).collect::<Vec<_>>(),
                expected_opcodes,
                "unexpected V128 signed compare lowering for {cond:?}: {insts:?}"
            );
            let (expected_gt_lhs, expected_gt_rhs) = if gt_uses_swapped_operands {
                (rhs_op.clone(), lhs_op.clone())
            } else {
                (lhs_op.clone(), rhs_op.clone())
            };
            assert_eq!(insts[0].operands[1], expected_gt_lhs);
            assert_eq!(insts[0].operands[2], expected_gt_rhs);

            if insts.len() == 3 {
                assert_eq!(insts[1].operands[1], lhs_op);
                assert_eq!(insts[1].operands[2], rhs_op);
                assert_eq!(insts[2].operands[1], insts[0].operands[0]);
                assert_eq!(insts[2].operands[2], insts[1].operands[0]);
            }
            assert_eq!(isel.value_types[&Value(2)], Type::V128);
        }
    }

