            let insts = &isel.func.blocks[&entry].insts;
            assert_eq!(
                insts.iter().map(|inst| inst.opcode).collect::<Vec<_>>(),
                expected_opcodes,
                "unexpected unsigned V2I64Icmp lowering for {cond:?}: {insts:?}"
            );
            assert_eq!(insts[0].operands[1], X86ISelOperand::Imm(i32::MIN as i64));
