    // Branches
    // -----------------------------------------------------------------------

    #[test]
    fn test_select_jump() {
        let (mut isel, entry) = make_empty_isel();
        let target = Block(1);
        isel.func.ensure_block(target);

        isel.select_branch(target, entry).unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        assert_eq!(insts.len(), 1);
        assert_eq!(insts[0].opcode, X86Opcode::Jmp);
        assert_eq!(insts[0].operands[0], X86ISelOperand::Block(target));

        // Check successor edge
        assert!(mfunc.blocks[&entry].successors.contains(&target));
    }

    #[test]
    fn test_select_condbranch() {
        let (mut isel, entry) = make_empty_isel();
        let then_block = Block(1);
        let else_block = Block(2);
        isel.func.ensure_block(then_block);
        isel.func.ensure_block(else_block);
        define_vreg(&mut isel, Value(0), Type::B1);

        isel.select_condbranch(
            &Instruction {
                opcode: Opcode::Brif {
                    cond: Value(0),
                    then_dest: then_block,
                    else_dest: else_block,
                },
                args: vec![Value(0)],
                results: vec![],
            },
            then_block,
            else_block,
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        // MOVZX, AND, CMP, Jcc, Jmp. B1 is masked before the zero test so
        // dirty non-bit0 payloads cannot make a false condition branch as true.
        assert_eq!(insts.len(), 5);
        assert_eq!(insts[0].opcode, X86Opcode::Movzx);
        assert_eq!(insts[1].opcode, X86Opcode::AndRI);
        assert_eq!(insts[1].operands[0], insts[0].operands[0]);
        assert_eq!(insts[1].operands[1], insts[0].operands[0]);
        assert_eq!(insts[1].operands[2], X86ISelOperand::Imm(1));
        assert_eq!(insts[2].opcode, X86Opcode::CmpRI);
        assert_eq!(insts[2].operands[0], insts[1].operands[0]);
        assert_eq!(insts[3].opcode, X86Opcode::Jcc);
        assert_eq!(insts[4].opcode, X86Opcode::Jmp);

        // Successor edges
        let succs = &mfunc.blocks[&entry].successors;
        assert!(succs.contains(&then_block));
        assert!(succs.contains(&else_block));
    }

    #[test]
    fn test_select_block_v128_compare_branch_uses_ptest_mask_zero_test() {
        let (mut isel, entry) = make_empty_isel();
        let then_block = Block(1);
        let else_block = Block(2);
        isel.func.ensure_block(then_block);
        isel.func.ensure_block(else_block);
        let lhs = define_vreg(&mut isel, Value(0), Type::V128);
        let rhs = define_vreg(&mut isel, Value(1), Type::V128);

        isel.select_block(
            entry,
            &[
                Instruction {
                    opcode: Opcode::Icmp { cond: IntCC::Equal },
                    args: vec![Value(0), Value(1)],
                    results: vec![Value(2)],
                },
                Instruction {
                    opcode: Opcode::Brif {
                        cond: Value(2),
                        then_dest: then_block,
                        else_dest: else_block,
                    },
                    args: vec![Value(2)],
                    results: vec![],
                },
            ],
        )
        .unwrap();

        let insts = &isel.func.blocks[&entry].insts;
        assert_eq!(
            insts.iter().map(|inst| inst.opcode).collect::<Vec<_>>(),
            vec![
                X86Opcode::Pcmpeqd,
                X86Opcode::Ptest,
                X86Opcode::Jcc,
                X86Opcode::Jmp,
            ],
            "V128 mask branch should test the vector predicate directly: {insts:?}"
        );
        assert_eq!(insts[0].operands[1], X86ISelOperand::VReg(lhs));
        assert_eq!(insts[0].operands[2], X86ISelOperand::VReg(rhs));
        assert_eq!(insts[1].operands[0], insts[0].operands[0]);
        assert_eq!(insts[1].operands[1], insts[0].operands[0]);
        assert_eq!(
            insts[2].operands[0],
            X86ISelOperand::CondCode(X86CondCode::NE)
        );
    }

