    #[test]
    fn test_select_mov_reg() {
        // Opcode::Copy lowers to MOVrr (formerly single-arg Iadd; see #417).
        let (mut isel, entry) = make_empty_isel();
        define_vreg(&mut isel, Value(0), Type::I64);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Copy,
                args: vec![Value(0)],
                results: vec![Value(1)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let inst = &mfunc.blocks[&entry].insts[0];
        assert_eq!(inst.opcode, X86Opcode::MovRR);
    }

    #[test]
    fn test_select_mov_reg_gpr32_values_use_movrr32() {
        for ty in [Type::B1, Type::I8, Type::I16, Type::I32] {
            let (mut isel, entry) = make_empty_isel();
            define_vreg(&mut isel, Value(0), ty.clone());

            isel.select_instruction(
                &Instruction {
                    opcode: Opcode::Copy,
                    args: vec![Value(0)],
                    results: vec![Value(1)],
                },
                entry,
            )
            .unwrap();

            let mfunc = isel.finalize();
            let inst = &mfunc.blocks[&entry].insts[0];
            assert_eq!(inst.opcode, X86Opcode::MovRR32, "{ty:?}");
            assert!(
                matches!(inst.operands[0], X86ISelOperand::VReg(v) if v.class == RegClass::Gpr32),
                "{ty:?} copy destination must stay Gpr32"
            );
        }
    }

    #[test]
