    #[test]
    fn test_select_load() {
        let (mut isel, entry) = make_empty_isel();
        define_vreg(&mut isel, Value(0), Type::I64); // address

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Load {
                    ty: Type::I64,
                    align: None,
                },
                args: vec![Value(0)],
                results: vec![Value(1)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let inst = &mfunc.blocks[&entry].insts[0];
        assert_eq!(inst.opcode, X86Opcode::MovRM);
        assert_eq!(inst.operands.len(), 2); // dst, memaddr
        assert_eq!(inst.proof_origin, None);
    }

    #[test]
    fn test_select_load_uses_memory_type_width() {
        for (ty, expected_opcode) in [
            (Type::I8, X86Opcode::MovRM8),
            (Type::I16, X86Opcode::MovRM16),
            (Type::I32, X86Opcode::MovRM32),
            (Type::I64, X86Opcode::MovRM),
        ] {
            let (mut isel, entry) = make_empty_isel();
            define_vreg(&mut isel, Value(0), Type::I64); // address

            isel.select_instruction(
                &Instruction {
                    opcode: Opcode::Load { ty, align: None },
                    args: vec![Value(0)],
                    results: vec![Value(1)],
                },
                entry,
            )
            .unwrap();

            let mfunc = isel.finalize();
            let inst = &mfunc.blocks[&entry].insts[0];
            assert_eq!(inst.opcode, expected_opcode);
            assert_eq!(inst.proof_origin, None);
        }
    }

    #[test]
    fn volatile_i128_load_and_store_fail_closed_instead_of_splitting() {
        let (mut load_isel, entry) = make_empty_isel();
        define_vreg(&mut load_isel, Value(0), Type::I64);
        let load_err = load_isel
            .select_instruction(
                &Instruction {
                    opcode: Opcode::VolatileLoad {
                        ty: Type::I128,
                        align: Some(16),
                    },
                    args: vec![Value(0)],
                    results: vec![Value(1)],
                },
                entry,
            )
            .expect_err("volatile I128 load must not split into two reads");
        assert!(
            matches!(load_err, X86ISelError::UnsupportedOpcode(ref message)
                if message.contains("I128 load") && message.contains("two 64-bit accesses"))
        );
        assert!(load_isel.func.blocks[&entry].insts.is_empty());

        let (mut store_isel, entry) = make_empty_isel();
        define_vreg(&mut store_isel, Value(0), Type::I64);
        let lo = store_isel.new_vreg(RegClass::Gpr64);
        let hi = store_isel.new_vreg(RegClass::Gpr64);
        store_isel.define_i128_value(Value(1), lo, hi);
        let store_err = store_isel
            .select_instruction(
                &Instruction {
                    opcode: Opcode::VolatileStore {
                        ty: Type::I128,
                        align: Some(16),
                    },
                    args: vec![Value(1), Value(0)],
                    results: vec![],
                },
                entry,
            )
            .expect_err("volatile I128 store must not split into two writes");
        assert!(
            matches!(store_err, X86ISelError::UnsupportedOpcode(ref message)
                if message.contains("I128 store") && message.contains("two 64-bit accesses"))
        );
        assert!(store_isel.func.blocks[&entry].insts.is_empty());
    }

