    #[test]
    fn test_select_atomic_rmw_xchg_i32_i64_emits_cas_loop_pseudo() {
        // The bare `XCHG r,[mem]` fast path was deleted (no per-instruction proof;
        // FailClosedAllowlisted under default certs). All Xchg RMWs -- including
        // I32/I64 -- now route through the cert-covered AtomicRmwCasLoop pseudo
        // (kind 5 == Xchg), covered by AtomicRmwCasLoop_Xchg_I32/I64 proofs.
        assert_atomic_rmw_lowers_to_cas_loop_pseudo(
            AtomicRmwOp::Xchg,
            Type::I32,
            X86Opcode::AtomicRmwCasLoop,
            5,
        );
        assert_atomic_rmw_lowers_to_cas_loop_pseudo(
            AtomicRmwOp::Xchg,
            Type::I64,
            X86Opcode::AtomicRmwCasLoop,
            5,
        );
    }

    fn assert_atomic_rmw_lowers_to_cas_loop_pseudo(
        op: AtomicRmwOp,
        ty: Type,
        expected_opcode: X86Opcode,
        expected_kind: i64,
    ) {
        let (mut isel, entry) = make_empty_isel();
        let value = define_vreg(&mut isel, Value(0), ty.clone());
        let addr = define_vreg(&mut isel, Value(1), Type::I64);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::AtomicRmw {
                    op,
                    ty: ty.clone(),
                    ordering: AtomicOrdering::SeqCst,
                },
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();

        let insts = &isel.func.blocks[&entry].insts;
        assert_eq!(insts.len(), 1);
        assert_eq!(insts[0].opcode, expected_opcode);
        let result_reg = match insts[0].operands.as_slice() {
            [
                X86ISelOperand::VReg(dst),
                X86ISelOperand::VReg(operand),
                X86ISelOperand::MemAddr { base, disp },
                X86ISelOperand::Imm(kind),
            ] => {
                assert_eq!(*operand, value);
                assert_eq!(base.as_ref(), &X86ISelOperand::VReg(addr));
                assert_eq!(*disp, 0);
                assert_eq!(*kind, expected_kind);
                *dst
            }
            other => panic!("expected AtomicRmwCasLoop dst, value, [addr], kind, got {other:?}"),
        };

        assert_eq!(
            isel.value_map.get(&Value(2)),
            Some(&X86ISelOperand::VReg(result_reg))
        );
        assert_eq!(isel.value_types.get(&Value(2)), Some(&ty));
    }

    #[test]
    fn test_select_atomic_rmw_non_exchange_i32_i64_emits_cas_loop_pseudo() {
        let cases = [
            (AtomicRmwOp::Add, 0),
            (AtomicRmwOp::Sub, 1),
            (AtomicRmwOp::And, 2),
            (AtomicRmwOp::Or, 3),
            (AtomicRmwOp::Xor, 4),
            (AtomicRmwOp::Max, 6),
            (AtomicRmwOp::Min, 7),
            (AtomicRmwOp::UMax, 8),
            (AtomicRmwOp::UMin, 9),
        ];

        for (op, expected_kind) in cases {
            assert_atomic_rmw_lowers_to_cas_loop_pseudo(
                op,
                Type::I32,
                X86Opcode::AtomicRmwCasLoop,
                expected_kind,
            );
            assert_atomic_rmw_lowers_to_cas_loop_pseudo(
                op,
                Type::I64,
                X86Opcode::AtomicRmwCasLoop,
                expected_kind,
            );
        }
    }

