    #[test]
    fn test_atomic_rmw_unsupported_forms_return_typed_errors() {
        let cases = [
            (
                Opcode::AtomicRmw {
                    op: AtomicRmwOp::Add,
                    ty: Type::I128,
                    ordering: AtomicOrdering::SeqCst,
                },
                "only i8/i16/i32/i64",
            ),
            (
                Opcode::AtomicRmw {
                    op: AtomicRmwOp::Xchg,
                    ty: Type::B1,
                    ordering: AtomicOrdering::SeqCst,
                },
                "only i8/i16/i32/i64",
            ),
        ];

        for (opcode, reason) in cases {
            let (mut isel, entry) = make_empty_isel();
            define_vreg(&mut isel, Value(0), Type::I64);
            define_vreg(&mut isel, Value(1), Type::I64);

            let result = isel.select_instruction(
                &Instruction {
                    opcode,
                    args: vec![Value(0), Value(1)],
                    results: vec![Value(2)],
                },
                entry,
            );

            assert!(
                matches!(
                    &result,
                    Err(X86ISelError::UnsupportedAtomicRmw {
                        reason: actual,
                        ..
                    }) if actual.contains(reason)
                ),
                "expected typed AtomicRmw error containing {reason:?}, got {result:?}"
            );
        }
    }

    fn assert_cmpxchg_lowers_to_fixed_accumulator(
        ty: Type,
        expected_copy: X86Opcode,
        expected_acc: X86PReg,
        expected_cmpxchg: X86Opcode,
    ) {
        let (mut isel, entry) = make_empty_isel();
        let expected = define_vreg(&mut isel, Value(0), ty.clone());
        let desired = define_vreg(&mut isel, Value(1), ty.clone());
        let addr = define_vreg(&mut isel, Value(2), Type::I64);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::CmpXchg {
                    ty: ty.clone(),
                    success: AtomicOrdering::SeqCst,
                    failure: AtomicOrdering::Acquire,
                },
                args: vec![Value(0), Value(1), Value(2)],
                results: vec![Value(3)],
            },
            entry,
        )
        .unwrap();

        let insts = &isel.func.blocks[&entry].insts;
        assert_eq!(insts.len(), 4);

        assert_eq!(insts[0].opcode, expected_copy);
        assert_eq!(insts[0].operands[1], X86ISelOperand::VReg(desired));
        let desired_reg = match &insts[0].operands[0] {
            X86ISelOperand::VReg(vreg) => *vreg,
            other => panic!("cmpxchg desired copy dst should be a vreg: {other:?}"),
        };

        assert_eq!(insts[1].opcode, expected_copy);
        assert_eq!(insts[1].operands[0], X86ISelOperand::PReg(expected_acc));
        assert_eq!(insts[1].operands[1], X86ISelOperand::VReg(expected));

        assert_eq!(insts[2].opcode, expected_cmpxchg);
        match insts[2].operands.as_slice() {
            [
                X86ISelOperand::VReg(cmpxchg_src),
                X86ISelOperand::MemAddr { base, disp },
            ] => {
                assert_eq!(*cmpxchg_src, desired_reg);
                assert_eq!(base.as_ref(), &X86ISelOperand::VReg(addr));
                assert_eq!(*disp, 0);
            }
            other => panic!("expected CMPXCHG desired, [addr], got {other:?}"),
        }

        assert_eq!(insts[3].opcode, expected_copy);
        assert_eq!(insts[3].operands[1], X86ISelOperand::PReg(expected_acc));
        let result_reg = match &insts[3].operands[0] {
            X86ISelOperand::VReg(vreg) => *vreg,
            other => panic!("cmpxchg result copy dst should be a vreg: {other:?}"),
        };
        assert_eq!(
            isel.value_map.get(&Value(3)),
            Some(&X86ISelOperand::VReg(result_reg))
        );
        assert_eq!(isel.value_types.get(&Value(3)), Some(&ty));
    }

    #[test]
    fn test_select_cmpxchg_i32_i64_emits_fixed_accumulator_memory_cmpxchg() {
        assert_cmpxchg_lowers_to_fixed_accumulator(
            Type::I32,
            X86Opcode::MovRR32,
            x86_64_regs::EAX,
            X86Opcode::Cmpxchg,
        );
        assert_cmpxchg_lowers_to_fixed_accumulator(
            Type::I64,
            X86Opcode::MovRR,
            RAX,
            X86Opcode::Cmpxchg,
        );
    }

    #[test]
    fn test_select_tls_ref_tlv_emits_descriptor_thunk_call() {
        // x86-64 Darwin TLV access: movq _v@TLVP(%rip), desc ; movq (desc), thunk
        // ; movq desc -> RDI ; call *thunk ; movq RAX -> result.
        let (mut isel, entry) = make_empty_isel();
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::TlsRef {
                    name: "tls.deadbeef".to_string(),
                    model: TlsModel::Tlv,
                    local_exec_offset: None,
                },
                args: vec![],
                results: vec![Value(3)],
            },
            entry,
        )
        .unwrap();

        let insts = &isel.func.blocks[&entry].insts;
        assert_eq!(insts.len(), 5, "TLV access is a 5-instruction sequence");

        // 0: movq _tls.deadbeef@TLVP(%rip), desc
        assert_eq!(insts[0].opcode, X86Opcode::MovRipRelTlv);
        let desc = match &insts[0].operands[0] {
            X86ISelOperand::VReg(v) => *v,
            other => panic!("MovRipRelTlv dst should be a vreg: {other:?}"),
        };
        assert_eq!(
            insts[0].operands[1],
            X86ISelOperand::Symbol("tls.deadbeef".to_string())
        );

        // 1: movq (desc), thunk
        assert_eq!(insts[1].opcode, X86Opcode::MovRM);
        let thunk = match &insts[1].operands[0] {
            X86ISelOperand::VReg(v) => *v,
            other => panic!("MovRM dst should be a vreg: {other:?}"),
        };
        match &insts[1].operands[1] {
            X86ISelOperand::MemAddr { base, disp } => {
                assert_eq!(base.as_ref(), &X86ISelOperand::VReg(desc));
                assert_eq!(*disp, 0);
            }
            other => panic!("MovRM src should be [desc]: {other:?}"),
        }

        // 2: movq desc -> RDI (the thunk's sole argument register)
        assert_eq!(insts[2].opcode, X86Opcode::MovRR);
        assert_eq!(insts[2].operands[0], X86ISelOperand::PReg(RDI));
        assert_eq!(insts[2].operands[1], X86ISelOperand::VReg(desc));

        // 3: call *thunk — an indirect call reading RDI, defining RAX.
        assert_eq!(insts[3].opcode, X86Opcode::CallR);
        assert_eq!(insts[3].operands[0], X86ISelOperand::VReg(thunk));

        // 4: movq RAX -> result
        assert_eq!(insts[4].opcode, X86Opcode::MovRR);
        assert_eq!(insts[4].operands[1], X86ISelOperand::PReg(RAX));
        let result_reg = match &insts[4].operands[0] {
            X86ISelOperand::VReg(v) => *v,
            other => panic!("result copy dst should be a vreg: {other:?}"),
        };
        assert_eq!(
            isel.value_map.get(&Value(3)),
            Some(&X86ISelOperand::VReg(result_reg))
        );
    }

