    #[test]
    fn test_select_cmpxchg_i8_i16_emits_narrow_cmpxchg() {
        // Narrow (i8/i16) AtomicU8/U16 compare-exchange lowers to the byte
        // (0F B0) / word (66 0F B1) LOCK CMPXCHG opcodes. The copy/accumulator
        // helpers select the Gpr32 carrier + EAX low bits (the encoder narrows
        // the source register + AL/AX accumulator).
        assert_cmpxchg_lowers_to_fixed_accumulator(
            Type::I8,
            X86Opcode::MovRR32,
            x86_64_regs::EAX,
            X86Opcode::Cmpxchg8,
        );
        assert_cmpxchg_lowers_to_fixed_accumulator(
            Type::I16,
            X86Opcode::MovRR32,
            x86_64_regs::EAX,
            X86Opcode::Cmpxchg16,
        );
    }

    #[test]
    fn test_cmpxchg_invalid_failure_ordering_fails_closed() {
        // THE rule (Rust/LLVM, one rule in adapter + both ISels): the failure
        // ordering must not be Release/AcqRel. Nothing else is invalid.
        for failure in [AtomicOrdering::Release, AtomicOrdering::AcqRel] {
            let (mut isel, entry) = make_empty_isel();
            define_vreg(&mut isel, Value(0), Type::I64);
            define_vreg(&mut isel, Value(1), Type::I64);
            define_vreg(&mut isel, Value(2), Type::I64);

            let result = isel.select_instruction(
                &Instruction {
                    opcode: Opcode::CmpXchg {
                        ty: Type::I64,
                        success: AtomicOrdering::SeqCst,
                        failure,
                    },
                    args: vec![Value(0), Value(1), Value(2)],
                    results: vec![Value(3)],
                },
                entry,
            );

            assert!(
                matches!(
                    result,
                    Err(X86ISelError::UnsupportedCmpXchg {
                        ty: Type::I64,
                        success: AtomicOrdering::SeqCst,
                        reason: "invalid compare-exchange failure ordering",
                        ..
                    })
                ),
                "failure ordering {failure:?} must fail closed"
            );
        }
    }

    #[test]
    fn test_cmpxchg_failure_stronger_than_success_is_legal() {
        // Rust/C++17 allow the failure ordering to EXCEED the success ordering
        // (`compare_exchange(.., AcqRel, SeqCst)` in std's mutex/rwlock). The
        // pre-alignment gate rejected these pairs while the adapter accepted
        // (and lifted) them; the aligned rule accepts every non-Release/AcqRel
        // failure. `LOCK CMPXCHG` is a full barrier, so the same sequence is
        // emitted regardless of the pair.
        for (success, failure) in [
            (AtomicOrdering::Acquire, AtomicOrdering::SeqCst),
            (AtomicOrdering::Relaxed, AtomicOrdering::Acquire),
            (AtomicOrdering::Release, AtomicOrdering::Acquire),
            (AtomicOrdering::Relaxed, AtomicOrdering::SeqCst),
        ] {
            let (mut isel, entry) = make_empty_isel();
            define_vreg(&mut isel, Value(0), Type::I64);
            define_vreg(&mut isel, Value(1), Type::I64);
            define_vreg(&mut isel, Value(2), Type::I64);

            isel.select_instruction(
                &Instruction {
                    opcode: Opcode::CmpXchg {
                        ty: Type::I64,
                        success,
                        failure,
                    },
                    args: vec![Value(0), Value(1), Value(2)],
                    results: vec![Value(3)],
                },
                entry,
            )
            .unwrap_or_else(|e| {
                panic!("cmpxchg ({success:?}, {failure:?}) must be accepted: {e:?}")
            });

            let insts = &isel.func.blocks[&entry].insts;
            assert_eq!(
                insts[2].opcode,
                X86Opcode::Cmpxchg,
                "({success:?}, {failure:?}) must lower to LOCK CMPXCHG"
            );
        }
    }

    #[test]
    fn test_select_fence_seqcst_emits_mfence() {
        // SLICE 3: on x86 TSO only SeqCst needs a hardware barrier (MFENCE),
        // carrying the FenceSeqCst proof origin that binds the single-thread
        // identity proof.
        let (mut isel, entry) = make_empty_isel();

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Fence {
                    ordering: AtomicOrdering::SeqCst,
                },
                args: vec![],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let insts = &isel.func.blocks[&entry].insts;
        assert_eq!(insts.len(), 1);
        assert_eq!(insts[0].opcode, X86Opcode::Mfence);
        assert!(insts[0].operands.is_empty());
        assert_eq!(insts[0].proof_origin, Some(X86ProofOrigin::FenceSeqCst));
    }

    #[test]
    fn test_select_fence_relaxed_acquire_release_acqrel_emit_no_instructions() {
        // SLICE 3: Relaxed/Acquire/Release/AcqRel fences are zero-instruction on
        // x86 TSO (LLVM emits nothing). The compiler-ordering barrier is kept by
        // the HAS_SIDE_EFFECTS Fence node, not by any hardware instruction.
        for ordering in [
            AtomicOrdering::Relaxed,
            AtomicOrdering::Acquire,
            AtomicOrdering::Release,
            AtomicOrdering::AcqRel,
        ] {
            let (mut isel, entry) = make_empty_isel();

            isel.select_instruction(
                &Instruction {
                    opcode: Opcode::Fence { ordering },
                    args: vec![],
                    results: vec![],
                },
                entry,
            )
            .unwrap();

            assert!(
                isel.func.blocks[&entry].insts.is_empty(),
                "{ordering:?} must emit no instruction on x86 TSO"
            );
        }
    }

    // -----------------------------------------------------------------------
    // Call / Return
    // -----------------------------------------------------------------------

    fn lowered_call_result_metadata(
        abi: X86CallAbi,
        result_tys: Vec<Type>,
    ) -> Vec<X86CallResultReg> {
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut isel = X86InstructionSelector::with_abi("caller".to_string(), sig, abi);
        let entry = Block(0);
        isel.func.ensure_block(entry);
        let result_values: Vec<Value> = (0..result_tys.len() as u32).map(Value).collect();
        isel.seed_value_types(
            &result_values
                .iter()
                .copied()
                .zip(result_tys)
                .collect::<HashMap<_, _>>(),
        );
        isel.lower_call(
            "callee",
            &Instruction {
                opcode: Opcode::Call {
                    name: "callee".to_string(),
                },
                args: vec![],
                results: result_values,
            },
            entry,
        )
        .unwrap();
        isel.finalize().blocks[&entry]
            .insts
            .iter()
            .find(|inst| inst.opcode == X86Opcode::Call)
            .expect("lowered call")
            .call_result_regs
            .clone()
            .expect("every call has explicit result metadata")
    }

    #[test]
    fn test_call_result_metadata_is_exact_for_void_scalar_and_multireg_both_abis() {
        for abi in [X86CallAbi::SystemV, X86CallAbi::WindowsX64] {
            assert_eq!(lowered_call_result_metadata(abi, vec![]), vec![]);
            assert_eq!(
                lowered_call_result_metadata(abi, vec![Type::I8]),
                vec![X86CallResultReg::new(RAX, 8)]
            );
            assert_eq!(
                lowered_call_result_metadata(abi, vec![Type::I64]),
                vec![X86CallResultReg::new(RAX, 64)]
            );
            assert_eq!(
                lowered_call_result_metadata(abi, vec![Type::F32]),
                vec![X86CallResultReg::new(XMM0, 32)]
            );
            assert_eq!(
                lowered_call_result_metadata(abi, vec![Type::F64]),
                vec![X86CallResultReg::new(XMM0, 64)]
            );
            assert_eq!(
                lowered_call_result_metadata(abi, vec![Type::I64, Type::I64]),
                vec![
                    X86CallResultReg::new(RAX, 64),
                    X86CallResultReg::new(RDX, 64),
                ]
            );
            assert_eq!(
                lowered_call_result_metadata(abi, vec![Type::I8, Type::I16]),
                vec![
                    X86CallResultReg::new(RAX, 8),
                    X86CallResultReg::new(RDX, 16),
                ]
            );
            assert_eq!(
                lowered_call_result_metadata(abi, vec![Type::F64, Type::F64]),
                vec![
                    X86CallResultReg::new(XMM0, 64),
                    X86CallResultReg::new(XMM1, 64),
                ]
            );
            assert_eq!(
                lowered_call_result_metadata(abi, vec![Type::F32, Type::F64]),
                vec![
                    X86CallResultReg::new(XMM0, 32),
                    X86CallResultReg::new(XMM1, 64),
                ]
            );
        }
    }

    #[test]
    fn test_lower_call_mixed_scalar_results_use_independent_return_sequences() {
        let result_types = [Type::I64, Type::F64, Type::I32, Type::F32];
        for abi in [X86CallAbi::SystemV, X86CallAbi::WindowsX64] {
            let sig = Signature {
                params: vec![],
                returns: vec![],
            };
            let mut isel = X86InstructionSelector::with_abi("caller".to_string(), sig, abi);
            let entry = Block(0);
            isel.func.ensure_block(entry);
            let result_values = [Value(0), Value(1), Value(2), Value(3)];
            isel.seed_value_types(
                &result_values
                    .iter()
                    .copied()
                    .zip(result_types.iter().cloned())
                    .collect(),
            );

            isel.lower_call(
                "callee",
                &Instruction {
                    opcode: Opcode::Call {
                        name: "callee".to_string(),
                    },
                    args: vec![],
                    results: result_values.to_vec(),
                },
                entry,
            )
            .unwrap();

            let mfunc = isel.finalize();
            let insts = &mfunc.blocks[&entry].insts;
            assert_eq!(insts.len(), 5, "{abi:?}: {insts:?}");
            assert_eq!(
                insts[0].call_result_regs,
                Some(vec![
                    X86CallResultReg::new(RAX, 64),
                    X86CallResultReg::new(XMM0, 64),
                    X86CallResultReg::new(RDX, 32),
                    X86CallResultReg::new(XMM1, 32),
                ]),
                "{abi:?}"
            );
            assert_eq!(insts[0].opcode, X86Opcode::Call);
            assert_eq!(insts[1].operands[1], X86ISelOperand::PReg(RAX));
            assert_eq!(insts[2].operands[1], X86ISelOperand::PReg(XMM0));
            assert_eq!(insts[3].operands[1], X86ISelOperand::PReg(EDX));
            assert_eq!(insts[4].operands[1], X86ISelOperand::PReg(XMM1));
        }
    }

    #[test]
    fn test_lower_call_rejects_third_same_class_result_without_aliasing() {
        let cases = [
            (vec![Type::I64, Type::I32, Type::I8], Type::I8),
            (vec![Type::F64, Type::F32, Type::F64], Type::F64),
        ];
        for abi in [X86CallAbi::SystemV, X86CallAbi::WindowsX64] {
            for (result_types, rejected_type) in &cases {
                let sig = Signature {
                    params: vec![],
                    returns: vec![],
                };
                let mut isel = X86InstructionSelector::with_abi("caller".to_string(), sig, abi);
                let entry = Block(0);
                isel.func.ensure_block(entry);
                let result_values = [Value(0), Value(1), Value(2)];
                isel.seed_value_types(
                    &result_values
                        .iter()
                        .copied()
                        .zip(result_types.iter().cloned())
                        .collect(),
                );

                let error = isel
                    .lower_call(
                        "callee",
                        &Instruction {
                            opcode: Opcode::Call {
                                name: "callee".to_string(),
                            },
                            args: vec![],
                            results: result_values.to_vec(),
                        },
                        entry,
                    )
                    .unwrap_err();

                assert!(matches!(
                    error,
                    X86ISelError::UnsupportedScalarReturnAbi {
                        index: 2,
                        ty,
                        abi: actual_abi,
                        reason,
                    } if actual_abi == abi
                        && ty == *rejected_type
                        && reason.contains("capacity is exhausted")
                ));
                assert!(
                    isel.func.blocks[&entry].insts.is_empty(),
                    "{abi:?} {result_types:?} must reject before emitting a call or partial extraction"
                );
            }
        }
    }

    #[test]
    fn test_call_result_metadata_tracks_register_aggregate_i128_and_sret_paths() {
        for abi in [X86CallAbi::SystemV, X86CallAbi::WindowsX64] {
            assert_eq!(
                lowered_call_result_metadata(abi, vec![Type::Struct(vec![Type::I8])]),
                vec![X86CallResultReg::new(RAX, 8)]
            );
        }
        assert_eq!(
            lowered_call_result_metadata(
                X86CallAbi::SystemV,
                vec![Type::Struct(vec![Type::I64, Type::F64])],
            ),
            vec![
                X86CallResultReg::new(RAX, 64),
                X86CallResultReg::new(XMM0, 64),
            ]
        );
        assert_eq!(
            lowered_call_result_metadata(
                X86CallAbi::SystemV,
                vec![Type::Struct(vec![Type::I32, Type::I32, Type::I32])],
            ),
            vec![
                X86CallResultReg::new(RAX, 64),
                X86CallResultReg::new(RDX, 32),
            ]
        );
        assert_eq!(
            lowered_call_result_metadata(X86CallAbi::SystemV, vec![Type::I128]),
            vec![
                X86CallResultReg::new(RAX, 64),
                X86CallResultReg::new(RDX, 64),
            ]
        );
        for abi in [X86CallAbi::SystemV, X86CallAbi::WindowsX64] {
            assert_eq!(
                lowered_call_result_metadata(
                    abi,
                    vec![Type::Struct(vec![Type::I64, Type::I64, Type::I64])],
                ),
                vec![],
                "sret returns are memory results under {abi:?}"
            );
        }
    }

    #[test]
    fn test_lower_call_system_v() {
        let sig = Signature {
            params: vec![Type::I64, Type::I64],
            returns: vec![Type::I64],
        };
        let mut isel = X86InstructionSelector::new("caller".to_string(), sig);
        let entry = Block(0);
        isel.func.ensure_block(entry);

        // Define arg values
        define_vreg(&mut isel, Value(0), Type::I64);
        define_vreg(&mut isel, Value(1), Type::I64);

        isel.lower_call(
            "callee",
            &Instruction {
                opcode: Opcode::Call {
                    name: "callee".to_string(),
                },
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;

        // Should have: MOV RDI, arg0 + MOV RSI, arg1 + CALL + MOV result, RAX
        assert_eq!(insts.len(), 4);

        // First arg goes to RDI
        assert_eq!(insts[0].opcode, X86Opcode::MovRR);
        assert_eq!(insts[0].operands[0], X86ISelOperand::PReg(RDI));

        // Second arg goes to RSI
        assert_eq!(insts[1].opcode, X86Opcode::MovRR);
        assert_eq!(insts[1].operands[0], X86ISelOperand::PReg(RSI));

        // CALL callee
        assert_eq!(insts[2].opcode, X86Opcode::Call);
        assert_eq!(
            insts[2].call_result_regs,
            Some(vec![X86CallResultReg::new(RAX, 64)])
        );
        assert_eq!(
            insts[2].operands[0],
            X86ISelOperand::Symbol("callee".to_string())
        );

        // Result copied from RAX
        assert_eq!(insts[3].opcode, X86Opcode::MovRR);
        assert_eq!(insts[3].operands[1], X86ISelOperand::PReg(RAX));
    }

