    #[test]
    fn test_lower_call_indirect_windows_x64_uses_callr_and_tracks_shadow_space() {
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut isel =
            X86InstructionSelector::with_abi("caller".to_string(), sig, X86CallAbi::WindowsX64);
        let entry = Block(0);
        isel.func.ensure_block(entry);

        let callee = define_vreg(&mut isel, Value(0), Type::I64);
        let args: Vec<VReg> = (1..=4u32)
            .map(|idx| define_vreg(&mut isel, Value(idx), Type::I64))
            .collect();

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::CallIndirect,
                args: (0..=4u32).map(Value).collect(),
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        assert_no_rsp_adjusts(insts);
        assert_eq!(mfunc.max_outgoing_call_bytes, 32);
        assert_eq!(insts.len(), 5);

        for (idx, expected_reg) in [RCX, RDX, R8, R9].into_iter().enumerate() {
            assert_eq!(insts[idx].opcode, X86Opcode::MovRR);
            assert_eq!(insts[idx].operands[0], X86ISelOperand::PReg(expected_reg));
            assert_eq!(insts[idx].operands[1], X86ISelOperand::VReg(args[idx]));
        }
        assert_eq!(insts[4].opcode, X86Opcode::CallR);
        assert_eq!(insts[4].operands, vec![X86ISelOperand::VReg(callee)]);
    }

