    #[test]
    fn test_memory_intrinsic_passes_address_carried_aggregate_as_pointer() {
        for (abi, expected_regs) in [
            (X86CallAbi::SystemV, [RDI, RSI, RDX]),
            (X86CallAbi::WindowsX64, [RCX, RDX, R8]),
        ] {
            let sig = Signature {
                params: vec![],
                returns: vec![],
            };
            let mut isel = X86InstructionSelector::with_abi("caller".to_string(), sig, abi);
            let entry = Block(0);
            isel.func.ensure_block(entry);

            define_vreg(&mut isel, Value(0), Type::I64);
            let source_addr = define_vreg(
                &mut isel,
                Value(1),
                Type::Struct(vec![Type::I64, Type::I64]),
            );
            define_vreg(&mut isel, Value(2), Type::I64);

            isel.select_instruction(
                &Instruction {
                    opcode: Opcode::Memmove,
                    args: vec![Value(0), Value(1), Value(2)],
                    results: vec![],
                },
                entry,
            )
            .unwrap();

            let mfunc = isel.finalize();
            let insts = &mfunc.blocks[&entry].insts;
            assert_eq!(insts.len(), 4, "{abi:?}: {insts:?}");
            for (idx, reg) in expected_regs.into_iter().enumerate() {
                assert_eq!(insts[idx].opcode, X86Opcode::MovRR, "{abi:?}");
                assert_eq!(insts[idx].operands[0], X86ISelOperand::PReg(reg));
            }
            assert_eq!(
                insts[1].operands[1],
                X86ISelOperand::VReg(source_addr),
                "{abi:?} must pass the aggregate's address, not load its lanes"
            );
            assert_eq!(insts[3].opcode, X86Opcode::Call);
            assert_eq!(
                insts[3].call_arg_regs,
                expected_regs
                    .into_iter()
                    .map(|reg| X86CallArgReg::new(reg, 64))
                    .collect::<Vec<_>>()
            );
        }
    }

    #[test]
    fn test_select_memory_intrinsics_fail_closed_for_extra_operands_and_results() {
        let (mut isel, entry) = make_empty_isel();
        for idx in 0..4u32 {
            define_vreg(&mut isel, Value(idx), Type::I64);
        }

        let err = isel
            .select_instruction(
                &Instruction {
                    opcode: Opcode::Memcpy,
                    args: vec![Value(0), Value(1), Value(2), Value(3)],
                    results: vec![],
                },
                entry,
            )
            .unwrap_err();
        assert!(matches!(
            err,
            X86ISelError::WrongArgCount {
                expected: 3,
                actual: 4,
                context: "Memcpy"
            }
        ));

        let err = isel
            .select_instruction(
                &Instruction {
                    opcode: Opcode::Memset,
                    args: vec![Value(0), Value(1), Value(2)],
                    results: vec![Value(4)],
                },
                entry,
            )
            .unwrap_err();
        assert!(
            matches!(err, X86ISelError::UnsupportedOpcode(ref msg) if msg.contains("Memset with result values")),
            "unexpected error: {err:?}"
        );
    }

    #[test]
    fn test_lower_call_large_struct_arg() {
        // A >16-byte struct is SysV MEMORY class: passed by value on the stack
        // (accepted). Windows x64 has no MEMORY-class by-value path for this
        // shape, so it still fails closed.
        let large = Type::Struct(vec![Type::I64, Type::I64, Type::I64]);
        assert!(is_sysv_memory_byval_aggregate(&large, X86CallAbi::SystemV));
        assert_call_arg_lowers_sysv_memory_byval(large.clone());
        assert_call_arg_rejects_aggregate(large, X86CallAbi::WindowsX64);
    }

    #[test]
    fn test_lower_call_rejects_mixed_and_sse_aggregate_args() {
        for aggregate_ty in [
            Type::Struct(vec![Type::I64, Type::F64]),
            Type::Struct(vec![Type::F64, Type::I64]),
            Type::Struct(vec![Type::F64, Type::F64]),
            Type::Array(Box::new(Type::F64), 2),
            Type::Struct(vec![Type::V128]),
            Type::Array(Box::new(Type::V128), 1),
        ] {
            assert_call_arg_rejects_aggregate(aggregate_ty, X86CallAbi::WindowsX64);
        }
    }

    #[test]
    fn test_lower_call_sysv_mixed_and_sse_aggregate_args_load_abi_lanes() {
        for (aggregate_ty, expected_lanes) in [
            (
                Type::Struct(vec![Type::I64, Type::F64]),
                vec![(X86Opcode::MovRM, RDI, 0), (X86Opcode::MovsdRM, XMM0, 8)],
            ),
            (
                Type::Struct(vec![Type::F64, Type::I64]),
                vec![(X86Opcode::MovsdRM, XMM0, 0), (X86Opcode::MovRM, RDI, 8)],
            ),
            (
                Type::Struct(vec![Type::F64, Type::F64]),
                vec![(X86Opcode::MovsdRM, XMM0, 0), (X86Opcode::MovsdRM, XMM1, 8)],
            ),
            (
                Type::Array(Box::new(Type::F64), 2),
                vec![(X86Opcode::MovsdRM, XMM0, 0), (X86Opcode::MovsdRM, XMM1, 8)],
            ),
        ] {
            let sig = Signature {
                params: vec![],
                returns: vec![],
            };
            let mut isel =
                X86InstructionSelector::with_abi("caller".to_string(), sig, X86CallAbi::SystemV);
            let entry = Block(0);
            isel.func.ensure_block(entry);
            isel.seed_value_types(&HashMap::from([(Value(0), aggregate_ty)]));
            isel.select_instruction(
                &Instruction {
                    opcode: Opcode::StackAddr { slot: 0 },
                    args: vec![],
                    results: vec![Value(0)],
                },
                entry,
            )
            .unwrap();

            isel.lower_call(
                "callee",
                &Instruction {
                    opcode: Opcode::Call {
                        name: "callee".to_string(),
                    },
                    args: vec![Value(0)],
                    results: vec![],
                },
                entry,
            )
            .unwrap();

            let mfunc = isel.finalize();
            let insts = &mfunc.blocks[&entry].insts;
            let aggregate_addr = insts[0].operands[0].clone();
            assert_eq!(insts[0].opcode, X86Opcode::Lea);
            for (idx, (opcode, reg, disp)) in expected_lanes.iter().enumerate() {
                let inst = &insts[1 + idx];
                assert_eq!(inst.opcode, *opcode);
                assert_eq!(inst.operands[0], X86ISelOperand::PReg(*reg));
                assert_eq!(
                    inst.operands[1],
                    X86ISelOperand::MemAddr {
                        base: Box::new(aggregate_addr.clone()),
                        disp: *disp,
                    }
                );
            }
            assert_eq!(insts[1 + expected_lanes.len()].opcode, X86Opcode::Call);
        }
    }

    #[test]
    fn test_lower_call_sysv_sse_aggregate_preserves_following_gpr_sequence() {
        let aggregate_ty = Type::Struct(vec![Type::F64, Type::F64]);
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut isel =
            X86InstructionSelector::with_abi("caller".to_string(), sig, X86CallAbi::SystemV);
        let entry = Block(0);
        isel.func.ensure_block(entry);
        isel.seed_value_types(&HashMap::from([(Value(0), aggregate_ty)]));
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::StackAddr { slot: 0 },
                args: vec![],
                results: vec![Value(0)],
            },
            entry,
        )
        .unwrap();
        define_vreg(&mut isel, Value(1), Type::I64);

        isel.lower_call(
            "callee",
            &Instruction {
                opcode: Opcode::Call {
                    name: "callee".to_string(),
                },
                args: vec![Value(0), Value(1)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        assert_eq!(insts[1].opcode, X86Opcode::MovsdRM);
        assert_eq!(insts[1].operands[0], X86ISelOperand::PReg(XMM0));
        assert_eq!(insts[2].opcode, X86Opcode::MovsdRM);
        assert_eq!(insts[2].operands[0], X86ISelOperand::PReg(XMM1));
        assert_eq!(insts[3].opcode, X86Opcode::MovRR);
        assert_eq!(insts[3].operands[0], X86ISelOperand::PReg(RDI));
        assert_eq!(insts[4].opcode, X86Opcode::Call);
    }

