    #[test]
    fn test_lower_call_sysv_v128_carrier_uses_one_xmm_and_preserves_sequences() {
        let aggregate_ty = Type::Struct(vec![Type::V128]);
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut isel =
            X86InstructionSelector::with_abi("caller".to_string(), sig, X86CallAbi::SystemV);
        let entry = Block(0);
        isel.func.ensure_block(entry);
        isel.set_stack_slots(vec![StackSlotInfo::new(16, 16)]);
        isel.seed_value_types(&HashMap::from([(Value(0), aggregate_ty)]));
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::StackAddr { slot: 0 },
                args: vec![],
                results: vec![Value(0)],
            },
            entry,
        )
        .unwrap();
        define_vreg(&mut isel, Value(1), Type::I64);
        define_vreg(&mut isel, Value(2), Type::F64);

        isel.lower_call(
            "callee",
            &Instruction {
                opcode: Opcode::Call {
                    name: "callee".to_string(),
                },
                args: vec![Value(0), Value(1), Value(2)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        let aggregate_addr = insts[0].operands[0].clone();
        assert_eq!(insts.len(), 5);
        assert_eq!(insts[1].opcode, X86Opcode::MovdquRM);
        assert_eq!(insts[1].operands[0], X86ISelOperand::PReg(XMM0));
        assert_eq!(
            insts[1].operands[1],
            X86ISelOperand::MemAddr {
                base: Box::new(aggregate_addr),
                disp: 0,
            }
        );
        assert_eq!(insts[2].opcode, X86Opcode::MovRR);
        assert_eq!(insts[2].operands[0], X86ISelOperand::PReg(RDI));
        assert_eq!(insts[3].opcode, X86Opcode::MovsdRR);
        assert_eq!(insts[3].operands[0], X86ISelOperand::PReg(XMM1));
        assert_eq!(insts[4].opcode, X86Opcode::Call);
    }

    #[test]
    fn test_lower_call_sysv_v128_carrier_stack_fallback_is_16_byte_aligned() {
        let aggregate_ty = Type::Struct(vec![Type::V128]);
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut isel =
            X86InstructionSelector::with_abi("caller".to_string(), sig, X86CallAbi::SystemV);
        let entry = Block(0);
        let aggregate_value = Value(15);
        isel.func.ensure_block(entry);
        isel.set_stack_slots(vec![StackSlotInfo::new(16, 16)]);
        isel.seed_value_types(&HashMap::from([(aggregate_value, aggregate_ty)]));
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::StackAddr { slot: 0 },
                args: vec![],
                results: vec![aggregate_value],
            },
            entry,
        )
        .unwrap();
        for i in 0..8u32 {
            define_vreg(&mut isel, Value(i), Type::F64);
        }
        for i in 8..=14u32 {
            define_vreg(&mut isel, Value(i), Type::I64);
        }
        let mut args: Vec<Value> = (0..8u32).map(Value).collect();
        args.extend((8..=14u32).map(Value));
        args.push(aggregate_value);

        isel.lower_call(
            "callee",
            &Instruction {
                opcode: Opcode::Call {
                    name: "callee".to_string(),
                },
                args,
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        assert_eq!(insts[1].opcode, X86Opcode::SubRI);
        assert_eq!(insts[1].operands[1], X86ISelOperand::Imm(32));

        let rsp_store_disps = insts
            .iter()
            .filter_map(|inst| match inst.operands.first() {
                Some(X86ISelOperand::MemAddr { base, disp })
                    if base.as_ref() == &X86ISelOperand::PReg(RSP) =>
                {
                    Some(*disp)
                }
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(rsp_store_disps.contains(&0));
        assert!(rsp_store_disps.contains(&16));
        assert!(rsp_store_disps.contains(&24));
        assert!(
            !rsp_store_disps.contains(&8),
            "V128 carrier stack fallback must leave the padding eightbyte unused: {insts:?}"
        );
    }

    #[test]
    fn test_lower_call_sysv_mixed_aggregate_stack_fallback_preserves_tail_xmm() {
        let aggregate_ty = Type::Struct(vec![Type::I64, Type::F64]);
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut isel =
            X86InstructionSelector::with_abi("caller".to_string(), sig, X86CallAbi::SystemV);
        let entry = Block(0);
        let aggregate_value = Value(6);
        isel.func.ensure_block(entry);
        isel.set_stack_slots(vec![StackSlotInfo::new(16, 8)]);
        isel.seed_value_types(&HashMap::from([(aggregate_value, aggregate_ty)]));
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::StackAddr { slot: 0 },
                args: vec![],
                results: vec![aggregate_value],
            },
            entry,
        )
        .unwrap();
        for i in 0..6u32 {
            define_vreg(&mut isel, Value(i), Type::I64);
        }
        define_vreg(&mut isel, Value(7), Type::F64);
        let mut args: Vec<Value> = (0..6u32).map(Value).collect();
        args.push(aggregate_value);
        args.push(Value(7));

        isel.lower_call(
            "callee",
            &Instruction {
                opcode: Opcode::Call {
                    name: "callee".to_string(),
                },
                args,
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        let aggregate_addr = insts[0].operands[0].clone();

        assert_eq!(insts.len(), 15);
        assert_eq!(insts[1].opcode, X86Opcode::SubRI);
        assert_eq!(insts[1].operands[1], X86ISelOperand::Imm(16));
        for (idx, disp) in [0, 8].into_iter().enumerate() {
            let load = &insts[2 + idx * 2];
            let store = &insts[3 + idx * 2];
            assert_eq!(load.opcode, X86Opcode::MovRM);
            assert_eq!(
                load.operands[1],
                X86ISelOperand::MemAddr {
                    base: Box::new(aggregate_addr.clone()),
                    disp,
                }
            );
            assert_eq!(store.opcode, X86Opcode::MovMR);
            assert_eq!(
                store.operands[0],
                X86ISelOperand::MemAddr {
                    base: Box::new(X86ISelOperand::PReg(RSP)),
                    disp,
                }
            );
            assert_eq!(store.operands[1], load.operands[0]);
        }
        for (idx, reg) in [RDI, RSI, RDX, RCX, R8, R9].into_iter().enumerate() {
            assert_eq!(insts[6 + idx].opcode, X86Opcode::MovRR);
            assert_eq!(insts[6 + idx].operands[0], X86ISelOperand::PReg(reg));
        }
        assert_eq!(insts[12].opcode, X86Opcode::MovsdRR);
        assert_eq!(insts[12].operands[0], X86ISelOperand::PReg(XMM0));
        assert_eq!(insts[13].opcode, X86Opcode::Call);
        assert_eq!(insts[14].opcode, X86Opcode::AddRI);
        assert_eq!(insts[14].operands[1], X86ISelOperand::Imm(16));
    }

    #[test]
    fn test_lower_call_sysv_mixed_aggregate_xmm_exhaustion_preserves_tail_gpr() {
        let aggregate_ty = Type::Struct(vec![Type::I64, Type::F64]);
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut isel =
            X86InstructionSelector::with_abi("caller".to_string(), sig, X86CallAbi::SystemV);
        let entry = Block(0);
        let aggregate_value = Value(8);
        isel.func.ensure_block(entry);
        isel.set_stack_slots(vec![StackSlotInfo::new(16, 8)]);
        isel.seed_value_types(&HashMap::from([(aggregate_value, aggregate_ty)]));
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::StackAddr { slot: 0 },
                args: vec![],
                results: vec![aggregate_value],
            },
            entry,
        )
        .unwrap();
        for i in 0..8u32 {
            define_vreg(&mut isel, Value(i), Type::F64);
        }
        define_vreg(&mut isel, Value(9), Type::I64);
        let mut args: Vec<Value> = (0..8u32).map(Value).collect();
        args.push(aggregate_value);
        args.push(Value(9));

        isel.lower_call(
            "callee",
            &Instruction {
                opcode: Opcode::Call {
                    name: "callee".to_string(),
                },
                args,
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        let aggregate_addr = insts[0].operands[0].clone();

        assert_eq!(insts.len(), 17);
        assert_eq!(insts[1].opcode, X86Opcode::SubRI);
        assert_eq!(insts[1].operands[1], X86ISelOperand::Imm(16));
        for (idx, disp) in [0, 8].into_iter().enumerate() {
            let load = &insts[2 + idx * 2];
            let store = &insts[3 + idx * 2];
            assert_eq!(load.opcode, X86Opcode::MovRM);
            assert_eq!(
                load.operands[1],
                X86ISelOperand::MemAddr {
                    base: Box::new(aggregate_addr.clone()),
                    disp,
                }
            );
            assert_eq!(store.opcode, X86Opcode::MovMR);
            assert_eq!(
                store.operands[0],
                X86ISelOperand::MemAddr {
                    base: Box::new(X86ISelOperand::PReg(RSP)),
                    disp,
                }
            );
            assert_eq!(store.operands[1], load.operands[0]);
        }
        for idx in 0..8 {
            assert_eq!(insts[6 + idx].opcode, X86Opcode::MovsdRR);
        }
        assert_eq!(insts[14].opcode, X86Opcode::MovRR);
        assert_eq!(insts[14].operands[0], X86ISelOperand::PReg(RDI));
        assert_eq!(insts[15].opcode, X86Opcode::Call);
        assert_eq!(insts[16].opcode, X86Opcode::AddRI);
        assert_eq!(insts[16].operands[1], X86ISelOperand::Imm(16));
    }

    #[test]
    fn test_lower_call_sysv_sse_aggregate_stack_fallback_preserves_tail_gpr() {
        let aggregate_ty = Type::Struct(vec![Type::F64, Type::F64]);
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut isel =
            X86InstructionSelector::with_abi("caller".to_string(), sig, X86CallAbi::SystemV);
        let entry = Block(0);
        let aggregate_value = Value(8);
        isel.func.ensure_block(entry);
        isel.set_stack_slots(vec![StackSlotInfo::new(16, 8)]);
        isel.seed_value_types(&HashMap::from([(aggregate_value, aggregate_ty)]));
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::StackAddr { slot: 0 },
                args: vec![],
                results: vec![aggregate_value],
            },
            entry,
        )
        .unwrap();
        for i in 0..8u32 {
            define_vreg(&mut isel, Value(i), Type::F64);
        }
        define_vreg(&mut isel, Value(9), Type::I64);
        let mut args: Vec<Value> = (0..8u32).map(Value).collect();
        args.push(aggregate_value);
        args.push(Value(9));

        isel.lower_call(
            "callee",
            &Instruction {
                opcode: Opcode::Call {
                    name: "callee".to_string(),
                },
                args,
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        let aggregate_addr = insts[0].operands[0].clone();

        assert_eq!(insts.len(), 17);
        assert_eq!(insts[1].opcode, X86Opcode::SubRI);
        assert_eq!(insts[1].operands[1], X86ISelOperand::Imm(16));
        for (idx, disp) in [0, 8].into_iter().enumerate() {
            let load = &insts[2 + idx * 2];
            let store = &insts[3 + idx * 2];
            assert_eq!(load.opcode, X86Opcode::MovRM);
            assert_eq!(
                load.operands[1],
                X86ISelOperand::MemAddr {
                    base: Box::new(aggregate_addr.clone()),
                    disp,
                }
            );
            assert_eq!(store.opcode, X86Opcode::MovMR);
            assert_eq!(
                store.operands[0],
                X86ISelOperand::MemAddr {
                    base: Box::new(X86ISelOperand::PReg(RSP)),
                    disp,
                }
            );
            assert_eq!(store.operands[1], load.operands[0]);
        }
        for idx in 0..8 {
            assert_eq!(insts[6 + idx].opcode, X86Opcode::MovsdRR);
        }
        assert_eq!(insts[14].opcode, X86Opcode::MovRR);
        assert_eq!(insts[14].operands[0], X86ISelOperand::PReg(RDI));
        assert_eq!(insts[15].opcode, X86Opcode::Call);
        assert_eq!(insts[16].opcode, X86Opcode::AddRI);
        assert_eq!(insts[16].operands[1], X86ISelOperand::Imm(16));
    }

    #[test]
    fn test_lower_call_rejects_unsupported_single_lane_aggregate_args() {
        // `{B1}` (1-byte) now lowers on SysV (a 1-byte INTEGER eightbyte arg in a
        // GPR — see test_sysv_subdword_aggregates_supported_all_positions); still
        // rejected on Windows x64. Single-SSE aggregates classify on SysV (XMM) but
        // are rejected on Windows x64.
        for aggregate_ty in [
            Type::Struct(vec![Type::B1]),
            Type::Array(Box::new(Type::B1), 1),
        ] {
            assert_call_arg_rejects_aggregate(aggregate_ty, X86CallAbi::WindowsX64);
        }
        for aggregate_ty in [
            Type::Struct(vec![Type::F32]),
            Type::Array(Box::new(Type::F32), 1),
            Type::Struct(vec![Type::F64]),
            Type::Array(Box::new(Type::F64), 1),
        ] {
            assert_call_arg_rejects_aggregate(aggregate_ty, X86CallAbi::WindowsX64);
        }
    }

    #[test]
    fn test_lower_call_rejects_non_exact_integer_aggregate_args() {
        // Valid SysV register aggregates; still rejected on Windows x64.
        for aggregate_ty in [
            Type::Struct(vec![Type::I32, Type::I32]),
            Type::Array(Box::new(Type::I32), 2),
            Type::Array(Box::new(Type::I8), 8),
            Type::Struct(vec![Type::I16, Type::I16, Type::I16, Type::I16]),
            Type::Struct(vec![Type::I64, Type::I32]),
            Type::Struct(vec![Type::I32, Type::I32, Type::I32]),
            Type::Array(Box::new(Type::I32), 3),
        ] {
            assert!(
                classify_sysv_register_aggregate(&aggregate_ty, X86CallAbi::SystemV).is_some(),
                "{aggregate_ty:?} should classify as a SysV register aggregate"
            );
            assert_call_arg_rejects_aggregate(aggregate_ty, X86CallAbi::WindowsX64);
        }
    }

    #[test]
    fn test_lower_call_sysv_v128_carrier_boundary_args() {
        // Nested single V128 is the SSE carrier (one XMM, register-passed).
        assert!(
            classify_sysv_register_aggregate(
                &Type::Struct(vec![Type::Struct(vec![Type::V128])]),
                X86CallAbi::SystemV,
            )
            .is_some(),
            "nested single V128 should classify as the SSE vector carrier"
        );
        // The >16-byte mixes are not register aggregates: they are SysV MEMORY
        // class and now pass *by value on the stack*. They never classify as a
        // register aggregate, and SysV call lowering accepts them (byte-copied
        // to the outgoing argument area). Windows x64 has no such MEMORY path
        // for these shapes, so it still fails closed.
        for aggregate_ty in [
            Type::Struct(vec![Type::V128, Type::I64]),
            Type::Array(Box::new(Type::V128), 2),
        ] {
            assert!(
                classify_sysv_register_aggregate(&aggregate_ty, X86CallAbi::SystemV).is_none(),
                "{aggregate_ty:?} is >16 bytes and must not classify as a register aggregate"
            );
            assert!(
                is_sysv_memory_byval_aggregate(&aggregate_ty, X86CallAbi::SystemV),
                "{aggregate_ty:?} should be a SysV MEMORY-class by-value aggregate"
            );
            assert_call_arg_lowers_sysv_memory_byval(aggregate_ty.clone());
            assert_call_arg_rejects_aggregate(aggregate_ty, X86CallAbi::WindowsX64);
        }
    }

    #[test]
    fn test_lower_call_zero_sized_nested_sysv_aggregate_arg_classifies_without_panic() {
        // A zero-sized leading field contributes no eightbyte; the remaining
        // {i64, f64} classifies as INTEGER + SSE (RDI + XMM0). The point of this
        // regression is that the recursive leaf walk handles the empty struct
        // without panicking.
        let aggregate_ty = Type::Struct(vec![Type::Struct(vec![]), Type::I64, Type::F64]);
        let layout =
            classify_sysv_register_aggregate(&aggregate_ty, X86CallAbi::SystemV).expect("classify");
        assert_eq!(layout.gpr_count(), 1);
        assert_eq!(layout.xmm_count(), 1);
    }

    #[test]
    fn test_lower_call_single_integer_aggregate_arg_loads_register_slot() {
        for (aggregate_ty, expected_opcode, expected_sysv_reg, expected_windows_reg) in [
            (Type::Struct(vec![Type::I32]), X86Opcode::MovRM32, EDI, ECX),
            (Type::Struct(vec![Type::I64]), X86Opcode::MovRM, RDI, RCX),
            (
                Type::Array(Box::new(Type::I32), 1),
                X86Opcode::MovRM32,
                EDI,
                ECX,
            ),
        ] {
            for (abi, expected_reg) in [
                (X86CallAbi::SystemV, expected_sysv_reg),
                (X86CallAbi::WindowsX64, expected_windows_reg),
            ] {
                let sig = Signature {
                    params: vec![],
                    returns: vec![],
                };
                let mut isel = X86InstructionSelector::with_abi("caller".to_string(), sig, abi);
                let entry = Block(0);
                isel.func.ensure_block(entry);
                isel.seed_value_types(&HashMap::from([(Value(0), aggregate_ty.clone())]));
                isel.select_instruction(
                    &Instruction {
                        opcode: Opcode::StackAddr { slot: 0 },
                        args: vec![],
                        results: vec![Value(0)],
                    },
                    entry,
                )
                .unwrap();

                isel.lower_call(
                    "callee",
                    &Instruction {
                        opcode: Opcode::Call {
                            name: "callee".to_string(),
                        },
                        args: vec![Value(0)],
                        results: vec![],
                    },
                    entry,
                )
                .unwrap();

                let mfunc = isel.finalize();
                let insts = &mfunc.blocks[&entry].insts;
                let load_idx = 1;
                let call_idx = 2;

                assert_eq!(insts[0].opcode, X86Opcode::Lea);
                if abi == X86CallAbi::WindowsX64 {
                    assert_no_rsp_adjusts(insts);
                    assert_eq!(mfunc.max_outgoing_call_bytes, 32);
                }
                assert_eq!(insts[load_idx].opcode, expected_opcode);
                assert_eq!(
                    insts[load_idx].operands[0],
                    X86ISelOperand::PReg(expected_reg)
                );
                assert_eq!(
                    insts[load_idx].operands[1],
                    X86ISelOperand::MemAddr {
                        base: Box::new(insts[0].operands[0].clone()),
                        disp: 0,
                    }
                );
                assert_eq!(insts[call_idx].opcode, X86Opcode::Call);
            }
        }
    }

