    #[test]
    fn test_lower_call_single_integer_aggregate_arg_spills_stack_lane() {
        for (aggregate_ty, expected_load_opcode, expected_store_opcode) in [
            (
                Type::Struct(vec![Type::I32]),
                X86Opcode::MovRM32,
                X86Opcode::MovMR32,
            ),
            (
                Type::Struct(vec![Type::I64]),
                X86Opcode::MovRM,
                X86Opcode::MovMR,
            ),
        ] {
            for (abi, expected_stack_alloc, expected_stack_disp) in [
                (X86CallAbi::SystemV, 16, 0),
                (X86CallAbi::WindowsX64, 64, 48),
            ] {
                let sig = Signature {
                    params: vec![],
                    returns: vec![],
                };
                let mut isel = X86InstructionSelector::with_abi("caller".to_string(), sig, abi);
                let entry = Block(0);
                let aggregate_value = Value(6);
                isel.func.ensure_block(entry);
                isel.seed_value_types(&HashMap::from([(aggregate_value, aggregate_ty.clone())]));
                isel.select_instruction(
                    &Instruction {
                        opcode: Opcode::StackAddr { slot: 0 },
                        args: vec![],
                        results: vec![aggregate_value],
                    },
                    entry,
                )
                .unwrap();
                for i in 0..6u32 {
                    define_vreg(&mut isel, Value(i), Type::I64);
                }
                let mut args: Vec<Value> = (0..6u32).map(Value).collect();
                args.push(aggregate_value);

                isel.lower_call(
                    "callee",
                    &Instruction {
                        opcode: Opcode::Call {
                            name: "callee".to_string(),
                        },
                        args,
                        results: vec![],
                    },
                    entry,
                )
                .unwrap();

                let mfunc = isel.finalize();
                let insts = &mfunc.blocks[&entry].insts;
                let aggregate_addr = insts[0].operands[0].clone();
                if abi == X86CallAbi::SystemV {
                    assert_eq!(insts[1].opcode, X86Opcode::SubRI);
                    assert_eq!(
                        insts[1].operands[1],
                        X86ISelOperand::Imm(expected_stack_alloc)
                    );
                } else {
                    assert_no_rsp_adjusts(insts);
                    assert_eq!(mfunc.max_outgoing_call_bytes, expected_stack_alloc as u32);
                }

                let aggregate_load_idx = insts
                    .iter()
                    .position(|inst| {
                        inst.opcode == expected_load_opcode
                            && inst.operands[1]
                                == X86ISelOperand::MemAddr {
                                    base: Box::new(aggregate_addr.clone()),
                                    disp: 0,
                                }
                    })
                    .expect("single integer aggregate stack arg must load its lane");
                let aggregate_store = &insts[aggregate_load_idx + 1];
                assert_eq!(aggregate_store.opcode, expected_store_opcode);
                assert_eq!(
                    aggregate_store.operands[0],
                    X86ISelOperand::MemAddr {
                        base: Box::new(X86ISelOperand::PReg(RSP)),
                        disp: expected_stack_disp,
                    }
                );
                assert_eq!(
                    aggregate_store.operands[1],
                    insts[aggregate_load_idx].operands[0]
                );
            }
        }
    }

    #[test]
    fn test_lower_call_sysv_i128_stack_rollback_preserves_tail_gpr() {
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut isel =
            X86InstructionSelector::with_abi("caller".to_string(), sig, X86CallAbi::SystemV);
        let entry = Block(0);
        isel.func.ensure_block(entry);

        for i in 0..5u32 {
            define_vreg(&mut isel, Value(i), Type::I64);
        }
        let i128_lo = isel.new_vreg(RegClass::Gpr64);
        let i128_hi = isel.new_vreg(RegClass::Gpr64);
        isel.define_i128_value(Value(5), i128_lo, i128_hi);
        define_vreg(&mut isel, Value(6), Type::I64);

        isel.lower_call(
            "callee",
            &Instruction {
                opcode: Opcode::Call {
                    name: "callee".to_string(),
                },
                args: (0..=6).map(Value).collect(),
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        assert_eq!(insts.len(), 11);
        assert_eq!(insts[0].opcode, X86Opcode::SubRI);
        assert_eq!(insts[0].operands[1], X86ISelOperand::Imm(16));
        for (idx, (disp, limb)) in [(0, i128_lo), (8, i128_hi)].into_iter().enumerate() {
            let store = &insts[1 + idx];
            assert_eq!(store.opcode, X86Opcode::MovMR);
            assert_eq!(
                store.operands[0],
                X86ISelOperand::MemAddr {
                    base: Box::new(X86ISelOperand::PReg(RSP)),
                    disp,
                }
            );
            assert_eq!(store.operands[1], X86ISelOperand::VReg(limb));
        }
        for (idx, reg) in [RDI, RSI, RDX, RCX, R8].into_iter().enumerate() {
            assert_eq!(insts[3 + idx].opcode, X86Opcode::MovRR);
            assert_eq!(insts[3 + idx].operands[0], X86ISelOperand::PReg(reg));
        }
        assert_eq!(insts[8].opcode, X86Opcode::MovRR);
        assert_eq!(insts[8].operands[0], X86ISelOperand::PReg(R9));
        assert_eq!(insts[9].opcode, X86Opcode::Call);
        assert_eq!(insts[10].opcode, X86Opcode::AddRI);
        assert_eq!(insts[10].operands[1], X86ISelOperand::Imm(16));
    }

