    #[test]
    fn test_lower_call_sysv_two_i64_aggregate_arg_stack_rollback_preserves_tail_gpr() {
        let aggregate_ty = Type::Struct(vec![Type::I64, Type::I64]);
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut isel =
            X86InstructionSelector::with_abi("caller".to_string(), sig, X86CallAbi::SystemV);
        let entry = Block(0);
        let aggregate_value = Value(5);
        isel.func.ensure_block(entry);
        isel.set_stack_slots(vec![StackSlotInfo::new(16, 8)]);
        isel.seed_value_types(&HashMap::from([(aggregate_value, aggregate_ty)]));
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::StackAddr { slot: 0 },
                args: vec![],
                results: vec![aggregate_value],
            },
            entry,
        )
        .unwrap();
        for i in 0..5u32 {
            define_vreg(&mut isel, Value(i), Type::I64);
        }
        define_vreg(&mut isel, Value(6), Type::I64);
        let mut args: Vec<Value> = (0..5u32).map(Value).collect();
        args.push(aggregate_value);
        args.push(Value(6));

        isel.lower_call(
            "callee",
            &Instruction {
                opcode: Opcode::Call {
                    name: "callee".to_string(),
                },
                args,
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        let aggregate_addr = insts[0].operands[0].clone();

        assert_eq!(insts.len(), 14);
        assert_eq!(insts[1].opcode, X86Opcode::SubRI);
        assert_eq!(insts[1].operands[1], X86ISelOperand::Imm(16));
        for (idx, disp) in [0, 8].into_iter().enumerate() {
            let load = &insts[2 + idx * 2];
            let store = &insts[3 + idx * 2];
            assert_eq!(load.opcode, X86Opcode::MovRM);
            assert_eq!(
                load.operands[1],
                X86ISelOperand::MemAddr {
                    base: Box::new(aggregate_addr.clone()),
                    disp,
                }
            );
            assert_eq!(store.opcode, X86Opcode::MovMR);
            assert_eq!(
                store.operands[0],
                X86ISelOperand::MemAddr {
                    base: Box::new(X86ISelOperand::PReg(RSP)),
                    disp,
                }
            );
            assert_eq!(store.operands[1], load.operands[0]);
        }
        for (idx, reg) in [RDI, RSI, RDX, RCX, R8].into_iter().enumerate() {
            assert_eq!(insts[6 + idx].opcode, X86Opcode::MovRR);
            assert_eq!(insts[6 + idx].operands[0], X86ISelOperand::PReg(reg));
        }
        assert_eq!(insts[11].opcode, X86Opcode::MovRR);
        assert_eq!(insts[11].operands[0], X86ISelOperand::PReg(R9));
        assert_eq!(insts[12].opcode, X86Opcode::Call);
        assert_eq!(insts[13].opcode, X86Opcode::AddRI);
        assert_eq!(insts[13].operands[1], X86ISelOperand::Imm(16));
    }

