    #[test]
    fn test_lower_call_windows_two_i64_aggregate_arg_passes_byref_temp_stack_slot() {
        let aggregate_ty = Type::Struct(vec![Type::I64, Type::I64]);
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut isel =
            X86InstructionSelector::with_abi("caller".to_string(), sig, X86CallAbi::WindowsX64);
        let entry = Block(0);
        let aggregate_value = Value(4);
        isel.func.ensure_block(entry);
        isel.set_stack_slots(vec![StackSlotInfo::new(16, 8)]);
        isel.seed_value_types(&HashMap::from([(aggregate_value, aggregate_ty)]));
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::StackAddr { slot: 0 },
                args: vec![],
                results: vec![aggregate_value],
            },
            entry,
        )
        .unwrap();
        for i in 0..4u32 {
            define_vreg(&mut isel, Value(i), Type::I64);
        }

        isel.lower_call(
            "callee",
            &Instruction {
                opcode: Opcode::Call {
                    name: "callee".to_string(),
                },
                args: vec![Value(0), Value(1), Value(2), Value(3), aggregate_value],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        let src_addr = insts[0].operands[0].clone();
        let temp_addr = insts[1].operands[0].clone();

        assert_no_rsp_adjusts(insts);
        assert_eq!(
            mfunc.stack_slots,
            vec![StackSlotInfo::new(16, 8), StackSlotInfo::new(16, 16)]
        );
        assert_eq!(mfunc.max_outgoing_call_bytes, 48);
        assert_eq!(insts.len(), 12);
        assert_eq!(insts[1].opcode, X86Opcode::Lea);
        for (idx, disp) in [0, 8].into_iter().enumerate() {
            let load = &insts[2 + idx * 2];
            let store = &insts[3 + idx * 2];
            assert_eq!(load.opcode, X86Opcode::MovRM);
            assert_eq!(
                load.operands[1],
                X86ISelOperand::MemAddr {
                    base: Box::new(src_addr.clone()),
                    disp,
                }
            );
            assert_eq!(store.opcode, X86Opcode::MovMR);
            assert_eq!(
                store.operands[0],
                X86ISelOperand::MemAddr {
                    base: Box::new(temp_addr.clone()),
                    disp,
                }
            );
            assert_eq!(store.operands[1], load.operands[0]);
        }
        assert_eq!(insts[6].opcode, X86Opcode::MovMR);
        assert_eq!(
            insts[6].operands[0],
            X86ISelOperand::MemAddr {
                base: Box::new(X86ISelOperand::PReg(RSP)),
                disp: 32,
            }
        );
        assert_eq!(insts[6].operands[1], temp_addr);
        assert_eq!(insts[7].operands[0], X86ISelOperand::PReg(RCX));
        assert_eq!(insts[8].operands[0], X86ISelOperand::PReg(RDX));
        assert_eq!(insts[9].operands[0], X86ISelOperand::PReg(R8));
        assert_eq!(insts[10].operands[0], X86ISelOperand::PReg(R9));
        assert_eq!(insts[11].opcode, X86Opcode::Call);
    }

