    #[test]
    fn test_lower_call_windows_sret_result_shifts_byref_aggregate_arg_to_rdx() {
        let result_ty = Type::Struct(vec![Type::I64, Type::I64]);
        let arg_ty = Type::Struct(vec![Type::I64, Type::I64]);
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut isel =
            X86InstructionSelector::with_abi("caller".to_string(), sig, X86CallAbi::WindowsX64);
        let entry = Block(0);
        isel.func.ensure_block(entry);
        isel.set_stack_slots(vec![StackSlotInfo::new(16, 8)]);
        isel.seed_value_types(&HashMap::from([(Value(0), arg_ty), (Value(1), result_ty)]));
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::StackAddr { slot: 0 },
                args: vec![],
                results: vec![Value(0)],
            },
            entry,
        )
        .unwrap();

        isel.lower_call(
            "callee",
            &Instruction {
                opcode: Opcode::Call {
                    name: "callee".to_string(),
                },
                args: vec![Value(0)],
                results: vec![Value(1)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        let src_addr = insts[0].operands[0].clone();
        let sret_addr = insts[1].operands[0].clone();
        let temp_addr = insts[2].operands[0].clone();

        assert_no_rsp_adjusts(insts);
        assert_eq!(
            mfunc.stack_slots,
            vec![
                StackSlotInfo::new(16, 8),
                StackSlotInfo::new(16, 8),
                StackSlotInfo::new(16, 16),
            ]
        );
        assert_eq!(mfunc.max_outgoing_call_bytes, 32);
        assert_eq!(insts.len(), 10);
        assert_eq!(insts[1].opcode, X86Opcode::Lea);
        assert_eq!(
            insts[1].operands[1],
            X86ISelOperand::MemAddr {
                base: Box::new(X86ISelOperand::StackSlot(1)),
                disp: 0,
            }
        );
        assert_eq!(insts[2].opcode, X86Opcode::Lea);
        assert_eq!(
            insts[2].operands[1],
            X86ISelOperand::MemAddr {
                base: Box::new(X86ISelOperand::StackSlot(2)),
                disp: 0,
            }
        );
        for (idx, disp) in [0, 8].into_iter().enumerate() {
            let load = &insts[3 + idx * 2];
            let store = &insts[4 + idx * 2];
            assert_eq!(load.opcode, X86Opcode::MovRM);
            assert_eq!(
                load.operands[1],
                X86ISelOperand::MemAddr {
                    base: Box::new(src_addr.clone()),
                    disp,
                }
            );
            assert_eq!(store.opcode, X86Opcode::MovMR);
            assert_eq!(
                store.operands[0],
                X86ISelOperand::MemAddr {
                    base: Box::new(temp_addr.clone()),
                    disp,
                }
            );
            assert_eq!(store.operands[1], load.operands[0]);
        }
        assert_eq!(insts[7].opcode, X86Opcode::MovRR);
        assert_eq!(insts[7].operands[0], X86ISelOperand::PReg(RCX));
        assert_eq!(insts[7].operands[1], sret_addr);
        assert_eq!(insts[8].opcode, X86Opcode::MovRR);
        assert_eq!(insts[8].operands[0], X86ISelOperand::PReg(RDX));
        assert_eq!(insts[8].operands[1], temp_addr);
        assert_eq!(insts[9].opcode, X86Opcode::Call);
    }

