    #[test]
    fn test_lower_call_sysv_mixed_and_sse_aggregate_results_materialize_abi_lanes() {
        for (aggregate_ty, expected_slot, expected_lanes) in [
            (
                Type::Struct(vec![Type::I64, Type::F64]),
                StackSlotInfo::new(16, 8),
                vec![(X86Opcode::MovMR, RAX, 0), (X86Opcode::MovsdMR, XMM0, 8)],
            ),
            (
                Type::Struct(vec![Type::F64, Type::I64]),
                StackSlotInfo::new(16, 8),
                vec![(X86Opcode::MovsdMR, XMM0, 0), (X86Opcode::MovMR, RAX, 8)],
            ),
            (
                Type::Struct(vec![Type::F64, Type::F64]),
                StackSlotInfo::new(16, 8),
                vec![(X86Opcode::MovsdMR, XMM0, 0), (X86Opcode::MovsdMR, XMM1, 8)],
            ),
            (
                Type::Array(Box::new(Type::F64), 2),
                StackSlotInfo::new(16, 8),
                vec![(X86Opcode::MovsdMR, XMM0, 0), (X86Opcode::MovsdMR, XMM1, 8)],
            ),
            (
                Type::Struct(vec![Type::V128]),
                StackSlotInfo::new(16, 16),
                vec![(X86Opcode::MovdquMR, XMM0, 0)],
            ),
            (
                Type::Array(Box::new(Type::V128), 1),
                StackSlotInfo::new(16, 16),
                vec![(X86Opcode::MovdquMR, XMM0, 0)],
            ),
        ] {
            let sig = Signature {
                params: vec![],
                returns: vec![],
            };
            let mut isel =
                X86InstructionSelector::with_abi("caller".to_string(), sig, X86CallAbi::SystemV);
            let entry = Block(0);
            isel.func.ensure_block(entry);
            isel.seed_value_types(&HashMap::from([(Value(0), aggregate_ty)]));

            isel.lower_call(
                "callee",
                &Instruction {
                    opcode: Opcode::Call {
                        name: "callee".to_string(),
                    },
                    args: vec![],
                    results: vec![Value(0)],
                },
                entry,
            )
            .unwrap();

            let mfunc = isel.finalize();
            let insts = &mfunc.blocks[&entry].insts;
            let aggregate_addr = insts[0].operands[0].clone();
            assert_eq!(mfunc.stack_slots, vec![expected_slot]);
            assert_eq!(insts[0].opcode, X86Opcode::Lea);
            assert_eq!(insts[1].opcode, X86Opcode::Call);
            for (idx, (opcode, reg, disp)) in expected_lanes.iter().enumerate() {
                let store = &insts[2 + idx];
                assert_eq!(store.opcode, *opcode);
                assert_eq!(
                    store.operands[0],
                    X86ISelOperand::MemAddr {
                        base: Box::new(aggregate_addr.clone()),
                        disp: *disp,
                    }
                );
                assert_eq!(store.operands[1], X86ISelOperand::PReg(*reg));
            }
            assert_eq!(insts.len(), 2 + expected_lanes.len());
        }
    }

