    #[test]
    fn test_lower_call_sysv_sret_result_shifts_integer_args() {
        let large_ty = Type::Struct(vec![Type::I64, Type::I64, Type::I64]);
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut isel = X86InstructionSelector::new("caller".to_string(), sig);
        let entry = Block(0);
        isel.func.ensure_block(entry);
        isel.seed_value_types(&HashMap::from([(Value(6), large_ty)]));
        for i in 0..6u32 {
            define_vreg(&mut isel, Value(i), Type::I64);
        }

        isel.lower_call(
            "callee",
            &Instruction {
                opcode: Opcode::Call {
                    name: "callee".to_string(),
                },
                args: (0..6).map(Value).collect(),
                results: vec![Value(6)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        assert_eq!(insts[0].opcode, X86Opcode::Lea);
        assert_eq!(insts[1].opcode, X86Opcode::SubRI);
        assert_eq!(insts[1].operands[1], X86ISelOperand::Imm(16));
        assert_eq!(insts[2].opcode, X86Opcode::MovMR);
        assert_eq!(
            insts[2].operands[0],
            X86ISelOperand::MemAddr {
                base: Box::new(X86ISelOperand::PReg(RSP)),
                disp: 0,
            }
        );
        assert_eq!(insts[3].opcode, X86Opcode::MovRR);
        assert_eq!(insts[3].operands[0], X86ISelOperand::PReg(RDI));
        for (idx, expected) in [RSI, RDX, RCX, R8, R9].into_iter().enumerate() {
            assert_eq!(insts[4 + idx].opcode, X86Opcode::MovRR);
            assert_eq!(insts[4 + idx].operands[0], X86ISelOperand::PReg(expected));
        }
    }

