    #[test]
    fn test_lower_return_mixed_scalars_use_independent_return_sequences() {
        let return_types = vec![Type::I64, Type::F64, Type::I32, Type::F32];
        for abi in [X86CallAbi::SystemV, X86CallAbi::WindowsX64] {
            let sig = Signature {
                params: vec![],
                returns: return_types.clone(),
            };
            let mut isel = X86InstructionSelector::with_abi("mixed_returns".to_string(), sig, abi);
            let entry = Block(0);
            isel.func.ensure_block(entry);
            for (index, ty) in return_types.iter().cloned().enumerate() {
                define_vreg(&mut isel, Value(index as u32), ty);
            }

            isel.lower_return(
                &Instruction {
                    opcode: Opcode::Return,
                    args: vec![Value(0), Value(1), Value(2), Value(3)],
                    results: vec![],
                },
                entry,
            )
            .unwrap();

            let mfunc = isel.finalize();
            let insts = &mfunc.blocks[&entry].insts;
            assert_eq!(insts.len(), 5, "{abi:?}: {insts:?}");
            assert_eq!(insts[0].operands[0], X86ISelOperand::PReg(RAX));
            assert_eq!(insts[1].operands[0], X86ISelOperand::PReg(XMM0));
            assert_eq!(insts[2].operands[0], X86ISelOperand::PReg(EDX));
            assert_eq!(insts[3].operands[0], X86ISelOperand::PReg(XMM1));
            assert_eq!(insts[4].opcode, X86Opcode::Ret);
        }
    }

