    #[test]
    fn test_lower_return_large_aggregate_copies_to_sret_pointer() {
        let large_ty = Type::Struct(vec![Type::I64, Type::I64, Type::I64]);
        let sig = Signature {
            params: vec![],
            returns: vec![large_ty.clone()],
        };
        let mut isel = X86InstructionSelector::new("test_fn".to_string(), sig);
        let entry = Block(0);
        isel.func.ensure_block(entry);
        let src = X86ISelOperand::VReg(define_vreg(&mut isel, Value(0), large_ty));

        isel.lower_return(
            &Instruction {
                opcode: Opcode::Return,
                args: vec![Value(0)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;

        assert_eq!(insts.len(), 8);
        for (idx, disp) in [0, 8, 16].into_iter().enumerate() {
            let load = &insts[idx * 2];
            let store = &insts[idx * 2 + 1];
            assert_eq!(load.opcode, X86Opcode::MovRM);
            assert_eq!(
                load.operands[1],
                X86ISelOperand::MemAddr {
                    base: Box::new(src.clone()),
                    disp,
                }
            );
            assert_eq!(store.opcode, X86Opcode::MovMR);
            assert_eq!(
                store.operands[0],
                X86ISelOperand::MemAddr {
                    base: Box::new(X86ISelOperand::PReg(RDI)),
                    disp,
                }
            );
            assert_eq!(store.operands[1], load.operands[0]);
        }
        assert_eq!(insts[6].opcode, X86Opcode::MovRR);
        assert_eq!(
            insts[6].operands,
            vec![X86ISelOperand::PReg(RAX), X86ISelOperand::PReg(RDI)]
        );
        assert_eq!(insts[7].opcode, X86Opcode::Ret);
    }

