    #[test]
    fn test_lower_return_windows_two_i64_aggregate_copies_to_saved_sret_pointer() {
        let aggregate_ty = Type::Struct(vec![Type::I64, Type::I64]);
        let sig = Signature {
            params: vec![],
            returns: vec![aggregate_ty.clone()],
        };
        let mut isel = X86InstructionSelector::with_abi(
            "test_fn".to_string(),
            sig.clone(),
            X86CallAbi::WindowsX64,
        );
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();
        let saved_sret = isel.sret_return_ptr.clone().unwrap();
        let src = X86ISelOperand::VReg(define_vreg(&mut isel, Value(0), aggregate_ty));

        isel.lower_return(
            &Instruction {
                opcode: Opcode::Return,
                args: vec![Value(0)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;

        assert_eq!(insts.len(), 7);
        assert_eq!(insts[0].opcode, X86Opcode::MovRR);
        assert_eq!(insts[0].operands[1], X86ISelOperand::PReg(RCX));
        for (idx, disp) in [0, 8].into_iter().enumerate() {
            let load = &insts[1 + idx * 2];
            let store = &insts[2 + idx * 2];
            assert_eq!(load.opcode, X86Opcode::MovRM);
            assert_eq!(
                load.operands[1],
                X86ISelOperand::MemAddr {
                    base: Box::new(src.clone()),
                    disp,
                }
            );
            assert_eq!(store.opcode, X86Opcode::MovMR);
            assert_eq!(
                store.operands[0],
                X86ISelOperand::MemAddr {
                    base: Box::new(saved_sret.clone()),
                    disp,
                }
            );
            assert_eq!(store.operands[1], load.operands[0]);
        }
        assert_eq!(insts[5].opcode, X86Opcode::MovRR);
        assert_eq!(
            insts[5].operands,
            vec![X86ISelOperand::PReg(RAX), saved_sret]
        );
        assert_eq!(insts[6].opcode, X86Opcode::Ret);
    }

