    #[test]
    fn test_lower_return_sysv_mixed_and_sse_aggregate_returns_load_abi_lanes() {
        for (aggregate_ty, expected_lanes) in [
            (
                Type::Struct(vec![Type::I64, Type::F64]),
                vec![(X86Opcode::MovRM, RAX, 0), (X86Opcode::MovsdRM, XMM0, 8)],
            ),
            (
                Type::Struct(vec![Type::F64, Type::I64]),
                vec![(X86Opcode::MovsdRM, XMM0, 0), (X86Opcode::MovRM, RAX, 8)],
            ),
            (
                Type::Struct(vec![Type::F64, Type::F64]),
                vec![(X86Opcode::MovsdRM, XMM0, 0), (X86Opcode::MovsdRM, XMM1, 8)],
            ),
            (
                Type::Array(Box::new(Type::F64), 2),
                vec![(X86Opcode::MovsdRM, XMM0, 0), (X86Opcode::MovsdRM, XMM1, 8)],
            ),
            (
                Type::Struct(vec![Type::V128]),
                vec![(X86Opcode::MovdquRM, XMM0, 0)],
            ),
            (
                Type::Array(Box::new(Type::V128), 1),
                vec![(X86Opcode::MovdquRM, XMM0, 0)],
            ),
        ] {
            let sig = Signature {
                params: vec![],
                returns: vec![aggregate_ty],
            };
            let mut isel =
                X86InstructionSelector::with_abi("test_fn".to_string(), sig, X86CallAbi::SystemV);
            let entry = Block(0);
            isel.func.ensure_block(entry);
            isel.select_instruction(
                &Instruction {
                    opcode: Opcode::StackAddr { slot: 0 },
                    args: vec![],
                    results: vec![Value(0)],
                },
                entry,
            )
            .unwrap();

            isel.lower_return(
                &Instruction {
                    opcode: Opcode::Return,
                    args: vec![Value(0)],
                    results: vec![],
                },
                entry,
            )
            .unwrap();

            let mfunc = isel.finalize();
            let insts = &mfunc.blocks[&entry].insts;
            let aggregate_addr = insts[0].operands[0].clone();
            assert_eq!(insts[0].opcode, X86Opcode::Lea);
            for (idx, (opcode, reg, disp)) in expected_lanes.iter().enumerate() {
                let load = &insts[1 + idx];
                assert_eq!(load.opcode, *opcode);
                assert_eq!(load.operands[0], X86ISelOperand::PReg(*reg));
                assert_eq!(
                    load.operands[1],
                    X86ISelOperand::MemAddr {
                        base: Box::new(aggregate_addr.clone()),
                        disp: *disp,
                    }
                );
            }
            assert_eq!(insts[1 + expected_lanes.len()].opcode, X86Opcode::Ret);
            assert_eq!(insts.len(), 2 + expected_lanes.len());
        }
    }

    #[test]
    fn test_lower_return_rejects_non_exact_integer_aggregate_returns() {
        // Valid SysV register-aggregate returns (RAX:RDX). On Windows x64 the
        // <=8-byte ones are rejected (no eightbyte register-aggregate ABI),
        // while the >8-byte ones are returned via sret, so only the 8-byte
        // shapes are asserted to reject on Windows.
        for aggregate_ty in [
            Type::Struct(vec![Type::I32, Type::I32]),
            Type::Array(Box::new(Type::I32), 2),
            Type::Array(Box::new(Type::I8), 8),
            Type::Struct(vec![Type::I16, Type::I16, Type::I16, Type::I16]),
            Type::Struct(vec![Type::I64, Type::I32]),
            Type::Struct(vec![Type::I32, Type::I32, Type::I32]),
            Type::Array(Box::new(Type::I32), 3),
        ] {
            assert!(
                classify_sysv_register_aggregate(&aggregate_ty, X86CallAbi::SystemV).is_some(),
                "{aggregate_ty:?} should classify as a SysV register aggregate"
            );
            if aggregate_ty.bytes() <= 8 {
                assert_return_rejects_aggregate(aggregate_ty, X86CallAbi::WindowsX64);
            }
        }
    }

    #[test]
    fn test_lower_return_rejects_unsupported_single_lane_aggregate_returns() {
        // `{B1}` (1-byte) now LOWERS on SysV (a 1-byte INTEGER eightbyte returned
        // in AL — see test_sysv_subdword_returns_supported_args_fail_closed); it is
        // still rejected on Windows x64 (no eightbyte register-aggregate ABI).
        // Single-SSE aggregates classify on SysV but are rejected on Windows x64.
        for aggregate_ty in [
            Type::Struct(vec![Type::B1]),
            Type::Array(Box::new(Type::B1), 1),
        ] {
            assert_return_rejects_aggregate(aggregate_ty, X86CallAbi::WindowsX64);
        }
        for aggregate_ty in [
            Type::Struct(vec![Type::F32]),
            Type::Array(Box::new(Type::F32), 1),
            Type::Struct(vec![Type::F64]),
            Type::Array(Box::new(Type::F64), 1),
        ] {
            assert_return_rejects_aggregate(aggregate_ty, X86CallAbi::WindowsX64);
        }
    }

