    #[test]
    fn test_lower_formal_arguments_sysv_mixed_and_sse_materializes_abi_lanes() {
        for (aggregate_ty, expected_lanes, expected_next_gpr) in [
            (
                Type::Struct(vec![Type::I64, Type::F64]),
                vec![
                    (X86Opcode::MovRR, RDI, X86Opcode::MovMR, 0),
                    (X86Opcode::MovsdRR, XMM0, X86Opcode::MovsdMR, 8),
                ],
                RSI,
            ),
            (
                Type::Struct(vec![Type::F64, Type::I64]),
                vec![
                    (X86Opcode::MovsdRR, XMM0, X86Opcode::MovsdMR, 0),
                    (X86Opcode::MovRR, RDI, X86Opcode::MovMR, 8),
                ],
                RSI,
            ),
            (
                Type::Struct(vec![Type::F64, Type::F64]),
                vec![
                    (X86Opcode::MovsdRR, XMM0, X86Opcode::MovsdMR, 0),
                    (X86Opcode::MovsdRR, XMM1, X86Opcode::MovsdMR, 8),
                ],
                RDI,
            ),
            (
                Type::Array(Box::new(Type::F64), 2),
                vec![
                    (X86Opcode::MovsdRR, XMM0, X86Opcode::MovsdMR, 0),
                    (X86Opcode::MovsdRR, XMM1, X86Opcode::MovsdMR, 8),
                ],
                RDI,
            ),
        ] {
            let sig = Signature {
                params: vec![aggregate_ty, Type::I64],
                returns: vec![],
            };
            let mut isel = X86InstructionSelector::with_abi(
                "sysv_mixed_sse_formal".to_string(),
                sig.clone(),
                X86CallAbi::SystemV,
            );
            let entry = Block(0);

            isel.lower_formal_arguments(&sig, entry).unwrap();

            let mfunc = isel.finalize();
            let insts = &mfunc.blocks[&entry].insts;
            assert_eq!(mfunc.stack_slots, vec![StackSlotInfo::new(16, 8)]);
            let mut lane_sources = Vec::new();
            for (idx, (copy_opcode, reg, _, _)) in expected_lanes.iter().enumerate() {
                let copy = &insts[idx];
                assert_eq!(copy.opcode, *copy_opcode);
                assert_eq!(copy.operands[1], X86ISelOperand::PReg(*reg));
                lane_sources.push(copy.operands[0].clone());
            }
            let next = &insts[expected_lanes.len()];
            assert_eq!(next.opcode, X86Opcode::MovRR);
            assert_eq!(next.operands[1], X86ISelOperand::PReg(expected_next_gpr));

            let aggregate_index = expected_lanes.len() + 1;
            let aggregate_addr = insts[aggregate_index].operands[0].clone();
            assert_eq!(insts[aggregate_index].opcode, X86Opcode::Lea);
            for (idx, (_, _, store_opcode, disp)) in expected_lanes.iter().enumerate() {
                let store = &insts[aggregate_index + 1 + idx];
                assert_eq!(store.opcode, *store_opcode);
                assert_eq!(
                    store.operands[0],
                    X86ISelOperand::MemAddr {
                        base: Box::new(aggregate_addr.clone()),
                        disp: *disp,
                    }
                );
                assert_eq!(store.operands[1], lane_sources[idx]);
            }
            assert_eq!(insts.len(), expected_lanes.len() * 2 + 2);
        }
    }

