    #[test]
    fn test_lower_formal_arguments_sysv_mixed_aggregate_stack_fallback_preserves_tail_xmm() {
        let aggregate_ty = Type::Struct(vec![Type::I64, Type::F64]);
        let mut params = vec![Type::I64; 6];
        params.push(aggregate_ty);
        params.push(Type::F64);
        let sig = Signature {
            params,
            returns: vec![],
        };
        let mut isel = X86InstructionSelector::with_abi(
            "sysv_mixed_formal_stack".to_string(),
            sig.clone(),
            X86CallAbi::SystemV,
        );
        let entry = Block(0);

        isel.lower_formal_arguments(&sig, entry).unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        let aggregate_addr = insts[7].operands[0].clone();

        assert_eq!(mfunc.stack_slots, vec![StackSlotInfo::new(16, 8)]);
        assert_eq!(insts.len(), 12);
        for (idx, reg) in [RDI, RSI, RDX, RCX, R8, R9].into_iter().enumerate() {
            assert_eq!(insts[idx].opcode, X86Opcode::MovRR);
            assert_eq!(insts[idx].operands[1], X86ISelOperand::PReg(reg));
        }
        assert_eq!(insts[6].opcode, X86Opcode::MovsdRR);
        assert_eq!(insts[6].operands[1], X86ISelOperand::PReg(XMM0));
        assert_eq!(insts[7].opcode, X86Opcode::Lea);
        for (idx, (load_opcode, store_opcode, disp)) in [
            (X86Opcode::MovRM, X86Opcode::MovMR, 0),
            (X86Opcode::MovsdRM, X86Opcode::MovsdMR, 8),
        ]
        .into_iter()
        .enumerate()
        {
            let load = &insts[8 + idx * 2];
            let store = &insts[9 + idx * 2];
            assert_eq!(load.opcode, load_opcode);
            assert_eq!(
                load.operands[1],
                X86ISelOperand::MemAddr {
                    base: Box::new(X86ISelOperand::PReg(RBP)),
                    disp: 16 + disp,
                }
            );
            assert_eq!(store.opcode, store_opcode);
            assert_eq!(
                store.operands[0],
                X86ISelOperand::MemAddr {
                    base: Box::new(aggregate_addr.clone()),
                    disp,
                }
            );
            assert_eq!(store.operands[1], load.operands[0]);
        }
    }

