    #[test]
    fn test_lower_formal_arguments_sysv_v128_carrier_stack_fallback_aligns_slot() {
        let aggregate_ty = Type::Struct(vec![Type::V128]);
        let mut params = vec![Type::F64; 8];
        params.extend(std::iter::repeat_n(Type::I64, 7));
        params.push(aggregate_ty);
        let sig = Signature {
            params,
            returns: vec![],
        };
        let mut isel = X86InstructionSelector::with_abi(
            "sysv_v128_carrier_formal_stack".to_string(),
            sig.clone(),
            X86CallAbi::SystemV,
        );
        let entry = Block(0);

        isel.lower_formal_arguments(&sig, entry).unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        assert_eq!(mfunc.stack_slots, vec![StackSlotInfo::new(16, 16)]);
        assert!(
            insts.iter().any(|inst| {
                inst.opcode == X86Opcode::MovRM
                    && inst.operands[1]
                        == X86ISelOperand::MemAddr {
                            base: Box::new(X86ISelOperand::PReg(RBP)),
                            disp: 16,
                        }
            }),
            "the scalar stack arg before the carrier should remain at [rbp+16]: {insts:?}"
        );
        assert!(
            insts.iter().any(|inst| {
                inst.opcode == X86Opcode::MovdqaRM
                    && inst.operands[1]
                        == X86ISelOperand::MemAddr {
                            base: Box::new(X86ISelOperand::PReg(RBP)),
                            disp: 32,
                        }
            }),
            "the V128 carrier must start at the next 16-byte-aligned stack slot: {insts:?}"
        );
        assert!(
            insts.iter().all(|inst| {
                inst.operands.get(1)
                    != Some(&X86ISelOperand::MemAddr {
                        base: Box::new(X86ISelOperand::PReg(RBP)),
                        disp: 24,
                    })
            }),
            "the padding eightbyte before the V128 carrier must not be read: {insts:?}"
        );
    }

