    #[test]
    fn test_lower_formal_arguments_windows_two_i64_aggregate_byref_register_pointer() {
        let aggregate_ty = Type::Struct(vec![Type::I64, Type::I64]);
        let sig = Signature {
            params: vec![aggregate_ty, Type::I64],
            returns: vec![],
        };
        let mut isel = X86InstructionSelector::with_abi(
            "windows_byref_formal".to_string(),
            sig.clone(),
            X86CallAbi::WindowsX64,
        );
        let entry = Block(0);

        isel.lower_formal_arguments(&sig, entry).unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        let incoming_addr = insts[0].operands[0].clone();
        let aggregate_addr = insts[2].operands[0].clone();

        assert_eq!(mfunc.stack_slots, vec![StackSlotInfo::new(16, 16)]);
        assert_eq!(insts.len(), 7);
        assert_eq!(insts[0].opcode, X86Opcode::MovRR);
        assert_eq!(insts[0].operands[1], X86ISelOperand::PReg(RCX));
        assert_eq!(insts[1].opcode, X86Opcode::MovRR);
        assert_eq!(insts[1].operands[1], X86ISelOperand::PReg(RDX));
        assert_eq!(insts[2].opcode, X86Opcode::Lea);
        for (idx, disp) in [0, 8].into_iter().enumerate() {
            let load = &insts[3 + idx * 2];
            let store = &insts[4 + idx * 2];
            assert_eq!(load.opcode, X86Opcode::MovRM);
            assert_eq!(
                load.operands[1],
                X86ISelOperand::MemAddr {
                    base: Box::new(incoming_addr.clone()),
                    disp,
                }
            );
            assert_eq!(store.opcode, X86Opcode::MovMR);
            assert_eq!(
                store.operands[0],
                X86ISelOperand::MemAddr {
                    base: Box::new(aggregate_addr.clone()),
                    disp,
                }
            );
            assert_eq!(store.operands[1], load.operands[0]);
        }
    }

    #[test]
    fn test_lower_formal_arguments_windows_two_i64_aggregate_byref_stack_pointer() {
        let aggregate_ty = Type::Struct(vec![Type::I64, Type::I64]);
        let mut params = vec![Type::I64; 4];
        params.push(aggregate_ty);
        let sig = Signature {
            params,
            returns: vec![],
        };
        let mut isel = X86InstructionSelector::with_abi(
            "windows_byref_formal_stack".to_string(),
            sig.clone(),
            X86CallAbi::WindowsX64,
        );
        let entry = Block(0);

        isel.lower_formal_arguments(&sig, entry).unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        let pointer_tmp = insts[4].operands[0].clone();
        let aggregate_addr = insts[5].operands[0].clone();

        assert_eq!(mfunc.stack_slots, vec![StackSlotInfo::new(16, 16)]);
        assert_eq!(insts.len(), 10);
        assert_eq!(insts[0].operands[1], X86ISelOperand::PReg(RCX));
        assert_eq!(insts[1].operands[1], X86ISelOperand::PReg(RDX));
        assert_eq!(insts[2].operands[1], X86ISelOperand::PReg(R8));
        assert_eq!(insts[3].operands[1], X86ISelOperand::PReg(R9));
        assert_eq!(insts[4].opcode, X86Opcode::MovRM);
        assert_eq!(
            insts[4].operands[1],
            X86ISelOperand::MemAddr {
                base: Box::new(X86ISelOperand::PReg(RBP)),
                disp: 48,
            }
        );
        assert_eq!(insts[5].opcode, X86Opcode::Lea);
        for (idx, disp) in [0, 8].into_iter().enumerate() {
            let load = &insts[6 + idx * 2];
            let store = &insts[7 + idx * 2];
            assert_eq!(load.opcode, X86Opcode::MovRM);
            assert_eq!(
                load.operands[1],
                X86ISelOperand::MemAddr {
                    base: Box::new(pointer_tmp.clone()),
                    disp,
                }
            );
            assert_eq!(store.opcode, X86Opcode::MovMR);
            assert_eq!(
                store.operands[0],
                X86ISelOperand::MemAddr {
                    base: Box::new(aggregate_addr.clone()),
                    disp,
                }
            );
            assert_eq!(store.operands[1], load.operands[0]);
        }
    }

