    // -----------------------------------------------------------------------
    // Division
    // -----------------------------------------------------------------------

    #[test]
    fn test_select_sdiv() {
        let (mut isel, entry) = make_empty_isel();
        define_vreg(&mut isel, Value(0), Type::I64);
        define_vreg(&mut isel, Value(1), Type::I64);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Sdiv,
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        // Signed div lowers to: [INT_MIN/-1 overflow guard: MOV one,1 ;
        // MOV safe_rhs,rhs ; CMP rhs,-1 ; CMOVE safe_rhs,one] ; MOV RAX, lhs ;
        // CQO ; IDIV safe_rhs ; MOV dst, RAX ; [SDiv -1 patch: NEG -lhs ;
        // CMP rhs,-1 ; CMOVE dst,-lhs]. The guard makes the divisor never -1
        // so IDIV cannot raise #DE on INT_MIN/-1, and the patch overwrites the
        // bogus `lhs/1` quotient with `-lhs` (wraps INT_MIN), matching the
        // interpreter's wrapping_div. The dividend is moved into RAX only after
        // the guard so the accumulator's live range stays tight (RAX is not held
        // live across the guard's scratch MOV/CMOVs).
        assert_eq!(insts.len(), 11);
        // Overflow guard: materialize 1, copy rhs, CMP rhs,-1, CMOVE.
        assert_eq!(insts[0].opcode, X86Opcode::MovRI);
        assert_eq!(insts[0].operands[1], X86ISelOperand::Imm(1));
        assert_eq!(insts[1].opcode, X86Opcode::MovRR); // safe_rhs := rhs
        assert_eq!(insts[2].opcode, X86Opcode::CmpRI);
        assert_eq!(insts[2].operands[1], X86ISelOperand::Imm(-1));
        assert_eq!(insts[3].opcode, X86Opcode::Cmovcc);
        assert_eq!(
            insts[3].operands[2],
            X86ISelOperand::CondCode(X86CondCode::E)
        );
        assert_eq!(insts[4].opcode, X86Opcode::MovRR); // MOV RAX, lhs
        assert_eq!(insts[4].operands[0], X86ISelOperand::PReg(RAX));
        assert_eq!(insts[5].opcode, X86Opcode::Cqo);
        assert_eq!(insts[6].opcode, X86Opcode::Idiv); // IDIV safe_rhs (never -1)
        // IDIV divides by the guarded divisor, not the raw rhs.
        assert_eq!(insts[6].operands[0], insts[3].operands[0]);
        assert_eq!(insts[7].opcode, X86Opcode::MovRR); // MOV dst, RAX
        assert_eq!(insts[7].operands[1], X86ISelOperand::PReg(RAX));
        // SDiv overflow patch: NEG -lhs ; CMP rhs,-1 ; CMOVE dst, -lhs.
        assert_eq!(insts[8].opcode, X86Opcode::Neg);
        assert_eq!(insts[9].opcode, X86Opcode::CmpRI);
        assert_eq!(insts[9].operands[1], X86ISelOperand::Imm(-1));
        assert_eq!(insts[10].opcode, X86Opcode::Cmovcc);
        assert_eq!(insts[10].operands[0], insts[7].operands[0]); // patches dst
        assert_eq!(
            insts[10].operands[2],
            X86ISelOperand::CondCode(X86CondCode::E)
        );
    }

    #[test]
    fn test_select_udiv() {
        let (mut isel, entry) = make_empty_isel();
        define_vreg(&mut isel, Value(0), Type::I64);
        define_vreg(&mut isel, Value(1), Type::I64);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Udiv,
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        // MOV RAX, lhs + XOR RDX, RDX + DIV rhs + MOV dst, RAX
        assert_eq!(insts.len(), 4);
        assert_eq!(insts[0].opcode, X86Opcode::MovRR); // MOV RAX, lhs
        assert_eq!(insts[1].opcode, X86Opcode::XorRR); // XOR RDX, RDX
        assert_eq!(insts[2].opcode, X86Opcode::Div); // DIV rhs
        assert_eq!(insts[3].opcode, X86Opcode::MovRR); // MOV dst, RAX
        assert_eq!(insts[3].operands[1], X86ISelOperand::PReg(RAX));
    }

    #[test]
    fn test_select_i32_division_uses_32bit_implicit_regs() {
        let (mut isel, entry) = make_empty_isel();
        define_vreg(&mut isel, Value(0), Type::I32);
        define_vreg(&mut isel, Value(1), Type::I32);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Sdiv,
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        // i32 signed div uses the 32-bit accumulator (EAX/EDX), Cdq, and the
        // 32-bit CMOV/copy forms throughout, including the INT_MIN/-1 overflow
        // guard and the SDiv -1 patch. The dividend MOV into EAX comes after the
        // guard (insts[4]).
        assert_eq!(insts[0].opcode, X86Opcode::MovRI); // one := 1
        assert_eq!(insts[1].opcode, X86Opcode::MovRR32); // safe_rhs := rhs
        assert_eq!(insts[2].opcode, X86Opcode::CmpRI);
        assert_eq!(insts[2].operands[1], X86ISelOperand::Imm(-1));
        assert_eq!(insts[3].opcode, X86Opcode::Cmovcc32);
        assert_eq!(insts[4].opcode, X86Opcode::MovRR32); // MOV EAX, lhs
        assert_eq!(insts[4].operands[0], X86ISelOperand::PReg(EAX));
        assert_eq!(insts[5].opcode, X86Opcode::Cdq);
        assert_eq!(insts[6].opcode, X86Opcode::Idiv);
        assert_eq!(insts[7].opcode, X86Opcode::MovRR32);
        assert_eq!(insts[7].operands[1], X86ISelOperand::PReg(EAX));
        assert_eq!(insts[8].opcode, X86Opcode::Neg);
        assert_eq!(insts[9].opcode, X86Opcode::CmpRI);
        assert_eq!(insts[10].opcode, X86Opcode::Cmovcc32);
    }

