    #[test]
    fn test_select_fneg_f64() {
        let (mut isel, entry) = make_empty_isel();
        define_vreg(&mut isel, Value(0), Type::F64);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Fneg,
                args: vec![Value(0)],
                results: vec![Value(1)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        // MovsdRipRel (load the f64 sign mask) + Pxor (flip the sign bit). NOT
        // `0.0 - x`, which would give +0.0 for -(0.0).
        assert_eq!(insts.len(), 2);
        assert_eq!(insts[0].opcode, X86Opcode::MovsdRipRel);
        assert_eq!(insts[1].opcode, X86Opcode::Pxor);
        // Verify the sign-mask constant pool entry.
        assert_eq!(mfunc.const_pool_entries.len(), 1);
        assert_eq!(
            mfunc.const_pool_entries[0].data,
            0x8000_0000_0000_0000_u64.to_le_bytes().to_vec()
        );
        assert_eq!(mfunc.const_pool_entries[0].align, 8);
    }

