    #[test]
    fn test_select_fcvt_from_uint_small_widths_normalize_before_convert() {
        let cases = [
            (Type::I8, Type::F32, X86Opcode::Movzx, X86Opcode::Cvtsi2ss),
            (Type::I8, Type::F64, X86Opcode::Movzx, X86Opcode::Cvtsi2sd),
            (Type::I16, Type::F32, X86Opcode::MovzxW, X86Opcode::Cvtsi2ss),
            (Type::I16, Type::F64, X86Opcode::MovzxW, X86Opcode::Cvtsi2sd),
            (
                Type::I32,
                Type::F32,
                X86Opcode::MovRR32,
                X86Opcode::Cvtsi2ss,
            ),
            (
                Type::I32,
                Type::F64,
                X86Opcode::MovRR32,
                X86Opcode::Cvtsi2sd,
            ),
        ];

        for (src_ty, dst_ty, normalize, convert) in cases {
            let (mut isel, entry) = make_empty_isel();
            define_vreg(&mut isel, Value(0), src_ty.clone());
            isel.seed_value_types(&HashMap::from([(Value(1), dst_ty.clone())]));

            isel.select_instruction(
                &Instruction {
                    opcode: Opcode::FcvtFromUint {
                        src_ty: src_ty.clone(),
                    },
                    args: vec![Value(0)],
                    results: vec![Value(1)],
                },
                entry,
            )
            .unwrap();

            let mfunc = isel.finalize();
            let insts = &mfunc.blocks[&entry].insts;
            assert_eq!(insts[0].opcode, normalize, "{src_ty:?} -> {dst_ty:?}");
            assert_eq!(insts[1].opcode, convert, "{src_ty:?} -> {dst_ty:?}");
            assert_eq!(mfunc.blocks[&entry].insts.len(), 2);
        }
    }

