    #[test]
    fn test_select_fcvt_to_uint_small_widths_use_cvtt_and_narrow() {
        let cases = [
            (
                Type::F32,
                Type::I8,
                X86Opcode::Ucomiss,
                X86Opcode::MovssRipRel,
                X86Opcode::Cvttss2si,
                X86Opcode::Movzx,
            ),
            (
                Type::F64,
                Type::I8,
                X86Opcode::Ucomisd,
                X86Opcode::MovsdRipRel,
                X86Opcode::Cvttsd2si,
                X86Opcode::Movzx,
            ),
            (
                Type::F64,
                Type::I16,
                X86Opcode::Ucomisd,
                X86Opcode::MovsdRipRel,
                X86Opcode::Cvttsd2si,
                X86Opcode::MovzxW,
            ),
            (
                Type::F32,
                Type::I16,
                X86Opcode::Ucomiss,
                X86Opcode::MovssRipRel,
                X86Opcode::Cvttss2si,
                X86Opcode::MovzxW,
            ),
            (
                Type::F32,
                Type::I32,
                X86Opcode::Ucomiss,
                X86Opcode::MovssRipRel,
                X86Opcode::Cvttss2si,
                X86Opcode::MovRR32,
            ),
            (
                Type::F64,
                Type::I32,
                X86Opcode::Ucomisd,
                X86Opcode::MovsdRipRel,
                X86Opcode::Cvttsd2si,
                X86Opcode::MovRR32,
            ),
        ];

        for (src_ty, dst_ty, compare, _load_bound, convert, narrow) in cases {
            let (mut isel, entry) = make_empty_isel();
            define_vreg(&mut isel, Value(0), src_ty.clone());

            isel.select_instruction(
                &Instruction {
                    opcode: Opcode::FcvtToUint {
                        dst_ty: dst_ty.clone(),
                    },
                    args: vec![Value(0)],
                    results: vec![Value(1)],
                },
                entry,
            )
            .unwrap();

            let mfunc = isel.finalize();
            let insts = &mfunc.blocks[&entry].insts;
            let opcodes = insts.iter().map(|inst| inst.opcode).collect::<Vec<_>>();

            // Saturating lowering (MISCOMPILE #59): truncate, then clamp the
            // out-of-domain inputs with float-threshold compares + CMOV. There
            // are NO trap edges (`Jcc`/`Ud2`) — an out-of-range `as` cast is a
            // defined saturation, not a SIGILL.
            assert!(
                opcodes.contains(&convert),
                "{src_ty:?} -> {dst_ty:?} should truncate via {convert:?}"
            );
            assert!(
                opcodes.contains(&narrow),
                "{src_ty:?} -> {dst_ty:?} should narrow via {narrow:?}"
            );
            assert!(
                opcodes.contains(&compare),
                "{src_ty:?} -> {dst_ty:?} should compare via {compare:?}"
            );
            assert!(
                !opcodes.contains(&X86Opcode::Jcc) && !opcodes.contains(&X86Opcode::Ud2),
                "{src_ty:?} -> {dst_ty:?} saturating cast must not emit trap edges"
            );
            let cmov_conds: Vec<_> = insts
                .iter()
                .filter(|i| i.opcode == X86Opcode::Cmovcc)
                .map(|i| i.operands[2].clone())
                .collect();
            assert_eq!(
                cmov_conds,
                vec![
                    X86ISelOperand::CondCode(X86CondCode::B),  // x < 0   -> 0
                    X86ISelOperand::CondCode(X86CondCode::AE), // x >= 2^n -> MAX
                    X86ISelOperand::CondCode(X86CondCode::P),  // NaN     -> 0
                ],
                "{src_ty:?} -> {dst_ty:?} clamp cmov condition order"
            );
            // hi threshold (2^n) and 0.0 are the only const-pool floats.
            assert_eq!(mfunc.const_pool_entries.len(), 2);
        }
    }

    #[test]
    fn test_select_fcvt_to_uint_u64_uses_threshold_split() {
        for (src_ty, load_opcode, trunc_opcode, sub_opcode, compare_opcode) in [
            (
                Type::F32,
                X86Opcode::MovssRipRel,
                X86Opcode::Cvttss2si,
                X86Opcode::Subss,
                X86Opcode::Ucomiss,
            ),
            (
                Type::F64,
                X86Opcode::MovsdRipRel,
                X86Opcode::Cvttsd2si,
                X86Opcode::Subsd,
                X86Opcode::Ucomisd,
            ),
        ] {
            let (mut isel, entry) = make_empty_isel();
            define_vreg(&mut isel, Value(0), src_ty.clone());

            isel.select_instruction(
                &Instruction {
                    opcode: Opcode::FcvtToUint { dst_ty: Type::I64 },
                    args: vec![Value(0)],
                    results: vec![Value(1)],
                },
                entry,
            )
            .unwrap();

            let mfunc = isel.finalize();
            let insts = &mfunc.blocks[&entry].insts;
            let opcodes = insts.iter().map(|inst| inst.opcode).collect::<Vec<_>>();

            // Saturating u64 lowering (MISCOMPILE #59): the bias-split
            // (trunc(x) for the low half, trunc(x - 2^63) | 2^63 for the high
            // half) selected by CMOV, then saturation clamps (x<=0/NaN -> 0,
            // x >= 2^64 -> u64::MAX) — all via CMOV, with NO trap edges.
            assert!(
                opcodes.contains(&trunc_opcode),
                "{src_ty:?} -> I64 truncates"
            );
            assert!(
                opcodes.contains(&sub_opcode),
                "{src_ty:?} -> I64 bias-subtracts"
            );
            assert!(
                opcodes.contains(&X86Opcode::OrRR),
                "{src_ty:?} -> I64 re-adds 2^63"
            );
            assert!(
                opcodes.contains(&compare_opcode),
                "{src_ty:?} -> I64 compares"
            );
            assert!(
                opcodes.contains(&load_opcode),
                "{src_ty:?} -> I64 loads fp consts"
            );
            assert!(
                !opcodes.contains(&X86Opcode::Jcc) && !opcodes.contains(&X86Opcode::Ud2),
                "{src_ty:?} -> I64 saturating cast must not emit trap edges"
            );
            let cmov_conds: Vec<_> = insts
                .iter()
                .filter(|i| i.opcode == X86Opcode::Cmovcc)
                .map(|i| i.operands[2].clone())
                .collect();
            assert_eq!(
                cmov_conds,
                vec![
                    X86ISelOperand::CondCode(X86CondCode::AE), // x >= 2^63 -> high path
                    X86ISelOperand::CondCode(X86CondCode::B),  // x < 0     -> 0
                    X86ISelOperand::CondCode(X86CondCode::AE), // x >= 2^64 -> u64::MAX
                    X86ISelOperand::CondCode(X86CondCode::P),  // NaN       -> 0
                ],
                "{src_ty:?} -> I64 clamp cmov condition order"
            );
            // bias (2^63), 2^64, and 0.0 are the const-pool floats.
            assert_eq!(mfunc.const_pool_entries.len(), 3);
        }
    }

