    #[test]
    fn test_select_switch() {
        let (mut isel, entry) = make_empty_isel();
        let b1 = Block(1);
        let b2 = Block(2);
        let b3 = Block(3); // default
        isel.func.ensure_block(b1);
        isel.func.ensure_block(b2);
        isel.func.ensure_block(b3);
        define_vreg(&mut isel, Value(0), Type::I64);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Switch {
                    cases: vec![(1, b1), (2, b2)],
                    default: b3,
                },
                args: vec![Value(0)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        // For 2 cases: CMP + Jcc + CMP + Jcc + JMP = 5 instructions
        assert_eq!(insts.len(), 5);
        assert_eq!(insts[0].opcode, X86Opcode::CmpRI);
        assert_eq!(insts[1].opcode, X86Opcode::Jcc);
        assert_eq!(insts[2].opcode, X86Opcode::CmpRI);
        assert_eq!(insts[3].opcode, X86Opcode::Jcc);
        assert_eq!(insts[4].opcode, X86Opcode::Jmp);

        // Verify successors include all targets + default
        let succs = &mfunc.blocks[&entry].successors;
        assert!(succs.contains(&b1));
        assert!(succs.contains(&b2));
        assert!(succs.contains(&b3));
    }

    #[test]
    fn test_emit_x86_jump_table_dense_sequence() {
        let (mut isel, entry) = make_empty_isel();
        // 5 dense case values 10..=14 -> targets b1..b5, default b6.
        let targets = [Block(1), Block(2), Block(3), Block(4), Block(5)];
        let default = Block(6);
        for b in targets.iter().chain(std::iter::once(&default)) {
            isel.func.ensure_block(*b);
        }
        let sel = X86ISelOperand::VReg(isel.new_vreg(RegClass::Gpr64));
        let cases: Vec<(i64, Block)> = (0..5).map(|i| (10 + i as i64, targets[i])).collect();

        assert!(isel.emit_x86_jump_table(&cases, &sel, default, entry));

        // Entry block: mov norm,sel ; sub norm,min ; cmp norm,range ; ja default ; jmp in_range.
        let ent = &isel.func.blocks[&entry].insts;
        assert_eq!(ent.len(), 5);
        assert_eq!(ent[0].opcode, X86Opcode::MovRR);
        assert_eq!(ent[1].opcode, X86Opcode::SubRI);
        assert_eq!(ent[2].opcode, X86Opcode::CmpRI);
        assert_eq!(ent[3].opcode, X86Opcode::Jcc);
        // The bounds-check branch MUST be unsigned-above (A), never signed (G).
        assert!(matches!(
            ent[3].operands[0],
            X86ISelOperand::CondCode(X86CondCode::A)
        ));
        assert_eq!(ent[4].opcode, X86Opcode::Jmp);

        // Side-table: one dense entry, min=10, targets in order (no holes).
        assert_eq!(isel.func.jump_tables.len(), 1);
        assert_eq!(isel.func.jump_tables[0].min_val, 10);
        assert_eq!(isel.func.jump_tables[0].targets, targets.to_vec());

        // in_range block: lea(JTI 0) ; mov [base+norm*8] ; add ; jmp *reg.
        let in_range = *isel
            .func
            .blocks
            .keys()
            .find(|b| {
                isel.func.blocks[b]
                    .insts
                    .iter()
                    .any(|i| i.opcode == X86Opcode::JmpR)
            })
            .expect("in_range dispatch block");
        let ir = &isel.func.blocks[&in_range].insts;
        assert_eq!(ir.len(), 4);
        assert_eq!(ir[0].opcode, X86Opcode::LeaRip);
        assert!(matches!(
            ir[0].operands[1],
            X86ISelOperand::JumpTableIndex(0)
        ));
        // 8-byte signed delta load: MovRMSib(scale=8) — proven 64-bit scaled load.
        assert_eq!(ir[1].opcode, X86Opcode::MovRMSib);
        assert!(matches!(
            &ir[1].operands[1],
            X86ISelOperand::SibMemAddr {
                scale: 8,
                disp: 0,
                ..
            }
        ));
        assert_eq!(ir[2].opcode, X86Opcode::AddRR);
        assert_eq!(ir[3].opcode, X86Opcode::JmpR);

        // in_range successors = the DISTINCT dense targets. This case is dense
        // with NO holes, so `default` is NOT reachable from the JmpR (it is only
        // reached via the bounds-check JA in the entry block).
        let succ = &isel.func.blocks[&in_range].successors;
        for b in targets.iter() {
            assert!(succ.contains(b), "missing successor {b:?}");
        }
        assert!(
            !succ.contains(&default),
            "hole-free dense table: default is not a JmpR successor"
        );
        assert_eq!(succ.len(), targets.len());
    }

    #[test]
    fn test_emit_x86_jump_table_declines_wide_range_no_emit() {
        let (mut isel, entry) = make_empty_isel();
        let a = Block(1);
        let b = Block(2);
        let default = Block(3);
        isel.func.ensure_block(a);
        isel.func.ensure_block(b);
        isel.func.ensure_block(default);
        let sel = X86ISelOperand::VReg(isel.new_vreg(RegClass::Gpr64));
        // Span exceeds i32 -> decline (BST/linear handles it); NOTHING emitted.
        let cases = vec![(0i64, a), (i64::from(i32::MAX) + 100, b)];
        assert!(!isel.emit_x86_jump_table(&cases, &sel, default, entry));
        assert!(
            isel.func.blocks[&entry].insts.is_empty(),
            "a declined jump table must push no instructions (fail-safe)"
        );
        assert!(isel.func.jump_tables.is_empty());
    }

    #[test]
    fn test_select_switch_deduplicates_shared_case_and_default_successor() {
        let (mut isel, entry) = make_empty_isel();
        let shared = Block(1);
        let other = Block(2);
        isel.func.ensure_block(shared);
        isel.func.ensure_block(other);
        define_vreg(&mut isel, Value(0), Type::I64);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Switch {
                    cases: vec![(0, shared), (1, other)],
                    default: shared,
                },
                args: vec![Value(0)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        assert_eq!(
            mfunc.blocks[&entry].successors,
            vec![shared, other],
            "successor metadata is a set even when switch outcomes converge"
        );
    }

    #[test]
    fn test_select_switch_wide_case_value_materializes_register_compare() {
        // Regression for bug #54/#56 (wide switch constants): an x86 `CMP r64, imm`
        // only encodes a 32-bit SIGN-EXTENDED immediate, so a case value outside
        // the signed i32 range cannot be a direct `CmpRI` operand without silently
        // truncating to its low 32 bits (the high bits would differ — `if x == BIG`
        // would compare the wrong value). A wide case value must be materialized
        // into a register (`MovRI`) and compared register-to-register (`CmpRR`).
        let (mut isel, entry) = make_empty_isel();
        let b1 = Block(1);
        let b2 = Block(2);
        let b3 = Block(3); // default
        isel.func.ensure_block(b1);
        isel.func.ensure_block(b2);
        isel.func.ensure_block(b3);
        define_vreg(&mut isel, Value(0), Type::I64);

        // Case 0 fits in i32 (compact `CmpRI`); the second case value
        // 0x7777_8888_9999_FFAA exceeds i32 and must use `MovRI` + `CmpRR`.
        let wide: i64 = 0x7777_8888_9999_FFAA;
        assert!(
            i32::try_from(wide).is_err(),
            "test value must exceed i32 range"
        );
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Switch {
                    cases: vec![(1, b1), (wide, b2)],
                    default: b3,
                },
                args: vec![Value(0)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        // Case 1 (fits i32): CmpRI + Jcc. Case wide: MovRI + CmpRR + Jcc. Then JMP.
        assert_eq!(insts[0].opcode, X86Opcode::CmpRI);
        assert_eq!(insts[1].opcode, X86Opcode::Jcc);
        assert_eq!(insts[2].opcode, X86Opcode::MovRI);
        // The materialized immediate is the FULL 64-bit case value (not truncated).
        assert_eq!(insts[2].operands[1], X86ISelOperand::Imm(wide));
        assert_eq!(insts[3].opcode, X86Opcode::CmpRR);
        assert_eq!(insts[4].opcode, X86Opcode::Jcc);
        assert_eq!(insts[5].opcode, X86Opcode::Jmp);

        let succs = &mfunc.blocks[&entry].successors;
        assert!(succs.contains(&b1));
        assert!(succs.contains(&b2));
        assert!(succs.contains(&b3));
    }

    #[test]
    fn test_select_switch_narrow_selector_zero_extends_before_compare() {
        // Regression for bug #55: a narrow (I8) discriminant selector is loaded
        // with a partial-width `movb` that leaves the GPR's high bits undefined,
        // but the `CmpRI` is encoded at full width. The selector MUST be
        // zero-extended (Movzx) before the per-case compares, or the compare
        // tests garbage high bits and never matches a case. A wide (I64) selector
        // needs no extension (see `test_select_switch`).
        let (mut isel, entry) = make_empty_isel();
        let b1 = Block(1);
        let b2 = Block(2);
        let b3 = Block(3); // default
        isel.func.ensure_block(b1);
        isel.func.ensure_block(b2);
        isel.func.ensure_block(b3);
        define_vreg(&mut isel, Value(0), Type::I8);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Switch {
                    cases: vec![(0, b1), (1, b2)],
                    default: b3,
                },
                args: vec![Value(0)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        // A zero-extend (Movzx) precedes the CMP+Jcc+CMP+Jcc+JMP sequence.
        assert_eq!(insts[0].opcode, X86Opcode::Movzx);
        assert_eq!(insts[1].opcode, X86Opcode::CmpRI);
        assert_eq!(insts[2].opcode, X86Opcode::Jcc);
        assert_eq!(insts[3].opcode, X86Opcode::CmpRI);
        assert_eq!(insts[4].opcode, X86Opcode::Jcc);
        assert_eq!(insts[5].opcode, X86Opcode::Jmp);
        // The two compares read the SAME zero-extended selector, not the raw I8.
        assert_eq!(insts[1].operands[0], insts[3].operands[0]);
        assert_eq!(insts[1].operands[0], insts[0].operands[0]);
    }

