    #[test]
    fn test_select_array_gep_uses_lea_add_for_sib_scale_plus_one_strides() {
        for (elem_size, expected_scale) in [(3, 2), (5, 4), (9, 8)] {
            let (mut isel, entry) = make_empty_isel();
            define_vreg(&mut isel, Value(0), Type::I64);
            define_vreg(&mut isel, Value(1), Type::I64);

            isel.select_instruction(
                &Instruction {
                    opcode: Opcode::ArrayGep {
                        elem_ty: Type::Array(Box::new(Type::I8), elem_size),
                    },
                    args: vec![Value(0), Value(1)],
                    results: vec![Value(2)],
                },
                entry,
            )
            .unwrap();

            let mfunc = isel.finalize();
            let insts = &mfunc.blocks[&entry].insts;
            assert_eq!(insts.len(), 2, "{elem_size}");
            assert_eq!(insts[0].opcode, X86Opcode::LeaSib, "{elem_size}");
            assert_eq!(
                insts[0].operands,
                vec![
                    X86ISelOperand::VReg(VReg::new(2, RegClass::Gpr64)),
                    X86ISelOperand::SibMemAddr {
                        base: Box::new(X86ISelOperand::VReg(VReg::new(0, RegClass::Gpr64))),
                        index: Box::new(X86ISelOperand::VReg(VReg::new(1, RegClass::Gpr64))),
                        scale: expected_scale,
                        disp: 0,
                    },
                ],
                "{elem_size}"
            );
            assert_eq!(insts[1].opcode, X86Opcode::AddRR, "{elem_size}");
            assert_eq!(
                insts[1].operands,
                vec![
                    X86ISelOperand::VReg(VReg::new(2, RegClass::Gpr64)),
                    X86ISelOperand::VReg(VReg::new(2, RegClass::Gpr64)),
                    X86ISelOperand::VReg(VReg::new(1, RegClass::Gpr64)),
                ],
                "{elem_size}"
            );
            assert!(
                insts.iter().all(|inst| inst.opcode != X86Opcode::ImulRRI),
                "{elem_size}"
            );
        }
    }

