    #[test]
    fn test_x86_set_stack_slots_preserves_metadata() {
        use trust_cg_ir::function::{StackSlotAllocationKind, StackSlotSizeSource};

        let (mut isel, _entry) = make_empty_isel();
        isel.set_stack_slots(vec![
            StackSlotInfo::new(8, 8),
            StackSlotInfo::new_dynamic_with_unit(StackSlotSizeSource::Value(42), 4, 16),
        ]);

        let mfunc = isel.finalize();
        assert_eq!(mfunc.stack_slots.len(), 2);
        assert_eq!(mfunc.stack_slots[0], StackSlotInfo::new(8, 8));
        assert_eq!(mfunc.stack_slots[1].size, 4);
        assert_eq!(mfunc.stack_slots[1].align, 16);
        assert_eq!(
            mfunc.stack_slots[1].allocation,
            StackSlotAllocationKind::RuntimeSized {
                size_source: StackSlotSizeSource::Value(42)
            }
        );
    }

