    #[test]
    fn select_guard_div_zero_emits_proof_only_carrier() {
        // Sentinel S5: GuardDivZero now lowers to the proof-only carrier
        // `TrapDivZeroExact [divisor]` (the x86 mirror of AArch64's
        // `TrapDivZeroIfZero`). The eager TEST/Jcc(E)/UD2 runtime check is produced
        // later by the codegen pipeline's carrier expansion, not by ISel.
        let (mut isel, entry) = make_empty_isel();
        define_vreg(&mut isel, Value(0), Type::I64);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::GuardDivZero { obligation: None },
                args: vec![Value(0)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let entry_block = &mfunc.blocks[&entry];
        assert_eq!(
            entry_block.insts.len(),
            1,
            "exactly one carrier, no eager check"
        );
        let carrier = &entry_block.insts[0];
        assert_eq!(carrier.opcode, X86Opcode::TrapDivZeroExact);
        assert_eq!(
            carrier.operands,
            vec![X86ISelOperand::VReg(VReg::new(0, RegClass::Gpr64))]
        );
        // No obligation supplied => nothing recorded; the kernel keeps it (fail-safe).
        assert!(mfunc.guard_obligations.is_empty());
        // No synthetic trap edge at ISel time.
        assert!(entry_block.successors.is_empty());
    }

    /// Sentinel S5: when the producer supplies a discharged obligation id (synthesized from a genuine
    /// `DivNonZero` proof), ISel records it keyed by the SAME single-operand fingerprint the kernel
    /// computes from the emitted carrier (`X86GuardTarget::operand_identity` over `[divisor]`).
    #[test]
    fn select_guard_div_zero_threads_obligation_by_fingerprint() {
        let (mut isel, entry) = make_empty_isel();
        define_vreg(&mut isel, Value(0), Type::I64);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::GuardDivZero {
                    obligation: Some(42),
                },
                args: vec![Value(0)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let entry_block = &mfunc.blocks[&entry];
        assert_eq!(entry_block.insts.len(), 1);
        assert_eq!(entry_block.insts[0].opcode, X86Opcode::TrapDivZeroExact);

        // The kind-folded binding key the kernel will recompute from the carrier operand [divisor].
        let expected_fp = trust_cg_ir::fingerprint_for_kind(
            trust_cg_ir::GuardKind::DivZero,
            &[trust_cg_ir::GuardOperandRef::Reg(0)],
        );
        assert_eq!(mfunc.guard_obligations.get(&expected_fp), Some(&42));
        assert_eq!(mfunc.guard_obligations.len(), 1);

        // SOUNDNESS (Item B): the same single operand under GuardKind::NullPtr keys a DISTINCT
        // binding, so a DivZero obligation cannot be picked up by a NullPtr carrier over the same
        // vreg (collision closed).
        let null_fp = trust_cg_ir::fingerprint_for_kind(
            trust_cg_ir::GuardKind::NullPtr,
            &[trust_cg_ir::GuardOperandRef::Reg(0)],
        );
        assert_ne!(expected_fp, null_fp, "the kind must change the binding key");
        assert!(!mfunc.guard_obligations.contains_key(&null_fp));
    }

    #[test]
    fn select_guard_null_emits_proof_only_carrier() {
        // Sentinel S5: GuardNull now lowers to the proof-only carrier
        // `TrapNullIfZeroExact [ptr]` (the x86 mirror of AArch64's
        // `TrapNullIfZero`). The eager TEST/Jcc(E)/UD2 runtime check is produced
        // later by the codegen pipeline's carrier expansion, not by ISel.
        let (mut isel, entry) = make_empty_isel();
        define_vreg(&mut isel, Value(0), Type::I64);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::GuardNull { obligation: None },
                args: vec![Value(0)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let entry_block = &mfunc.blocks[&entry];
        assert_eq!(
            entry_block.insts.len(),
            1,
            "exactly one carrier, no eager check"
        );
        let carrier = &entry_block.insts[0];
        assert_eq!(carrier.opcode, X86Opcode::TrapNullIfZeroExact);
        assert_eq!(
            carrier.operands,
            vec![X86ISelOperand::VReg(VReg::new(0, RegClass::Gpr64))]
        );
        // No obligation supplied => nothing recorded; the kernel keeps it (fail-safe).
        assert!(mfunc.guard_obligations.is_empty());
        // No synthetic trap edge at ISel time.
        assert!(entry_block.successors.is_empty());
    }

    /// Sentinel S5: when the producer supplies a discharged obligation id (synthesized from a genuine
    /// `NotNull` proof), ISel records it keyed by the SAME single-operand fingerprint the kernel
