    #[test]
    fn test_select_bitcast_same_class_and_cross_class_copies() {
        let (mut isel, entry) = make_empty_isel();
        define_vreg(&mut isel, Value(0), Type::I64);
        define_vreg(&mut isel, Value(2), Type::F64);
        define_vreg(&mut isel, Value(4), Type::F64);
        define_vreg(&mut isel, Value(6), Type::I32);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Bitcast { to_ty: Type::I64 },
                args: vec![Value(0)],
                results: vec![Value(1)],
            },
            entry,
        )
        .unwrap();
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Bitcast { to_ty: Type::F64 },
                args: vec![Value(2)],
                results: vec![Value(3)],
            },
            entry,
        )
        .unwrap();
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Bitcast { to_ty: Type::I64 },
                args: vec![Value(4)],
                results: vec![Value(5)],
            },
            entry,
        )
        .unwrap();
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Bitcast { to_ty: Type::F32 },
                args: vec![Value(6)],
                results: vec![Value(7)],
            },
            entry,
        )
        .unwrap();

        let insts = &isel.func.blocks[&entry].insts;
        assert_eq!(insts[0].opcode, X86Opcode::MovRR);
        assert_eq!(insts[1].opcode, X86Opcode::MovsdRR);
        assert_eq!(insts[2].opcode, X86Opcode::MovqFromXmm);
        assert_eq!(insts[3].opcode, X86Opcode::MovdToXmm);
        assert_eq!(isel.value_types[&Value(1)], Type::I64);
        assert_eq!(isel.value_types[&Value(3)], Type::F64);
        assert_eq!(isel.value_types[&Value(5)], Type::I64);
        assert_eq!(isel.value_types[&Value(7)], Type::F32);
    }

    #[test]
    fn test_select_select_i64_and_i32_use_cmov() {
        for (ty, copy_opcode, cmov_opcode) in [
            (Type::I64, X86Opcode::MovRR, X86Opcode::Cmovcc),
            (Type::I32, X86Opcode::MovRR32, X86Opcode::Cmovcc32),
        ] {
            let (mut isel, entry) = make_empty_isel();
            define_vreg(&mut isel, Value(0), Type::I64);
            define_vreg(&mut isel, Value(1), ty.clone());
            define_vreg(&mut isel, Value(2), ty.clone());

            isel.select_instruction(
                &Instruction {
                    opcode: Opcode::Select {
                        cond: IntCC::NotEqual,
                    },
                    args: vec![Value(0), Value(1), Value(2)],
                    results: vec![Value(3)],
                },
                entry,
            )
            .unwrap();

            let insts = &isel.func.blocks[&entry].insts;
            assert_eq!(
                insts.iter().map(|inst| inst.opcode).collect::<Vec<_>>(),
                vec![copy_opcode, X86Opcode::CmpRI, cmov_opcode]
            );
            assert_eq!(insts[1].operands[1], X86ISelOperand::Imm(0));
            assert_eq!(
                insts[2].operands[2],
                X86ISelOperand::CondCode(X86CondCode::NE)
            );
            assert_eq!(isel.value_types[&Value(3)], ty);
        }
    }

    #[test]
    fn test_select_select_v128_mask_condition_uses_ptest_for_scalar_cmov() {
        let (mut isel, entry) = make_empty_isel();
        let mask = define_vreg(&mut isel, Value(0), Type::V128);
        let true_reg = define_vreg(&mut isel, Value(1), Type::I32);
        let false_reg = define_vreg(&mut isel, Value(2), Type::I32);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Select {
                    cond: IntCC::NotEqual,
                },
                args: vec![Value(0), Value(1), Value(2)],
                results: vec![Value(3)],
            },
            entry,
        )
        .unwrap();

        let insts = &isel.func.blocks[&entry].insts;
        assert_eq!(
            insts.iter().map(|inst| inst.opcode).collect::<Vec<_>>(),
            vec![X86Opcode::MovRR32, X86Opcode::Ptest, X86Opcode::Cmovcc32,],
            "V128 mask scalar select should test the vector predicate directly: {insts:?}"
        );
        assert_eq!(insts[0].operands[1], X86ISelOperand::VReg(false_reg));
        assert_eq!(insts[1].operands[0], X86ISelOperand::VReg(mask));
        assert_eq!(insts[1].operands[1], X86ISelOperand::VReg(mask));
        assert_eq!(insts[2].operands[0], insts[0].operands[0]);
        assert_eq!(insts[2].operands[1], X86ISelOperand::VReg(true_reg));
        assert_eq!(
            insts[2].operands[2],
            X86ISelOperand::CondCode(X86CondCode::NE)
        );
        assert_eq!(isel.value_types[&Value(3)], Type::I32);
    }

