    #[test]
    fn test_select_select_normalizes_narrow_conditions_before_cmp() {
        for (cond_ty, expected_opcodes) in [
            (
                Type::B1,
                vec![
                    X86Opcode::MovRR32,
                    X86Opcode::Movzx,
                    X86Opcode::AndRI,
                    X86Opcode::CmpRI,
                    X86Opcode::Cmovcc32,
                ],
            ),
            (
                Type::I8,
                vec![
                    X86Opcode::MovRR32,
                    X86Opcode::Movzx,
                    X86Opcode::CmpRI,
                    X86Opcode::Cmovcc32,
                ],
            ),
            (
                Type::I16,
                vec![
                    X86Opcode::MovRR32,
                    X86Opcode::MovzxW,
                    X86Opcode::CmpRI,
                    X86Opcode::Cmovcc32,
                ],
            ),
        ] {
            let (mut isel, entry) = make_empty_isel();
            let cond = define_vreg(&mut isel, Value(0), cond_ty.clone());
            define_vreg(&mut isel, Value(1), Type::I32);
            define_vreg(&mut isel, Value(2), Type::I32);

            isel.select_instruction(
                &Instruction {
                    opcode: Opcode::Select {
                        cond: IntCC::NotEqual,
                    },
                    args: vec![Value(0), Value(1), Value(2)],
                    results: vec![Value(3)],
                },
                entry,
            )
            .unwrap();

            let insts = &isel.func.blocks[&entry].insts;
            assert_eq!(
                insts.iter().map(|inst| inst.opcode).collect::<Vec<_>>(),
                expected_opcodes,
                "unexpected select lowering for {cond_ty:?}: {insts:?}"
            );
            assert_eq!(insts[1].operands[1], X86ISelOperand::VReg(cond));
            assert_ne!(insts[1].operands[0], X86ISelOperand::VReg(cond));
            let cmp_index = if cond_ty == Type::B1 {
                assert_eq!(insts[2].operands[0], insts[1].operands[0]);
                assert_eq!(insts[2].operands[1], insts[1].operands[0]);
                assert_eq!(insts[2].operands[2], X86ISelOperand::Imm(1));
                3
            } else {
                2
            };
            assert_eq!(
                insts[cmp_index].operands[0],
                insts[cmp_index - 1].operands[0]
            );
            assert_eq!(insts[cmp_index].operands[1], X86ISelOperand::Imm(0));
        }
    }

