    #[test]
    fn test_select_select_rejects_unsupported_payload_shapes() {
        for ty in [Type::F16, Type::V128, Type::Struct(vec![Type::I64])] {
            let (mut isel, entry) = make_empty_isel();
            define_vreg(&mut isel, Value(0), Type::B1);
            define_vreg(&mut isel, Value(1), ty.clone());
            define_vreg(&mut isel, Value(2), ty.clone());

            let err = isel
                .select_instruction(
                    &Instruction {
                        opcode: Opcode::Select {
                            cond: IntCC::NotEqual,
                        },
                        args: vec![Value(0), Value(1), Value(2)],
                        results: vec![Value(3)],
                    },
                    entry,
                )
                .unwrap_err();
            assert!(
                err.to_string().contains("Select NotEqual"),
                "Select {ty:?} payload should fail closed with typed diagnostic, got: {err}"
            );
        }
    }

    fn assert_binary_not_logic_lowers(
        opcode: Opcode,
        ty: Type,
        combine_opcode: X86Opcode,
        expected_mask: Option<i64>,
    ) {
        let (mut isel, entry) = make_empty_isel();
        let lhs = define_vreg(&mut isel, Value(0), ty.clone());
        let rhs = define_vreg(&mut isel, Value(1), ty.clone());

        isel.select_instruction(
            &Instruction {
                opcode,
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();

        let insts = &isel.func.blocks[&entry].insts;
        let expected_opcodes = if expected_mask.is_some() {
            vec![
                X86Opcode::Not,
                combine_opcode,
                X86Opcode::MovRI,
                X86Opcode::AndRR,
            ]
        } else {
            vec![X86Opcode::Not, combine_opcode]
        };
        assert_eq!(
            insts.iter().map(|inst| inst.opcode).collect::<Vec<_>>(),
            expected_opcodes,
            "unexpected binary-not lowering for {ty:?}: {insts:?}"
        );
        assert_eq!(insts[0].operands[1], X86ISelOperand::VReg(rhs));
        assert_eq!(insts[1].operands[1], X86ISelOperand::VReg(lhs));
        assert_eq!(insts[1].operands[2], insts[0].operands[0]);

        if let Some(mask) = expected_mask {
            assert_eq!(insts[2].operands[1], X86ISelOperand::Imm(mask));
            assert_eq!(insts[3].operands[1], insts[1].operands[0]);
            assert_eq!(insts[3].operands[2], insts[2].operands[0]);
        }
        assert_eq!(isel.value_types[&Value(2)], ty);
    }

    #[test]
    fn test_bandnot_and_bornot_lower_supported_widths() {
        for (ty, expected_mask) in [
            (Type::B1, Some(1)),
            (Type::I8, Some(0xff)),
            (Type::I16, Some(0xffff)),
            (Type::I32, None),
            (Type::I64, None),
        ] {
            assert_binary_not_logic_lowers(
                Opcode::BandNot,
                ty.clone(),
                X86Opcode::AndRR,
                expected_mask,
            );
            assert_binary_not_logic_lowers(Opcode::BorNot, ty, X86Opcode::OrRR, expected_mask);
        }
    }

    #[test]
    fn test_bandnot_and_bornot_preserve_source_and_result_aliasing() {
        for (opcode, combine_opcode) in [
            (Opcode::BandNot, X86Opcode::AndRR),
            (Opcode::BorNot, X86Opcode::OrRR),
        ] {
            let (mut isel, entry) = make_empty_isel();
            let original = define_vreg(&mut isel, Value(0), Type::I64);
            define_vreg(&mut isel, Value(1), Type::I64);
            let original_op = X86ISelOperand::VReg(original);

            isel.select_instruction(
                &Instruction {
                    opcode,
                    args: vec![Value(0), Value(0)],
                    results: vec![Value(0)],
                },
                entry,
            )
            .unwrap();

            let insts = &isel.func.blocks[&entry].insts;
            assert_eq!(insts[0].opcode, X86Opcode::Not);
            assert_eq!(insts[0].operands[1], original_op);
            assert_eq!(insts[1].opcode, combine_opcode);
            assert_eq!(insts[1].operands[1], original_op);
            assert_eq!(insts[1].operands[2], insts[0].operands[0]);
            assert_ne!(isel.value_map[&Value(0)], original_op);
        }
    }

    #[test]
    fn test_bandnot_and_bornot_reject_unsupported_types() {
        for ty in [
            Type::I128,
            Type::F32,
            Type::F64,
            Type::V128,
            Type::Struct(vec![Type::I32]),
            Type::Array(Box::new(Type::I8), 2),
        ] {
            let (mut isel, entry) = make_empty_isel();
            define_vreg(&mut isel, Value(0), ty.clone());
            define_vreg(&mut isel, Value(1), ty);

            let err = isel
                .select_instruction(
                    &Instruction {
                        opcode: Opcode::BandNot,
                        args: vec![Value(0), Value(1)],
                        results: vec![Value(2)],
                    },
                    entry,
                )
                .unwrap_err();

            assert!(
                matches!(
                    err,
                    X86ISelError::UnsupportedBinaryNotType { op: "BandNot", .. }
                ),
                "unexpected BandNot unsupported-type error: {err:?}"
            );
            assert!(isel.func.blocks[&entry].insts.is_empty());
        }
    }

    #[test]
    fn test_bandnot_and_bornot_reject_type_mismatch() {
        let (mut isel, entry) = make_empty_isel();
        define_vreg(&mut isel, Value(0), Type::I64);
        define_vreg(&mut isel, Value(1), Type::I32);

        let err = isel
            .select_instruction(
                &Instruction {
                    opcode: Opcode::BorNot,
                    args: vec![Value(0), Value(1)],
                    results: vec![Value(2)],
                },
                entry,
            )
            .unwrap_err();

        assert!(matches!(
            err,
            X86ISelError::BinaryNotTypeMismatch {
                op: "BorNot",
                lhs_ty: Type::I64,
                rhs_ty: Type::I32,
            }
        ));
        assert!(isel.func.blocks[&entry].insts.is_empty());
    }

    // -----------------------------------------------------------------------
    // Unsupported opcode error (regression test for #276)
    // -----------------------------------------------------------------------

    #[test]
    fn test_unsupported_opcode_returns_error() {
        // Opcodes not yet handled by x86-64 ISel must produce an error,
        // not a silent NOP that causes miscompilation. (Resume is now handled
        // by the EH x86 Lane 1 arms; GuardOverflow is still routed to the
        // catch-all fail-closed path.)
        let unsupported_opcodes: Vec<Opcode> = vec![Opcode::GuardOverflow {
            op_tag: 0,
            obligation: None,
        }];

        for opcode in unsupported_opcodes {
            let (mut isel, entry) = make_empty_isel();
            // Some opcodes need defined values in args
            define_vreg(&mut isel, Value(0), Type::I64);
            define_vreg(&mut isel, Value(1), Type::I64);

            let result = isel.select_instruction(
                &Instruction {
                    opcode: opcode.clone(),
                    args: vec![Value(0), Value(1)],
                    results: vec![Value(2)],
                },
                entry,
            );

            assert!(
                result.is_err(),
                "Expected error for unsupported opcode {:?}, but got Ok",
                opcode,
            );
            let err = result.unwrap_err();
            let msg = err.to_string();
            assert!(
                msg.contains("unsupported opcode"),
                "Error message for {:?} should mention 'unsupported opcode', got: {}",
                opcode,
                msg,
            );
        }
    }

    #[test]
    fn test_unsupported_opcode_error_message_contains_opcode_name() {
        let (mut isel, entry) = make_empty_isel();

        let result = isel.select_instruction(
            &Instruction {
                opcode: Opcode::Resume,
                args: vec![],
                results: vec![],
            },
            entry,
        );

        let err = result.unwrap_err();
        let msg = err.to_string();
        assert!(
            msg.contains("Resume"),
            "Error message should name the unsupported opcode, got: {}",
            msg,
        );
    }

    // -----------------------------------------------------------------------
    // Stack-passed arguments
