    #[test]
    fn test_lower_call_ay_contains4_masked_six_i32_args_register_only() {
        // ay SAT batch helper shape: contains4_masked(lane0..lane3, literal, valid_mask) -> i32.
        // SysV x86-64 must keep this scalar baseline in registers:
        // EDI, ESI, EDX, ECX, R8D, R9D -> EAX, with no caller stack traffic.
        let sig = Signature {
            params: vec![],
            returns: vec![Type::I32],
        };
        let mut isel = X86InstructionSelector::new("ay_batch_contains4_caller".to_string(), sig);
        let entry = Block(0);
        isel.func.ensure_block(entry);

        for i in 0..6u32 {
            define_vreg(&mut isel, Value(i), Type::I32);
        }
        isel.seed_value_types(&HashMap::from([(Value(6), Type::I32)]));

        isel.lower_call(
            "ay_sat_contains4_masked",
            &Instruction {
                opcode: Opcode::Call {
                    name: "ay_sat_contains4_masked".to_string(),
                },
                args: (0..6).map(Value).collect(),
                results: vec![Value(6)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;

        // 6 register moves + CALL + return copy. No SUB/ADD RSP or stack stores.
        assert_eq!(insts.len(), 8);
        assert!(
            insts.iter().all(|inst| !matches!(
                (&inst.opcode, inst.operands.first()),
                (X86Opcode::SubRI | X86Opcode::AddRI, Some(X86ISelOperand::PReg(reg)))
                    if *reg == RSP
            )),
            "six-i32 ay helper call should not adjust RSP: {insts:?}"
        );
        assert!(
            insts.iter().all(|inst| inst.opcode != X86Opcode::MovMR32),
            "six-i32 ay helper call should not spill outgoing args to stack: {insts:?}"
        );

        let expected_arg_regs = [EDI, ESI, EDX, ECX, R8D, R9D];
        for (idx, expected) in expected_arg_regs.iter().enumerate() {
            assert_eq!(insts[idx].opcode, X86Opcode::MovRR32);
            assert_eq!(insts[idx].operands[0], X86ISelOperand::PReg(*expected));
        }

        assert_eq!(insts[6].opcode, X86Opcode::Call);
        assert_eq!(
            insts[6].operands[0],
            X86ISelOperand::Symbol("ay_sat_contains4_masked".to_string())
        );
        assert_eq!(insts[7].opcode, X86Opcode::MovRR32);
        assert_eq!(insts[7].operands[1], X86ISelOperand::PReg(EAX));
    }

